SELECT 'moj-all-verified-judgments-review-002-chunk-159' AS batch_name,
       (SELECT count(*) FROM public.legal_documents WHERE id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"972e8276-8bbe-597e-b976-502c3a84d7a4","document_type":"judgment","category":"judicial","subcategory":"general","title":"والية -مطالبة أم بإلغاء صك وصية وإقامتها ولية على أوالدها- املدعى عليهم مجلس وصاية أقامه األب قبل وفاته وهو يف حالته املعتبرة شرعا -القدح يف األوصياء دون إثبات ذلك -الوصي مقدم يف الوالية على األم وغيرها من األقرباء -احلكم برد الدعوى.","document_number":"34223712","case_number":"33681315","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/5/27","year":"1434","subject":"والية -مطالبة أم بإلغاء صك وصية وإقامتها ولية على أوالدها- املدعى عليهم مجلس وصاية أقامه األب قبل وفاته وهو يف حالته املعتبرة شرعا -القدح يف األوصياء دون إثبات ذلك -الوصي مقدم يف الوالية على األم وغيرها من األقرباء -احلكم برد الدعوى.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/5/27 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪34223712 :‬‬\n                         ‫َر ْق ُم الدعوى‪33681315 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 342284817‬تاريخه‪1434/8/1 :‬هـ‬\n\n\n      ‫واليــة ‪ -‬مطالبــة أم بإلغــاء صــك وصيــة وإقامتهــا وليــة علــى أوالدهــا‪-‬‬\n      ‫املدعــى عليهــم مجلــس وصايــة أقامــه األب قبــل وفاتــه وهــو يف حالتــه‬\n      ‫املعتبــرة شــرعا ‪ -‬القــدح يف األوصيــاء دون إثبــات ذلــك ‪ -‬الوصــي مقــدم‬\n            ‫يف الواليــة علــى األم وغيرهــا مــن األقربــاء ‪ -‬احلكــم بــرد الدعــوى‪.‬‬\n\n\n\n      ‫قــال البهوتــي (إن وصــي األب مقــدم علــى غيــره) كشــاف القنــاع‬\n                       ‫‪ -383/8‬وانظــر‪ :‬الــكايف البــن قدامــه (‪. )251/3‬‬\n\n\n\n      ‫ادعــت أم بطلــب إلغــاء صــك الوصايــة الصــادر مــن احملكمــة علــى‬\n      ‫أوالدهــا وإقامتهــا وليــة عليهــم ‪ -‬املدعــى عليهــم أوصيــاء معينــن مــن‬\n      ‫قبــل والــد القصــر وهــو يف حالتــه املعتبــرة شــرعا ‪ -‬رفــض املدعــى عليهــم‬\n      ‫إلغــاء صــك الوصايــة ألنــه صــادر مــن والدهــم وثابــت لــدى احملكمــة‬\n      ‫بصــك شــرعي ‪ -‬حاولــت املدعيــة القــدح يف صــك الوصايــة بأنــه ال يلــزم‬\n      ‫املضــي فيــه ويجــوز العــدول عنــه للمصلحــة وأن مصلحــة القصــر أن‬\n      ‫تتولــى عليهــم أمهــم املدعيــة وذكــرت أن األوصيــاء فرطــوا يف الواليــة‬\n      ‫وتصرفــوا يف أمــوال القصــر مبــا يقــدح يف أمانتهــم ثــم طلبــت بشــكل‬\n      ‫عاجــل إثبــات رشــد أحــد القاصــرات لبلوغهــا ‪ -‬أنكــر املدعــى عليهــم‬\n      ‫التهــم التــي ذكــرت املدعيــة وذكــروا أن التهــم التــي ذكــرت املدعيــة‬\n‫‪285‬‬\n\f‫ســبق إثارتهــا مــن املدعيــة يف قضيــة ســابقة لــدى احملكمــة ولــم تســتطع‬\n‫إثباتهــا وطالبوهــا بالبينــة كمــا ذكــر املدعــى عليهــم أن وصــي األب‬\n‫مقــدم علــى األم يف الواليــة وأن والــد أوالد املدعيــة واملدعــى عليهــم‬\n‫أقــام مجلــس األوصيــاء لعلمــه أن نصيــب القصــر مــن املــال كبيــر جــد ًا‬\n‫وال تســتطيع أم األوالد القيــام بــه وال اســتثماره ولهــذا أقــام والدهــم‬\n‫مجلــس األوصيــاء ‪ -‬لــم تســتطع املدعيــة إثبــات القــدح يف املدعــى عليهــم‬\n‫وأبــرز املدعــى عليهــم أوراق ومســتندات تــدل علــى قيامهــم باســتثمار‬\n‫أمــوال القصــر بشــكل صحيــح ‪ -‬وألن وصــي األب مقــدم علــى األم‬\n‫وألن الوصيــة ثابتــة بصــك شــرعي مــن والــد أوالد املدعيــة وهــو يف‬\n‫حالتــه املعتبــرة شــرع ًا ومكتســب للقطعيــة بتصديقــه مــن محكمــة‬\n‫االســتئناف وألن مــا قدمتــه املدعيــة مــن قــدح يف املدعــى عليهــم ال يرقــى‬\n‫إلــى عــزل األوصيــاء لــذا ردت احملكمــة دعــوى املدعيــة ‪ -‬اعترضــت‬\n                      ‫املدعيــة ‪ -‬صــدق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ ).....‬القاضــي يف احملكمــة العامــة‬\n‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بالريــاض املســاعد برقــم ‪ 33681315‬وتاريــخ ‪1433/11/29‬ه ـ‬\n‫املقيــدة باحملكمــة برقــم ‪ 332140020‬وتاريــخ ‪1433/11/29‬ه ـ‬\n‫ففــي يــوم الســبت املوافــق ‪1434/02/16‬ه ـ افتتحــت اجللســة األولــى‬\n‫ا عــن مبوجــب‬  ‫الســاعة ‪ 11 : 30‬وفيهــا حضــر (‪ ).....‬بصفتــه وكي ـ ً‬\n‫الوكالــة رقــم ‪ 73002‬يف ‪1429/09/03‬ه ـ جلــد صــادر مــن كتابــة‬\n‫العــدل الثانيــة جنــوب الريــاض واملتضمنــة لــه حــق ســماع الدعــوى والــرد‬\n\n                                                                                   ‫‪286‬‬\n\f      ‫عليهــا واالقــرار واالنــكار والصلــح وطلــب اليمــن ورده وقبــول احلكــم‬\n      ‫ونفيــه واالعتــراض عليــه وطلــب متييــزه وحضــر (‪ ).....‬حلضــوره مبوجــب‬\n      ‫ا عــن ســجل مدنــي رقــم (‪).....‬‬         ‫ســجل مدنــي رقــم (‪ )....‬بصفتــه وكي ـ ً‬\n      ‫بصفتــه (‪ )....‬وولي ـ ًا عــن وابنــاء مبوجــب صــك الواليــة رقــم ‪33356475‬‬\n      ‫بتاريــخ ‪1433/7/26‬ه ـ صــادر مــن احملكمــة العامــة بالوكالــة رقــم‬\n      ‫ا عــن ســجل مدنــي‬      ‫‪ 33431602‬يف ‪1433/11/29‬ه ـ وبصفتــه وكي ـ ً‬\n      ‫رقــم (‪ )....‬بصفتــه ولي ـ ًا عــن (‪ )....‬و(‪ )....‬وابنــاء مبوجــب صــك الواليــة‬\n      ‫رقــم ‪ 33356475‬بتاريــخ ‪1433/07/26‬ه ـ صــادر مــن احملكمــة العامــة‬\n      ‫بالريــاض مبوجــب الوكالــة رقــم ‪ 33433031‬يف ‪1433/11/29‬ه ـ‬\n      ‫ا عن‬  ‫صــادره مــن كتابــة العــدل الثانيــة بجنــوب الريــاض وبصفتــه وكيـ ً‬\n      ‫(‪ )....‬ســعودي ســجل مدنــي رقــم (‪ )....‬بصفتــه وليـ ًا عــن (‪ )....‬و(‪ )....‬وابنــاء‬\n      ‫مبوجــب صــك الواليــة رقــم ‪ 33356475‬بتاريــخ ‪1433/07/26‬ه ـ صــادر‬\n      ‫مــن احملكمــة العامــة بالوكالــة رقــم يف ‪1433/11/29‬ه ـ مبوجــب‬\n      ‫الوكالــة رقــم ‪ 34115197‬يف ‪1434/01/28‬ه ـ صــادره مــن كتابــة‬\n      ‫ا عــن بصفتــه ولي ـ ًا عــن‬   ‫العــدل الثانيــة جنــوب الريــاض وبصفتــه وكي ـ ً‬\n      ‫أبنــاء مبوجــب صــك الواليــة رقــم ‪ 33356475‬بتاريــخ ‪1433/07/26‬ه ـ‬\n      ‫صــادر مــن احملكمــة العامــة بالريــاض مبوجــب الوكالــة رقــم‬\n      ‫‪ 33434106‬يف ‪1433/11/29‬ه ـ صــادر مــن كتابــة العــدل الثانيــة‬\n      ‫بجنــوب الريــاض واملتضمنــة جميعهــا (املطالبــة واقامــة الدعــاوي‬\n      ‫واملرافعــة واملدافعــة وســماع الدعــاوي والــرد عليهــا واالقــرار واالنــكار‬\n      ‫والصلــح وطلــب اليمــن ورده واالمتنــاع عنــه ) وادعــى املدعــي وكالــة‬\n      ‫قائــا أقــدم دعــواي هــذه ضــد املدعــى عليهــم املوضــح اســمائهم بعاليــه‬\n      ‫وموضــوع الدعــوى بالتفصيــل مــا يلــي حيــث إنــه قــد صــدر منكــم صــك‬\n\n\n‫‪287‬‬\n\f‫إثبــات إقامــة وصــي رقــم ‪ 33356475‬وتاريــخ ‪1433/7/26‬ه ـ واملتضمــن‬\n‫إقامــة كل مــن أوصيــاء علــى كل مــن (‪ )....‬و(‪ ).....‬وأبنــاء (‪ ).....‬رحمــه‬\n‫اهلل وحيــث إن والدهــم قــد تــويف يــوم الثالثــاء ‪1433/11/9‬ه وحيــث إن‬\n‫والدتهــم هــي مــن ترعــى مصاحلهــم والقيــام علــى شــؤونهم مبوجــب صــك‬\n‫اإلعالــة رقــم ‪ 31/100/338‬وتاريــخ ‪1430/8/12‬ه ـ وحيــث إنهــا أرئــف‬\n‫بحالهــم وأكثــر حرص ـ ًا علــى مصاحلهــم وخشــية وقــوع الضــرر عليهــم‬\n‫مــن تنصيــب هــؤالء أوصيــاء يف حــال وفــاة والدهــم أطلــب احلكــم بإلغــاء‬\n‫صــك الوصايــة املذكــور أعــاه وإقامــة موكلتــي (والــدة األبنــاء) وليــة‬\n‫عليهــم هــذه دعــواي وبعــرض ذلــك علــى املدعــى عليــه وكالــة أجــاب‬\n‫مبــا يلــي‪ -1 :‬ســبق وأن عـ ّـن الشــيخ (‪ ).....‬يف حياتــه مجلس ـ ًا للواليــة‬\n‫ـاء علــى وصيتــه املثبتــة برقــم ‪3339658‬‬     ‫علــى القصــر مــن أبنائــه بنـ ً‬\n‫ـاء عليهــا صــدر صــك شــرعي مــن مكتــب‬        ‫وتاريــخ ‪1433/1/22‬ه ـ وبنـ ً‬\n‫فضيلتكــم برقــم ‪ 33356475‬وتاريــخ ‪1433/7/26‬ه ـ بإقامــة كل مــن‬\n‫‪ :‬أبنــاء الشــيخ(‪ ).....‬أوصيــاء علــى القصــر يرعــون شــؤونهم ومصاحلهــم‬\n‫وحيــث إن هــذا الصــك الصــادر مــن فضيلتكم ســاري املفعــول حتى بعد‬\n‫وفــاة الشــيخ (‪ ).....‬كمــا جــاء يف حاشــيتكم علــى خطــاب الشــيخ (‪)....‬‬\n‫القاضــي يف هــذه احملكمــة فــا وجــه للمطالبــة بإلغائــه ال شــرع ًا وال‬\n‫نظامــا ً‪ -2‬مــن الثابــت عنــد فقهــاء احلنابلــة وهــو املعمــول بــه يف محاكــم‬\n‫القصــر واإلشــراف‬\n                 ‫ّ‬     ‫أن وصـ ّـي األب مقــدم علــى األم يف رعايــة‬\n                                                                 ‫اململكــة َّ‬\n‫عليهــم قــال ابــن قدامــة ‪ « :‬ويتولــى األب مــال الصبــي واملجنــون ألنهــا‬\n‫واليــة علــى الصغيــر فقــدم فيهــا األب كواليــة النــكاح ثــم وصيــة‬\n‫بعــده ألنــه نائبــه فأشــبه وكيلــه يف احليــاة « الــكايف (‪ ،)251/3‬وقــال‬\n‫البهوتــي « ثــم تثبــت الواليــة علــى صغيــر ومجنــون بعــد األب لوصيــة‬\n\n\n                                                                                     ‫‪288‬‬\n\f      ‫العــدل « كشــاف القنــاع (‪ )383/8‬لذلــك كلــه نأمــل التكــرم بإمضــاء‬\n      ‫الصــك الواليــة الصــادر مــن مكتــب فضيلتكــم برقــم ‪33356475‬‬\n      ‫وتاريــخ ‪1433/7/26‬ه ـ واحلكــم بــرد الدعــوى كونهــا تأتــي مخالف ـ ًا‬\n      ‫ملــا عليــه الوصيــة وملــا قــرره فقــاء املذهــب وبعــرض ذلــك علــى املدعــي‬\n      ‫وكالــة أجــاب أطلــب مهلــة للــرد علــى دفــع املدعــى عليــه وكالــة هكــذا‬\n      ‫أجــاب ثــم يف يــوم الثالثــاء ‪1434/04/16‬ه ـ افتتحــت اجللســة الثانيــة‬\n      ‫الســاعة ‪ 08:30‬وفيهــا حضــر املدعــي وكالــة واملدعــى عليــه وكالــة‬\n      ‫وبســؤال املدعــي وكالــة عــن جوابــه أبــرز مذكــرة مكونــة مــن ســبع‬\n      ‫صفحــات ومتضمنــه مــا نصــه أو ًال ‪ :‬أن الصــك الصــادر مــن فضيلتكــم‬\n      ‫برقــم ‪ 33356475‬وتاريــخ ‪1433/7/26‬ه ـ املتضمــن تعيــن املذكوريــن‬\n      ‫أوصيــاء علــى أوالد موكلتــي قــد صــدر يف غيــر اختصــاص ‪ ،‬حيــث‬\n      ‫إن صــدور ذلــك الصــك كان يف وقــت حيــاة ‪ ،‬وقــد أقامــت موكلتــي‬\n      ‫الدعــوى رقــم ‪ 29/131631‬وتاريــخ ‪1429/10/18‬ه ـ واحملالــة إلــى‬\n      ‫مكتب فضيلة الشيخ (‪ )......‬بطلب نزع الوالية من على أوالد موكلتي‬\n      ‫لفقــده األهليــة ‪ ،‬وحيــث إن الدعــوى بعــد حضــور جلســتني فيهــا قــد‬\n      ‫أوقفــت بنــاء علــى املــادة ‪ 82‬مــن نظــام املرافعــات الشــرعية حلــن االنتهــاء‬\n      ‫ـاء عليــه فإنــه بانتهــاء‬\n                              ‫مــن نظــر القضيــة املتعلقــة باحلجــر علــى (‪ )......‬وبنـ ً‬\n      ‫القضيــة املذكــورة يكــون تعيــن أوصيــاء أو أوليــاء علــى القصــر هــو‬\n      ‫مــن اختصــاص مــن قــام عنــده النــزاع ابتــداء ثاني ـ ًا ‪:‬أن احتجــاج املدعــى‬\n      ‫عليــه وكالــة بالوصيــة املنســوبة لــ(‪( ).........‬وهــو مــا لــم نســلم بثبوتــه)‬\n      ‫ال يلــزم منــه إطالق ـ ًا لــزوم توليــة املذكوريــن علــى أوالد موكلتــي ملــا‬\n      ‫ـاء هــو جــواز عــدول القاضــي عــن نــص‬       ‫يلــي ‪ 1 :‬ـ أن الثابــت فقه ـ ًا وقضـ ً‬\n      ‫املوصــي متــى تبــن لــه املصلحــة يف ذلــك وعلــى ذلــك جــاءت نصــوص‬\n\n\n‫‪289‬‬\n\f‫األئمــة ‪ -‬قــال شــيخ اإلســام كمــا يف االختيــارات (( يجــوز تغييــر نــص‬\n‫الواقــف فيمــا هــو أحــب إلــى اهلل ورســوله وأكثــر مصلحــة دينيــة ممــا‬\n‫حلظــه الواقــف ))‪ ،‬وقــال يف موضــع آخــر (( ويجــوز تغييــر شــرط الواقــف‬\n‫إلــى مــا هــو أصلــح منــه وإن اختلــف ذلــك باختــاف الزمــان واملــكان ))‬\n‫‪ ،‬فاملتعــن هــو التحــوط ملــال ومصلحــة املولــى عليــه بأقصــى مــا ميكــن‬\n‫ولــو كان بتغييــر وصيــة املولــي ‪ ،‬والواليــة علــى لقاصــر أولــى مــن الوقف‬\n‫يف هــذا لكونهــا تتعلــق بحقــوق اآلدميــن املبنيــة علــى املشــاحة وليســت‬\n‫كالوقــف الــذي هومــن بــاب التبرعــات باجلملــة ‪2‬ـ أن مقصــد إقامــة‬\n‫الوصــي هــو حفــظ حقــوق القصــر ومراعــاة مصاحلهــم ‪ ،‬فــإذا تبــن أن‬\n‫املصلحــة يف غيــر مــن ســماه املوصــي أو أن الضــرر ممــن ســماه محقــق‬\n‫جــازت املخالفــة بــل تعينــت ‪ ،‬فاحتجــاج املدعــى عليــه مبــا ذكــره مــن‬\n‫تســمية املذكوريــن ال محــل لــه إذا حصلــت العــداوة بينهــم وبــن القصــر‬\n‫‪ ،‬وأي عــداوة أســرية أشــد ممــا شــاهدناه يف هــذه الدعــوى مــن إقامــة‬\n‫دعــوى القــذف وتطليــق األم مرتــن وطردهــا وأوالدهــا القصــر مــن‬\n‫ا ثالثـ ًا ‪ -:‬أن تضــاد املصالــح‬‫منزلهــم كمــا ســوف يأتــي ذكــره تفصيـ ً‬\n‫بــن املوصــي بهــم ( أوالد موكلتــي ) وبــن األوصيــاء املســمني ظاهــر‬\n‫‪ ،‬حيــث إن األوصيــاء املذكوريــن هــم الذيــن عينــوا أنفســهم وكالء‬\n‫عــن الوالــد فتــرة مرضــه وذلــك مــن عــام ‪1428‬ه ـ مــرور ًا بتاريــخ إقامــة‬\n‫موكلتــي الدعــوى بطلــب احلجــر يف شــهر محــرم عــام ‪1429‬ه ـ إلــى وقــت‬\n‫تعيينهــم أوليــاء علــى الوالــد وتصديــق ذلــك من التمييــز يف ‪1433/7/8‬هـ‬\n‫‪ ،‬وحيــث إن تصرفاتهــم الســابقة كلهــا حتتــاج إلــى محاســبة وأن هــذه‬\n‫احلقــوق التــي ســوف يحاســب املعينــون عليهــا قــد انتقلــت مــن الوالــد‬\n‫(املــورث) إلــى الورثــة ( ومنهــم القصــر ) لــذا فــإن مــن حــق القصــر أن‬\n\n\n                                                                                   ‫‪290‬‬\n\f      ‫يقــوم علــى شــأنهم مــن ال مينعــه مانــع مــن محاســبة األوليــاء والــوكالء و‬\n      ‫املتصرفــن عنــوة يف أمــوال والدهــم وتعيــن املذكوريــن يف الوصيــة هــو‬\n                                                   ‫يف حقيقتــه منــع للمحاســبة املتعينــة‬\n      ‫رابع ـ ًا ‪ -:‬اعتــداء بعــض املذكوريــن بانفرادهــم علــى حقــوق والدهــم‬\n      ‫وتعــن محاســبتهم بإقامــة الدعــاوى عليهــم بطلــب مــا بأيديهــم مــن أمــوال‬\n                           ‫التركــة والتــي بعضهــا حــق للقصــر ومــن ذلــك مــا يلــي‪:‬‬\n      ‫‪ -1‬اعتــداء يزيــد علــى مبلــغ قــدره مائــة مليــون ريــال حيــث اســتغل مــرض‬\n      ‫والــده وأخــذ منــه توقيــع علــى حتويــل مائــة ألــف ســهم مــن أســهم شــركة‬\n      ‫(‪ ).........‬األهليــة مــن محفظــة الوالــد الشــيخ (‪ ).........‬رقــم (‪ ).........‬إلــى‬\n      ‫محفظــة (‪ ،).........‬وبنــاء عليــه فــإن علــى العضــو املعــن يف الوصيــة إعــادة‬\n      ‫نصيــب القصــر إليهــم بنــاء علــى طلــب مــن املجلــس فكيــف يكــون هــذا‬\n                                                                                            ‫‪.‬‬\n      ‫‪ -2‬اعتــداء املذكوريــن جميع ـ ًا علــى أســهم (‪ )...‬يف حــال حياتــه ونقلهــا‬\n      ‫ألســمائهم وأخــذ األربــاح ملــدة ثــاث ســنوات والواجــب إرجاعهــا إلــى‬\n      ‫التركــة بكاملهــا‪ ،‬حيــث إن جميــع ممتلــكات الشــيخ (‪ - )...‬رحمــه‬\n      ‫اهلل ‪ -‬كانــت ضمــن مؤسســة (‪ )...‬للتجــارة والزراعــة بالســجل رقــم (‪)...‬‬\n      ‫وقــام مــن يديــر املــال حينهــا بإحالــة املمتلــكات إلــى شــركة (‪ )...‬التــي‬\n      ‫ال ميتلــك فيهــا (‪ )...‬ســوى ‪ %12‬وقــد قــام أبنــاء الشــيخ (‪ )...‬رحمــه اهلل ‪-‬‬\n      ‫بأخــذ توقيــع والدهــم علــى خطــاب تنــازل عــن جميــع الرصيــد الدائــن‬\n      ‫يف شــركة (‪ )...‬لالســتثمار والتطويــر العقــاري ‪ ،‬ويعتبــر هــذا اخلطــاب‬\n      ‫مبثابــة تنــازل عــن جميــع املمتلــكات التــي نقلــت مــن املؤسســة إلــى‬\n      ‫شــركة (‪ ،)...‬وهــذا يعنــي أن الشــيخ (‪ - )...‬رحمــه اهلل ‪ -‬قــام بتوزيــع‬\n      ‫مــا نســبته ‪ %88‬مــن مالــه وهــو املســجل يف شــركة (‪ )...‬بأســماء بقيــة‬\n\n\n‫‪291‬‬\n\f                                                                   ‫الشــركاء‪.‬‬\n‫‪ -3‬قيــام بعــض طالبــي الواليــة بصفتهــم وكالء عــن والدهــم بنقــل‬\n‫أمالكه يف مؤسســة (‪ )......‬للتجارة والزراعة (ســجل جتاري رقم(‪)).....‬‬\n‫والتــي تبلــغ قيمتهــا الدفتريــة ‪ 3.400.000.000‬ريــال (ثــاث مليــارات‬\n‫وأربعمائــة مليــون ريــال) مســتغلني صفتهــم أعضــاء يف مجلــس إدارتهــا‬\n‫وذلــك إلــى شــركة (‪ ).....‬اململوكــة باألغلبيــة لهــم وحرمــان إخوانهــم‬\n                                           ‫القصــر منهــا (أوالد موكلتــي(‪.‬‬\n‫‪ -4‬قيــام بعــض طالبــي الواليــة مســتغلني صفتهــم بأنهــم أعضــاء مجلــس‬\n‫إدارة مؤسســة (‪ )....‬للتجــارة والزراعــة القائمــة علــى إدارة أمالك وأعيان‬\n‫الشــيخ(‪ ،)....‬وذلــك بالتصــرف يف أســهمه املوجــودة يف احملفظــة رقــم‬\n‫يف البنــك (‪ )....‬وذلــك بنقلهــا إلــى محافــظ أخــرى باســم شــركة (‪).....‬‬\n‫وجــاء هــذا التصــرف بعــد إلغــاء وكاالتهــم مبوجــب أمــر احملكمــة‬\n‫‪ ،‬وبالتالــي فــإن ضمــان هــذا التصــرف هــو مســئوليتهم وهــو مــن حــق‬\n                       ‫القصــر فكيــف تتــم املطالبــة بــه واحلــال كذلــك ‪.‬‬\n‫خامس ـاً‪ -:‬ظهــور العــداوة بــن املذكوريــن أو بعضهــم وبــن موكلتــي‬\n                                     ‫وأوالدهــا وذلــك علــى النحــو التالــي‪-:‬‬\n‫‪-1‬قيــام املذكوريــن وخاصــة (‪ )....‬و(‪ )....‬بطــرد موكلتــي وأوالدهــا مــن‬\n‫قصرهــم يف نهايــة عــام ‪1428‬ه ـ وعــدم تســليمهم شــيء مــن أغراضهــم‬\n‫الشــخصية طيلــة هــذه الســنوات وعــدم قبولهــم الرجــوع إلــى بيتهــم‬\n‫ورفضهــم االســتجابة لنــداء العقــل واملنطــق بحســب تقريــر شــرطة ملقــام‬\n‫اإلمــارة وســلوكهم مختلــف الســبل لالمتنــاع مــن تنفيــذ مــا أمــرت‬\n‫بــه اجلهــات املســئولة مــن إعــادة موكلتــي وأوالدهــا إلــى بيتهــم‪ ،‬وإنــي‬\n‫هنــا أكتفــي مبــا جــاء يف خطــاب صاحــب الســمو امللكــي األميــر يف‬\n\n\n                                                                                  ‫‪292‬‬\n\f      ‫خطابــه رقــم ‪ 97782‬وتاريــخ ‪1432/7/19‬ه ـ واملؤكــد عليــه بخطــاب‬\n      ‫صاحــب الســمو امللكــي أميــر منطقــة الريــاض بالنيابــة برقــم ‪138356‬‬\n      ‫يف ‪1432/11/11‬ه ـ ونــص احلاجــة منــه مــا يلــي‪ :‬أوالً‪ :‬متكــن املــرأة‬\n      ‫املدعيــة وأوالدهــا مــن العــودة ملنزلهــم وأن يؤثــث لهــم ويعــاد علــى مــا‬\n      ‫كان عليــه ســابق ًا بــراءة للذمــة وإحقاق ـ ًا للعدالــة ثاني ـاً‪ :‬أن يعامــل‬\n      ‫املدعــى عليهمــا مبوجــب الئحــة اإلجــراءات اجلزائيــة لقــاء اعتدائهــم علــى‬\n      ‫منــزل إخوانهــم وســرقة األثــاث واجلــوازات وتغييــر أقفــال األبــواب وفصــل‬\n      ‫لذلــك أوراق مســتقلة‪ ،‬ومــع ذلــك فــإن موكلتــي مــا تــزال خــارج بيتهــا‪،‬‬\n      ‫وال يــزال أوالدهــا يف غرفــة مــن غــرف بيــت خالهــم رغــم صــدور التوجيــه‬\n      ‫الكــرمي ملقــام شــرطة منطقــة الريــاض منــذ مــا يقــارب العامــن لكــن‬\n      ‫(‪ ).........‬و(‪ ).........‬مياطــان مبختلــف الطــرق والوســائل لعــدم التنفيــذ‬\n      ‫‪ ،‬بــل إن األمــر قــد بلــغ باملذكوريــن مبلغــه حيــث قامــوا مبنــع القصــر‬\n      ‫أوالد موكلتــي مــن رؤيــة والدهــم أثنــاء مرضــه وأرفــق لفضيلتكــم‬\n      ‫ا عــن اعتــداء أحدهــم‬    ‫صــورة مــن محضــر احلالــة منع ـ ًا لإلطالــة فض ـ ً‬\n      ‫وهــو علــى أحــد إخوانــه وقــت كان قاصــر ًا وذلــك بالضــرب الــذي‬\n      ‫أدخــل الطفــل علــى إثــره إلــى املستشــفى وفق ـ ًا للتقريــر املرفــق ‪2‬ـ قيــام‬\n      ‫املذكوريــن أثنــاء فتــرة مــرض والدهــم بصــرف النفقــات مــن أمــوال‬\n      ‫الوالــد ألشــقائهم ومــن يرغبــون وحرمــان القصــر ( أوالد موكلتــي )‬\n      ‫مــن ذلــك حتــى اضطــرت موكلتــي للجــوء إلــى احملاكــم الشــرعية ولــم‬\n      ‫تســتطع احلصــول حتــى علــى عشــر مــا يصــرف مــن أمــوال والــده علــى‬\n      ‫ســباق الســيارات ‪ ،‬حيــث إنهــا لــم حتصــل إال علــى مائــة وخمســن‬\n      ‫ألــف ريــال ســنوي ًا ‪ ،‬بينمــا دعمــت شــركة (‪ ).........‬للســيارات بأحــد‬\n      ‫عشــر مليــون ريــال وفــق التقاريــر اإلعالميــة املنشــورة بتصريــح مديــر‬\n\n\n‫‪293‬‬\n\f‫الشــركة ‪ ،‬وقــد امتنــع عــن اإلنفــاق علــى أوالد موكلتــي القصــر ولــم‬\n‫يلتــزم باالتفــاق الــذي التــزم فيــه بــأن يدفــع مبلــغ شــهري قــدره ‪12.000‬‬\n‫ريــال إضافــة إلــى حتملــه رســوم املــدارس ‪ ،‬ولــم يقــم بدفــع أو ســداد أيــة‬\n‫مبالــغ إال بعــد أن تقدمنــا بالشــكوى لفضيلــة الشــيخ (‪ ).........‬مبوجــب‬\n‫خطابنــا رقــم ‪ 11/3/110‬املرفــق صــورة منــه والــذي همــش عليه فضيلته‬\n‫لــ(‪ ، ).........‬فلــو كان حريــص علــى مصالــح إخوانــه القصــر مــا امتنــع‬\n‫عــن أداء النفقــة لهــم وتعطيــل شــئونهم عــن طريــق االمتنــاع عــن تســديد‬\n‫مصاريــف املــدارس ‪ ،‬والشــاهد هنــا هــو عــدم أحقيــة يف الوصايــة علــى‬\n‫إخوانــه القصــر أوالد موكلتــي لعــدم حرصــه علــى مصاحلهــم ‪ -3 .‬قيــام‬\n‫املذكوريــن بالســعي الشــديد لتطليــق موكلتــي وهــي أم القصــر املــراد‬\n‫التوليــة عليهــم مــن زوجهــا ‪ ،‬ويكفــي داللــة لذلــك أن الشــاهد علــى‬\n‫الطــاق األول هــو ‪ ،‬ويكفــي أيض ـ ًا أن الشــيخ (‪ ).........‬طلــب حضــور‬\n‫أكثــر مــن مــرة بنــاء علــى دعــوى موكلتــي املقامــة يف ‪1429/1/12‬ه ـ‬\n‫ورفــض الــوكالء ذلــك ‪ ،‬ويف جلســة ‪1430/7/4‬ه ـ أفهــم الوكيــل بعدم‬\n‫طــاق موكلــه (‪ ).........‬ملوكلتــي أو تزوجــه بخامســة حتــى يحضــر إلــى‬\n‫مجلــس احلكــم‪ ،‬ويف ‪1430/7/10‬ه ـ أحضــر (‪ ).....‬إلــى القاضــي (‪).....‬‬\n‫يف محكمــة الضمــان واألنكحــة ومت إثبــات ســت طلقــات علــى لســانه‬\n‫وهــو الصــك املنقــوض واملصــادق علــى نقضــه مــن محكمــة التمييــز وهو‬\n‫هنــا مــن أكبــر أدلــة العــداوة بــن القصــر وبــن أكثــر أعضــاء مجلــس‬\n‫الوصايــة املعــن يف الصــك املعتــرض عليــه ‪ -4‬قيــام (‪ ).....‬و(‪ ).....‬مــع‬\n‫وكالء آخريــن باالحتيــال لالســتيالء علــى حصــة موكلتــي يف شــركة‬\n‫(‪ ).........‬وأوالده للتجــارة والصناعــة والزراعــة ( القابضــة حاليـ ًا ) والتــي‬\n‫تبلــغ أكثــر مــن ثمانــن مليــون ريــال وذلــك باســتخراج وكالــة للتنــازل‬\n\n\n                                                                                     ‫‪294‬‬\n\f      ‫عــن احلصــة ثــم قامــوا بنقــل تلــك احلصــة بالكامــل إلــى اســم والدهــم‬\n      ‫يف مظلمــة شــهد عليهــا اهلل تعالــى وصــدر حكــم نهائــي مصــدق مــن‬\n      ‫محكمــة االســتئناف بإقــرار هــذا التصــرف ويبقــى املوضــوع محــا ًال‬\n      ‫إلــى محكمــة اآلخــرة‪ ،‬وشــاهدنا هنــا درجــة العــداوة التــي حملهــا قلــب‬\n      ‫هذيــن املعينــن أوصيــاء علــى أوالد موكلتــي والتــي حملهــم علــى هــذا‬\n      ‫الصنيــع الــذي ميتنــع منــه أهــل املروءات ‪ ،‬لكن العداوة إذا اســتحكمت‬\n      ‫أنســت العاقــل عقلــه ‪ ،‬فكيــف يســوغ إقــرار هــؤالء أوصيــاء علــى أوالد‬\n      ‫موكلتــي مــع كل هــذه العــداوة مــع والدتهــم‪-5 .‬قيــام املذكوريــن‬\n      ‫(‪ ).........‬و(‪ ).........‬بتهديد موكلتي يف قضية أرض (‪ ).....‬املعروضة على‬\n      ‫فضيلتكــم برقــم (‪ ).....‬وتاريــخ ‪1429/1/12‬ه ـ وإجبارهــا علــى التنــازل‬\n      ‫عــن األرض والقضيــة منظــورة لــدى فضيلتكــم ‪ ،‬ومحــل الشــاهد هنــا‬\n      ‫بيــان درجــة العــداوة لتجريــد موكلتــي مــن كل حــق سادسـ ًا ‪ -:‬حصــول‬\n      ‫االعتــداء الظاهــر علــى أمــوال ابــن موكلتــي (‪ ).........‬حيــث إنــه بتاريــخ‬\n      ‫‪1433/5/17‬ه ـ اســتصدر (‪( ).........‬ابــن موكلتــي) بطاقــة أحــوال‬\n      ‫لبلوغــه الســن القانونيــة لذلــك ‪ ،‬ومبراجعتــه للبنــك وجــد أن هنــاك‬\n      ‫حســاب باســمه وأن املفــوض بالتوقيــع علــى هــذا احلســاب هــو (‪، ).........‬‬\n      ‫وبطلــب كشــف احلســاب وجــد أن إجمالــي اإليداعــات هــو مبلــغ وقــدره‬\n      ‫(‪ )44.863.674.69‬ريــال وأن املوجــود فعليـ ًا منهــا يف هــذا احلســاب هــو‬\n      ‫مبلــغ وقــدره ‪328.91‬ريــال فقــط ال غيــر ‪ ،‬واملوجــود باحلافظــة اخلاصــة‬\n      ‫باألســهم املربوطــة باحلســاب هــو مبلــغ وقــدره ‪ 19.642.370.26‬ريــال‬\n      ‫وذلــك بنقــص قــدره ‪ 25.221.304.43‬ريــال ‪ ،‬وقــد أقــام الدعــوى علــى‬\n      ‫بطلــب احملاســبة لكونــه املتصــرف باحلســاب واملقيــدة يف احملكمــة‬\n      ‫العامــة بالريــاض برقــم (‪ ).....‬وتاريــخ ‪1434/4/10‬ه ـ واحملالــة إلــى‬\n\n\n‫‪295‬‬\n\f‫فضيلــة الشــيخ (‪ ).........‬وجنــزم أن فضيلتكــم لــو طلــب مــن مؤسســة‬\n‫النقــد كشــف حلســابات القصــر لوجــد احلــال نفســه ‪ ،‬فهــل يســوغ‬\n‫املخاطــرة بأمــوال القصــر إلــى هــذا احلــد أم يعمــل باالحتيــاط والنصــح‬\n‫لهــم ســابع ًا ‪ -:‬عــدم ائتمــان طالبــي الوصايــة علــى القصــر‪ ،‬حيــث جعلــوا‬\n‫والدهــم يوقــع علــى إبــراء لهــم عــن كل مــا فعلــوه يف املاضــي أو احلاضــر‬\n‫أو املســتقبل عــن قصــد أو عــن غيــر قصــد فيمــا يتعلــق مبــال (‪ ).........‬أو‬\n‫مــال أحــد مــن أوالده القصــر (ومــن هــم أوالده القصــر إال أوالد موكلتــي‬\n‫اللذيــن يطلبــون الوصايــة عليهــم ؟ ) ثامن ـ ًا ‪ -:‬مخاطــرة املذكوريــن‬\n‫بأمــوال القصــر ومحاولتهــم بيــع كامــل نصيبهــم مــن إرثهــم الشــرعي‬\n‫مــن والدهــم علــى شــركة (‪ ).....‬القابضــة مببلــغ أقــل بكثيــر مــن ثمــن‬\n‫املثــل وقــدره ‪25.000.000‬ريــال (خمســة وعشــرون مليــون ريــال فقــط)‪،‬‬\n‫وقــد تقــدم أعضــاء مجلــس الوصايــة املذكــور واللذيــن مت تعيينهــم‬\n‫مبوجــب صــك الوصايــة الصــادر مــن فضيلتكــم بطلــب البيــع املذكــور‬\n‫مبوجــب املعاملــة املقيــدة يف مكتــب فضيلــة الشــيخ (‪ ).........‬القاضــي‬\n‫باحملكمــة العامــة بالريــاض برقــم ‪ 34303191‬وتاريــخ ‪1434/2/5‬ه ـ‬\n‫‪ ،‬وهــذا اإلجــراء فيــه أشــد الضــرر مبصلحــة القصــر ‪ ،‬لكــون الهــدف‬\n‫مــن هــذا البيــع هــو مــا عبــر عنــه محامــي مجلــس الوصايــة املذكــور‬\n‫بالتخلــص مــن واليــة احملكمــة علــى بيــع عقــارات القصــر ‪ ،‬وحيــث إن‬\n‫التخلــص مــن واليــة احملكمــة يخالــف مقصــود الشــارع احلكيــم بربطــه‬\n‫التصرفــات الناقلــة مللكيــة عقــارات القصــر باملوافقــة القضائيــة ‪ ،‬وإن‬\n‫تعيــن املذكوريــن أوصيــاء علــى القصــر يعنــي أن احملكمــة تقــر هــذا‬\n‫التصــرف بــل وتعطــي لــه الغطــاء القانونــي وكأنهــا تقــول لألوصيــاء‬\n‫وبــكل بســاطة إليكــم مــال القصــر لتتصرفــوا فيــه كمــا تشــاءون دون‬\n\n\n                                                                                    ‫‪296‬‬\n\f      ‫الرجــوع للمحكمــة ولكــم مطلــق احلريــة يف ذلــك وبنــاء علــى مــا تقــدم‬\n      ‫‪ ......‬نطلــب مــا يلــي‪ :‬أوالً‪ :‬الطلــب األصلــي التهميــش علــى صــك الواليــة‬\n      ‫الصــادر مــن فضيلتكــم بالرجــوع عنــه وإحالــة املعاملــة إلــى فضيلــة‬\n      ‫الشــيخ (‪ ).........‬خلــف الشــيخ (‪ ).....‬لســماع دعــوى موكلتــي بطلــب‬\n      ‫الواليــة وإجــراء الوجــه الشــرعي جتاههــا ثاني ـاً‪ -:‬الطلبــات االحتياطيــة‬\n      ‫‪ -1‬احلكــم بنــزع وصايــة املذكوريــن يف الوصيــة عــن القصــر أوالد‬\n                    ‫موكلتــي وتعيــن موكلتــي وليــة عليهــم حفظ ـ ًا حلقوقهــم‬\n      ‫‪ -2‬الكتابــة إلــى مؤسســة النقــد العربــي الســعودي لطلــب كشــف‬\n      ‫حلســابات القصــر وهــم (‪ ).....‬ســجل مدنــي (‪ ).....‬و(‪ ).....‬ســجل‬\n      ‫مدنــي (‪ ).....‬و(‪ ).....‬ســجل مدنــي (‪ ).....‬مــع تزويــدي بصــورة مــن تلــك‬\n      ‫الكشــوفات لبيــان مــا فيهــا مــن إهمــال وتقصيــر وتعــدي علــى أمــوال‬\n                             ‫القصــر شــبيهة مبــا حــل بأمــوال شــقيقهم (‪).........‬‬\n      ‫‪ -3‬ســحب أصــل صــك الوصايــة مــن املذكوريــن وإفهامهــم خطيـ ًا بدفتر‬\n      ‫الضبــط بعــدم التصــرف ســواء ببيــع أو رهــن أو نقــل ألمــاك القصــر‬\n                                                      ‫حتــى ينتهــي النظــر يف الدعــوى‬\n      ‫‪ -4‬حيــث إن (‪ )...‬بنــت (‪ )...‬قــد بلغــت مبلــغ النســاء ولرشــدها فــإن‬\n      ‫موكلتــي تطلــب إخــراج صــك رشــد مســتقل بهــا ومتكينهــا مــن الواليــة‬\n      ‫ا للنــزاع وحفظ ـ ًا حلقهــا هكــذا أجــاب‬       ‫علــى أموالهــا بنفســها تقلي ـ ً‬\n                               ‫وبعــرض ذلــك علــى املدعــى عليــه وكالــة أجــاب‪.‬‬\n      ‫‪ -1‬ســبق وأن أوصــى الشــيخ (‪ ).......‬يف حياتــه بأنــه يف حــال فقــده‬\n      ‫لألهليــة فيتولــى والياتــه مبــا فيهــم أوالده القصــر مجلس ـ ًا مــن ضمنهــم‬\n      ‫(‪ ).......‬و(‪ ).......‬واعترضــت علــى ذلــك املدعيــة وطعنــوا بهــم مــن خــال‬\n      ‫ذكــر أغلــب مــا ورد يف مذكــرة الــرد مــن طعــون وبعــد أنثبــت للقاضــي‬\n\n\n‫‪297‬‬\n\f‫عــدم صحــة ذلــك وثبــت لــه أهليتهــم للواليــة مــع بقيــة مــن عينهــم والدهــم‬\n‫صــدر بذلــك حكمـ ًا برقــم ‪ 3339658‬وتاريــخ ‪1433/1/22‬ه ـ ‪ ،‬وأويــد‬\n‫مــن محكمــة االســتئناف وبنــاء عليــه صــدر صــك شــرعي مــن مكتــب‬\n‫فضيلتكــم برقــم ‪ 33356475‬وتاريــخ ‪1433/7/26‬ه ـ بإقامــة كل‬\n‫مــن‪ ).......( :‬و(‪ ).......‬و(‪ ).......‬ابنــاء الشــيخ (‪ ،).......‬و(‪ ).......‬أوصيــاء‬\n‫علــى القصــر يرعــون شــؤونهم ومصاحلهــم كمــا أوصــى بذلــك والدهــم‬\n‫وحيــث أن هــذا الصــك الصــادر مــن فضيلتكــم ســاري املفعــول حتــى‬\n‫بعــد وفــاة الشــيخ (‪ ).........‬كمــا جــاء يف حاشــيتكم علــى خطــاب‬\n‫الشــيخ‪ ،).........( :‬القاضــي يف هــذه احملكمــة ‪ ،‬فــا وجــه للمطالبــة‬\n‫بإلغائــه ال شــرع ًا وال نظام ـ ًا ‪-2‬مــن الثابــت عنــد فقهــاء احلنابلــة ‪ ،‬وهــو‬\n‫أن وصـ ّـي األب مقــدم علــى األم يف‬        ‫املعمــول بــه يف محاكــم اململكــة َّ‬\n‫القصــر واإلشــراف عليهــم‪ ،‬قــال ابــن قدامــة ‪ « :‬ويتولــى األب‬       ‫ّ‬      ‫رعايــة‬\n‫مــال الصبــي واملجنــون ألنهــا واليــة علــى الصغيــر فقــدم فيهــا األب‬\n‫كواليــة النــكاح ثــم وصيــه بعــده ألنــه نائبــه فأشــبه وكيلــه يف احليــاة‬\n‫« الــكايف (‪ ، )251/8‬وقــال البهوتــي ‪ « :‬ثــم تثبــت الواليــة علــى صغيــر‬\n‫ومجنــون بعــد األب لوصيــه العــدل «‪ .‬كشــاف القنــاع (‪ )383/8‬لذلــك‬\n‫كلــه نأمــل مــن فضيلتكــم التكــرم بإمضــاء صــك الواليــة الصــادر‬\n‫مــن مكتــب فضيلتكــم برقــم ‪ 33356475‬وتاريــخ ‪1433/7/26‬ه ـ ‪،‬‬\n‫واحلكــم بــرد الدعــوى كونهــا تأتــي مخالفـ ًا ملــا عليــه الوصيــة وملــا قــرره‬\n‫فقــاء املذهــب ولكونــه صــدر حكــم ومصــدق مــن االســتئناف بأهليــة‬\n‫املجلــس الــذي أوصــى بــه الشــيخ (‪ ).........‬وعــدم ثبــوت الطعــن بعــدم‬\n‫أهليتهــم للواليــة هكــذا أجــاب وبعــرض ذلــك علــى املدعــي وكالــة‬\n‫أجــاب أطلــب مهلــة لذلــك ثــم يف يــوم الثالثــاء ‪1434/04/23‬ه ـ افتتحــت‬\n\n\n                                                                                         ‫‪298‬‬\n\f      ‫اجللســة الثالثــة الســاعة ‪ 01،15‬وفيهــا حضــر املدعــي وكالــة واملدعــى‬\n      ‫عليــه وكالــة وبســؤاله عــن جوابــه عمــا دفــع بــه املدعــى عليــه وكالــة‬\n      ‫يف اجللســة الســابقة أبــرز مذكــره مكونــة مــن صفحتــن ومتضمنــه مــا‬\n      ‫نصــه أوالً‪ :‬أن مــا جلــأ إليــه املدعــى عليهــم مــن التمســك باحلكــم املشــار‬\n      ‫إليــه واتخــاذه حجــة يف طلــب الوصايــة علــى القصــر هــو يف حقيقتــه حجــة‬\n      ‫عليهــم ال لهــم‪ ،‬حيــث تقــدم املنهــي (‪ ).....‬وكيــل عــن (‪ ).....‬يف الدعــوى‬\n      ‫الصــادر فيهــا احلكــم املذكــور للمحكمــة طالب ـ ًا مــا نصــه « وإقامــة‬\n      ‫مجلــس واليــة مبــا يحقــق مصلحــة املنهــى عنــه ومــن حتــت واليتــه مــن‬\n      ‫أوالده القصــر ويعتنــي بشــؤونه ويحفــظ أموالــه ويطالــب مبــا أخــذ منهــا‬\n      ‫« الصفحــة رقــم ( ‪ ) 2‬مــن الصــك املذكــور وقــد طلــب املدعــى عليهــم يف‬\n      ‫الدعــوى الصــادر فيهــا احلكــم املشــار إليــه تعيينهــم يف مجلــس الواليــة‬\n      ‫علــى والدهــم وتعينهــم أيض ـ ًا أوصيــاء علــى القصــر حســب الوصيــة‬\n      ‫وقــد مت ضبــط طلباتهــم املذكــورة يف الصفحــة رقــم ( ‪ ) 3‬مــن الصــك‬\n      ‫املشــار إليهــم ونصــه كمــا يلــي « إن موكلــي يطلبــون مــن فضيلتكــم‬\n      ‫إنفــاذ مــا ورد يف وصيــة الشــيخ (‪ ).........‬حفظــه اهلل واملوقعــة منــه بتاريــخ‬\n      ‫‪1428/4/28‬ه ـ وهــو بكامــل األهليــة (مرفــق‪ )1‬والتــي أشــهد عليهــا‬\n      ‫كل مــن (‪ ).......‬و(‪ ).......‬والتــي تضمنــت تعيينــه ألعضــاء مجلــس الواليــة‬\n      ‫عليــه عنــد وجــود عالمــات ضعــف يف ذاكرتــه وذلــك وفــق مــا جــاء يف‬\n      ‫الوصيــة أنهــم كل مــن‪ ).......( .3 ).......( .2 ).......( .1 .:‬و(‪( ).......‬إذا‬\n      ‫بلــغ راشــداً) وقــد نــص الشــيخ (‪ ).........‬أنــه علــى « املجلــس عنــد وجــود‬\n      ‫عالمــات الضعــف يف الذاكــرة واإلدارة والهــرم أن يحــل محلــي مباشــرة‬\n      ‫يف إدارة األعمــال واألمــوال واألوقــاف ويلغــي توقيعي وســلطتي الكاملة‬\n      ‫إذا بلغــت األصــوات أربعــة مــن أعضــاء املجلــس املذكوريــن» كمــا‬\n\n\n‫‪299‬‬\n\f‫نــص علــى أن « املجلــس املخــول بتنفيــذ هــذه الوصيــة هــم األوصيــاء علــى‬\n‫أوالدي القصــر ذكــور ًا وإناثـاً‪ ...‬وتكــون واليــة التزويــج لالبــن « ومرفــق‬\n‫صــورة الوصيــة ‪ .......‬إلــخ «‪ ،‬إال أن احلكــم يف الدعــوى املذكــورة قــد‬\n‫جــاء نصــه يف الصفحــة رقــم (‪ )59‬كمــا يلــي « ‪:‬ولــذ فقــد قــررت ‪ :‬أو ًال‬\n‫‪ :‬صرفــت النظــر عــن أي مطالبــة متــت يف أثنــاء املرافعــات ســوى إقامــة‬\n‫مجلــس الوصايــة وأفهمــت مــن لــه دعــوى أن يتقــدم بهــا بصفــة مســتقلة ‪.‬‬\n‫ثانيـ ًا ‪ :‬أقمــت كال مــن (‪ )...‬و(‪ )...‬و(‪ )...‬ابنــاء (‪ )...‬أوليــاء مجتمعــن علــى‬\n‫(‪ )...‬إلــخ « وبنــاء عليــه فــإن طلــب املذكوريــن قــد فصــل فيــه بصــرف‬\n‫النظــر وصــدق ذلــك مــن محكمــة االســتئناف ســابق ًا ثاني ـ ًا ‪ :‬إن ممــا‬\n‫يبــن عــدم صالحيــة املذكوريــن أن (‪ )...‬و(‪ )...‬ولــدي (‪ )...‬املطلــوب‬\n‫تنصيبهــم أوصيــاء علــى القصــر مقــام عليهمــا دعــوى باحلــق العــام يف‬\n‫ـزاء ملــا فعــا يف حــق موكلتــي وأوالدهــا‬  ‫احملكمــة اجلزئيــة بالريــاض جـ ً‬\n‫القصــر ‪ ،‬ونأمــل مــن فضيلتكــم التكــرم بالكتابــة إلــى احملكمــة‬\n‫اجلزائيــة بالريــاض لطلــب نســخة مــن صحيفــة الدعــوى املقامــة ضدهــم‬\n‫واملقيــدة برقــم ‪ 33933573‬وتاريــخ ‪1433/5/17‬ه ـ ثالثـ ًا ‪ -:‬نؤكد على‬\n‫متســكنا مبــا أبدينــاه يف مذكرتنــا املقدمــة يف اجللســة الســابقة بتاريــخ‬\n‫‪1434/4/16‬ه ـ مــن ضــرورة الكتابــة إلــى مؤسســة النقــد العربــي‬\n‫الســعودي لطلــب كشــف حلســابات القصــر وهــم (‪ )...‬و(‪ )...‬و(‪ )...‬مــع‬\n‫تزويــدي بصــورة مــن تلــك الكشــوفات لبيــان مــا فيهــا مــن إهمــال‬\n‫وتقصيــر وتعــدي علــى أمــوال القصــر شــبيهة مبــا حــل بأمــوال شــقيقهم‬\n‫(‪ )....‬وبنــاء علــى مــا تقــدم نأمــل التكــرم بالرجــوع عــن مــا حكمتــم‬\n‫بــه ســابق ًا مــن تعيــن املذكوريــن أوصيــاء علــى أوالد موكلتــي القصــر‬\n‫وتعيــن موكلتــي ( والدتهــم) وصيــة علــى أوالدهــا القصــر (‪ )....‬و(‪)...‬‬\n\n\n                                                                                       ‫‪300‬‬\n\f      ‫و(‪ )...‬حفظـ ًا لشــئونهم هكــذا أجــاب وبعــرض ذلــك علــى املدعــى عليــه‬\n                                                                     ‫وكالــة أجــاب‪:‬‬\n      ‫‪ -1‬ادعــاء وكيــل املدعيــة فيمــا ورد سادسـ ًا مــن املذكــرة مــن حصــول‬\n      ‫اعتــداء علــى أمــوال (‪ )...‬مــن قبــل أخيــه (‪ )...‬بســحب خمــس وعشــرين‬\n      ‫مليــون ريــال مــن حســابه ‪ ،‬وهــذا اتهــام باطــل ال أســاس لــه مــن الصحــة‬\n                                                                   ‫‪ ،‬وذلــك ملــا يلــي ‪:‬‬\n      ‫‪-2‬أن مجلــس الواليــة علــى القصــر كان حريص ـ ًا علــى أمــوال القصــر‬\n      ‫ورعايتهــا وتنميتهــا ‪ ،‬حيــث بلــغ إيــرادات االســتثمارات ووقــف الذريــة‬\n      ‫ألمــوال األخ (‪ )....‬مــا قيمتــه (‪ )41.769.686‬ريــا ًال (واحــد وأربعــون‬\n      ‫مليون وســبعمائة وتســع وســتون ألف وســتمائة وســت وثمانون رياالً)حتى‬\n      ‫تاريــخ ‪1433/5/9‬ه ـ وفقـ ًا للتقريــر املرفــق مــن مكتــب (‪ )....‬للمحاســبة‬\n      ‫‪ ،‬وهــذا التقريــر يدحــض االتهــام املوجــه ملجلــس الواليــة (مرفــق‪- )1‬‬\n      ‫يوضــح كشــف احلســاب اخلــاص بــاألخ (‪ )...‬يف الفتــرة مــن ‪1433/2/7‬‬\n      ‫ه ـ وحتــى تاريــخ ‪1433/6/18‬ه ـ وتقريــر احملاســب القانونــي عــدم وجــود‬\n      ‫أي عمليــة ســحب املبلــغ املذكــور يف مذكــرة وكيــل املدعيــة محــل‬\n                                                                                     ‫الــرد‬\n      ‫‪ -‬توضــح قائمــة حركــة االســتثمارات لــأخ (‪ ).....‬بأنــه مت إيــداع مبلــغ‬\n      ‫( ‪)21.186.148‬ريــا ًال يف صنــدوق (‪ )....‬العقــاري مبصــرف (‪ ).....‬الــذي‬\n      ‫يحقــق عائــد ًا ســنوي ًا بنســبة ‪ %9‬حســب تقريــر احملاســب القانونــي (‬\n      ‫مرفــق‪ )2‬وهــو املبلــغ الــذي يظــن وكيــل املدعيــة بأنــه مت ســحبه مــن‬\n                                ‫رصيــد األخ (‪ ،)......‬والبقيــة يف صناديــق أخــرى‪.‬‬\n      ‫‪-1‬أن األخ (‪ ).....‬وصــل ســن البلــوغ بتاريــخ ‪1433/5/16‬ه ـ ‪ ،‬وبتاريــخ‬\n      ‫‪1433/5/17‬ه ـ أصــدر بطاقــة أحوالــه ‪ ،‬ثــم قــام هــو بنفســه بالتصــرف‬\n\n\n‫‪301‬‬\n\f                   ‫يف حســابه يؤكــد ذلــك صــورة مــن احلســاب املرفــق (‪)3‬‬\n‫‪ -2‬ادعــاء وكيــل املدعيــة بــأن األخ (‪ ).....‬امتنــع عــن تســديد رســوم‬\n‫املــدارس إلخوانــه القصــر ‪ ،‬وهــذا محــض افتــراء ‪ ،‬فقــد بــادر مجلــس‬\n‫للقصــر ‪ ،‬يوضــح ذلــك‬ ‫ّ‬     ‫الواليــة علــى القصــر يف تســديد رســوم املــدارس‬\n                  ‫كشــف احلســاب وســند قبــض مبلــغ الرســوم ‪( .‬مرفــق‪)4‬‬\n‫‪-3‬ومــا عــدا ذلــك فــإن جميــع مــا ذكــره وكيــل املدعيــة يف مذكرتــه‬\n‫مــن ادعــاءات وتهمــة وجــود عــداوة بــن أعضــاء مجلــس الواليــة والقصــر‬\n‫ســبق وأن مت الترافــع فيهــا لــدى فضيلــة القاضــي بهــذه احملكمــة الشــيخ‬\n‫(‪ )......‬يف دعــوى الواليــة علــى الشــيخ (‪ )......‬والطعــن بأهليتــه عنــد‬\n‫كتابــة الوصيــة ‪ ،‬وقــد حكــم فضيلتــه بصــرف النظــر عنهــا ‪ ،‬وأثبــت‬\n‫أن جميــع تصرفــات الشــيخ (‪ ).....‬ووصيتــه صحيحــة نافــذة وصــدرت‬\n‫منــه وهــو يف حالــة معتبــرة شــرع ًا ‪ ،‬وعليــه صــدر صــك شــرعي برقــم‬\n‫‪ 3339658‬وتاريــخ ‪1433/01/22‬ه ـ بتعيــن مجلــس الواليــة علــى الشــيخ‬\n‫(‪ ).....‬مــن ضمنهــم أبنــاؤه (‪ )...‬و(‪ )...‬وعــدم النظــر يف الطعــون ضدهمــا‬\n‫بعــد أن ثبــت لفضيلتــه أهليتهمــا للواليــة و ُأ ّيــد احلكــم مــن محكمــة‬\n‫االســتئناف ‪4‬ـ يظهــر لفضيلتكــم مــن خــال ثنايــا مذكــرة وكيــل‬\n‫ـس باطلــة ‪ ،‬وطعـ ٍـن ألحــكام‬        ‫املدعيــة أنهــا كيديــة وقائم ـ ٌة علــى أسـ ٍ‬\n‫ـف ألحــكام أخــرى‬       ‫قضائيــة قطعيــة كمــا ورد يف املــادة الثانيــة‪ ،‬ووصـ ٍ‬\n‫بأنهــا أحــكام ظاملــة كمــا ورد يف الفقــرة الرابعــة مــن املــادة اخلامســة‬\n‫القصــر كيفمــا يشــاء وذلــك مبــا‬ ‫ّ‬      ‫ـام للمجلــس بالتصــرف بأمــوال‬ ‫‪ ،‬واتهـ ٌ‬\n‫قــام بــه فضيلــة القاضــي يف هــذه احملكمــة الشــيخ (‪ ).....‬مــن بيــع نصيــب‬\n‫القصــر مــن تركــة والدهــم علــى شــركة (‪ ،)......‬مــع أن هــذا البيــع لــم‬\n‫يتــم إال بعــد االســتئناس بأهــل اخلبــرة وتأكيدهــم بــأن هــذا البيــع يحقــق‬\n\n\n                                                                                        ‫‪302‬‬\n\f      ‫الغبطــة واملصلحــة للقصــر‪ ،‬خاصــة وأنــه ســبقهم مبثــل هــذا البيــع بنفــس‬\n                   ‫املبلــغ ثــاث وعشــرون مــن الورثــة ‪ ،‬فأيــن املخاطــرة املزعومــة ؟‬\n      ‫وهــذا يــدل علــى أن الهــدف مــن ذلــك كلــه تشــتيت القضيــة وإطالــة‬\n      ‫أمدهــا ‪ ،‬وإشــغال القضــاة‪ ،‬وتعطيــل تنفيــذ األحــكام القضائيــة وهــذا‬\n      ‫وبعــد‬    ‫ـلك خاطــئ ومنزلــق خطيــر يظهــر معــه حنكــة الشــيخ (‪ُ ).....‬‬     ‫مسـ ٌ‬\n      ‫القصــر‬\n            ‫ّ‬       ‫نظــره ‪-‬رحمــه اهلل ‪ -‬يف الوصيــة مــن إقامــة مجلــس الواليــة علــى‬\n      ‫مــن أبنائــه‪ .‬يتضــح ممــا ســبق ومــن خــال تقريــر احملاســب القانونــي أن‬\n      ‫القصــر‬ ‫ّ‬      ‫القصــر كان شــديد احلــرص علــى أمــوال‬ ‫ّ‬     ‫مجلــس الواليــة علــى‬\n      ‫وتنميتهــا ورعايتهــا واحملافظــة عليهــا واســتثمارها بالطــرق الشــرعية‬\n      ‫كمحفظــة (‪ )......‬لالســتثمار واملشــاركة لــه يف صنــدوق (‪ ).....‬العقــاري‬\n      ‫بعائــد ســنوي قــدره ‪ %9‬وغيرهــا مــن الصناديــق االســتثمارية إال أن األخ‬\n      ‫(‪ )....‬وحلداثــة سـ ّنه وقلــة خبرتــه لــم يكــن علــى علــم بطــرق التعامــل مــع‬\n      ‫البنــوك والصناديــق االســتثمارية وآليــة االســتفادة منهــا والتعــرف علــى‬\n      ‫معلوماتهــا ‪ ،‬حيــث أن مجلــس الواليــة ومبجــرد علمــه بإصــدار (‪).....‬‬\n      ‫لبطاقــة أحوالــه املدنيــة التــي تثبــت بلوغــه ســن اخلامســة عشــر عام ـ ًا‬\n      ‫وقيامــه مبراجعــة البنــوك لتولــي إدارة حســاباته قــام باالتصــال بــه وطلــب‬\n      ‫االجتمــاع معــه لتســليمه امليزانيــة اخلاصــة به إال أنه رفــض احلضور وطلب‬\n      ‫ـاء علــى طلبــه‬    ‫إرســالها عــن طريــق البريــد االلكترونــي وأرســلت لــه بنـ ً‬\n      ‫(مرفــق‪ )5‬وهــذا يدحــض ادعاءهــم أمــام فضيلتكــم بــأن مجلــس الواليــة‬\n      ‫اختلــس خمــس وعشــرين مليــون ريــال وهــو نتــاج قلــة خبرتهــم وعــدم‬\n      ‫معرفتهــم بتحليــل ودراســة التقاريــر املاليــة كل ذلــك يؤكــد أن الشــيخ‬\n      ‫القصــر ‪ -‬رحمــه اهلل ‪ -‬كان حريص ـ ًا علــى حفــظ أمــوال‬          ‫ّ‬      ‫(‪ )....‬والــد‬\n      ‫القصــر وحقوقهــم مــن خــال تعيــن املؤهلــن والقادريــن واألمنــاء علــى‬\n\n\n‫‪303‬‬\n\f‫أبنائــه القصــر كمــا أن تصــرف األخ (‪ ).....‬وعــدم معرفتــه بــإدارة أموالــه‬\n‫واتهــام أخيــه باختالســه مبلــغ خمــس وعشــرين مليــون ريــال مــن حســابه‬\n‫مــع حتقــق وجــوده لــدى مصــرف (‪ ).....‬ويف امليزانيــات والتقاريــر املســلمة‬\n‫مؤكـ ٌـد علــى حاجتــه بــأن يتولــى‬\n                                  ‫ّ‬      ‫القصــر‬\n                                             ‫ّ‬     ‫لــه مــن مجلــس الواليــة علــى‬\n‫مجلــس الواليــة علــى القصــر االســتمرار يف الواليــة عليــه حتــى يكتمــل‬\n‫ميكنــه مــن حمايــة حقوقــه وأموالــه وخشــية مــن أن يســتغل‬   ‫رشــده والــذي ّ‬\n‫ا بقولــه تعالــى ‪ « :‬وابتلــوا اليتامــى حتــى إذا‬\n                                                  ‫مــن ضعــاف النفــوس ‪ ،‬عمـ ً‬\n‫بلغــو النــكاح فــإن آنســتم منهــم رشــد ًا فادفعــوا إليهــم أموالهــم « ممــا‬\n‫ســبق يتضــح لفضيلتكــم أن هــدف املدعيــة مــن هــذه الدعــوى تعطيــل‬\n‫أعمــال مجلــس الواليــة علــى القصــر وهــذا بــا شــك يضــر بالقصــر مــن‬\n‫ناحيــة رعايــة مصاحلهــم وكذلــك مــن ناحيــة اســتثمار وتنميــة أموالهــم‬\n‫التــي تبلــغ مئــات املاليــن حيــث كان والدهــم رحمــه اهلل يعلــم حجــم‬\n‫ثروتهــم واحلاجــة خلبــراء وأمنــاء عليهــم كمــا حددهــم بوصيتــه‪ ،‬وهــذا‬\n‫يثبــت لفضيلتكــم أن دعــوى املدعــي بالوكالــة مخالــف ملــا هــو مقــرر‬\n‫عنــد فقــاء املذهــب ومــا هــو معمــول بــه يف احملاكــم مــن أن وصــي‬\n‫األب مقــدم علــى األم يف الواليــة‪ ،‬كمــا أن مضمــون هــذه الدعــوى مــن‬\n‫الطعــون بأعضــاء مجلــس الواليــة علــى القصــر ســبق وأن ُحكــم فيــه‬\n‫بأحــكام قضائيــة قطعيــة ســبق اإلشــارة إليهــا لــكل مــا تقــدم أطلــب‬\n‫مــن فضيلتكــم احلكــم بإمضــاء الصــك الواليــة الصــادر مــن مكتــب‬\n‫فضيلتكــم برقــم ‪ 33356475‬وتاريــخ ‪1433/7/26‬ه ـ ‪ ،‬واحلكــم بــرد‬\n‫الدعــوى واســتمرار املجلــس وصي ـ ًا علــى القاصــر (‪ )...‬هكــذا أجــاب‬\n‫وبطلــب إثبــات مــا ادعــاه املدعــى عليــه وكالــة مــن أن املبلــغ الــذي أودع‬\n‫يف حســاب ابــن املدعيــة (‪ )....‬قــد جــرى إيداعه لدى شــركة (‪ )....‬التابعة‬\n\n\n                                                                                      ‫‪304‬‬\n\f      ‫ملصــرف (‪ )...‬أبــرز ورقــه مــن أوراق ومطبوعــات (‪ )....‬املاليــة وموجه لـ(‪)...‬‬\n      ‫ومتضمنــه اإلفــادة بوجــود اســتثمار لــ(‪ )...‬مببلغ وقــدره ‪ 20898000‬ريال‬\n      ‫وعائــد ســنويا قــدره ‪ %6‬وبعــرض ذلــك علــى املدعي وكالة أجاب أطلب‬\n      ‫مهلــة للتأكــد مــن اخلطــاب الــذي أبــرزه املدعــى عليــه وكالــة هكــذا‬\n      ‫أجــاب ثــم يف يــوم األحــد املوافق‪1434/05/05‬ه ـ افتتحــت اجللســة‬\n      ‫الرابعــة الســاعة الواحــدة والربــع وفيهــا حضــر املدعــي وكالــة واملدعــى‬\n      ‫عليــه وكالــة وبســؤال املدعــي وكالــة عمــا اســتمهل مــن أجلــه أجــاب‬\n      ‫لقــد راجعــت مصــرف (‪ )....‬وطلبــت منــه بيــان باحلــواالت التــي متــت علــى‬\n      ‫حســاب (‪ )...‬فطلبــوا منــي وقــت كــون احلــواالت متــت علــى مبالــغ صغيــرة‬\n      ‫هكــذا أجــاب وجــرى ســؤال املدعــي وكالــة هلمــا ذكــره املدعــى عليــه‬\n      ‫وكالــة مــن وجــود اســتثمار لــ(‪ ).....‬يف شــركة (‪ ).....‬صحيــح أجــاب نعــم‬\n      ‫لــه مبلــغ مســتثمر يف شــركة (‪ )....‬بنفــس املبلــغ الــذي ذكــره املدعــى‬\n      ‫عليــه وكالــة لكــن ليــس مســحوب ًا مــن حســاب (‪ ).....‬هكــذا أجــاب‬\n      ‫وبعــرض ذلــك علــى املدعــى عليــه وكالــة أجــاب مــا ذكــره املدعــي‬\n      ‫وكالــة مــن اتهــام موكلــي عضــو مجلــس الوصايــة باالســتيالء علــى‬\n      ‫أمــوال (‪ )....‬فقــد ثبــت بجــواب وكيــل املدعيــة بأنــه موجــود يف حســاب‬\n      ‫االســتثمار اخلــاص بــ(‪ )....‬يف صنــدوق (‪ ).....‬العقــاري وهــذا يؤكــد أن‬\n      ‫موكلــي وأعضــاء مجلــس الوصايــة ومحافظــن علــى أمــوال القصــر‬\n      ‫ويســتثمرونها فيمــا يحقــق الصالــح لهــم حتقيــق الوصيــة والدهــم رحمــه‬\n      ‫اهلل كما يؤكد أن (‪ ).....‬ووالدته املدعية ليس لديهم اخلبرة الكافية‬\n      ‫لقــراءة التقاريــر املاليــة اخلاصة باالســتثمارات واحلســابات وإدارة األموال‬\n      ‫التــي ورثوهــا هكــذا أجــاب وأبــرز املدعــى عليــه وكالــة ورقــة أصــل‬\n      ‫صــادرة مــن (‪ )....‬املاليــة ومؤرخــة يف ‪2012/7/31‬م ومتضمنــه أن لــ(‪)...‬‬\n\n\n‫‪305‬‬\n\f‫اســتثمار لديهــا مبلــغ وقــدره ‪20898000‬ريــال وأنهــا حققــت عائــدا قــدره‬\n‫‪ %6.0‬للفتــرة مــن ‪2012/2/1‬م إلــى ‪2012/7/31‬م ومذيلــة بتوقيــع‬\n‫العضــو املنتــدب صنــدوق (‪ )....‬للدخــل العقــاري وعضــو مجلــس اإلدارة‬\n‫واخلتــم الرســمي وبعــرض ذلــك علــى املدعــي وكالــة أجــاب إن املبلــغ‬\n‫املــودع يف صنــدوق (‪ )....‬هــو ‪20898000‬ريــال واملبلــغ الــذي أخــذ مــن‬\n‫حســاب ابــن موكلتــي هــو قريــب خمســة وعشــرون مليــون ريــال وأوخــذ‬\n‫علــى دفعــات صغيــرة بينمــا مــا أودع البــن موكلتــي علــى دفعتــن كل‬\n‫دفعــة قرابــة عشــرة مليــون ريــال هكــذا أجــاب وعنــد وصــول الدعــوى‬\n‫عنــد هــذا احلــد رفعــت اجللســة الســاعة ‪ 01،45‬للتأمــل والنطــق باحلكــم‬\n‫ثــم يف يــوم الســبت ‪1434/05/25‬ه ـ افتتحــت اجللســة اخلامســة الســاعة‬\n‫‪ 01،40‬وفيهــا حضــر املدعــي (‪ )...‬ســعودي اجلنســية مبوجــب الهويــة‬\n‫الوطنيــة برقــم (‪ )...‬بصفتــه وكيــا عــن (‪ )...‬ســعودي اجلنســية مبوجــب‬\n‫الهويــة الوطنيــة رقــم (‪ )...‬الوكيــل عــن (‪ )...‬حســب الوكالــة الصــادرة‬\n‫مــن كتابــة العــدل الثانيــة شــمال محافظــة جــدة برقــم ‪ 60519‬وتاريــخ‬\n‫‪1430/6/22‬ه واملخــول لــه فيهــا حــق املطالبــة واملرافعــة واملدافعة وإقامة‬\n‫الدعــاوى وســماع الدعــاوى والــرد عليهــا وطلــب اليمــن واملدعــى عليــه‬\n‫وكالــة وقــد جــرى اطالعــي علــى احلكــم الصــادر مــن ســلفي فضيلــة‬\n‫الشــيخ (‪ )......‬رقــم ‪ 3339658‬وتاريــخ ‪1433/1/22‬ه بثبــوت وصيــة‬\n‫(‪ )...‬والــد املدعــن واملدعــى عليهــم وهــو يف حالــة معتبــرة شــرع ًا وقــد‬\n‫اكتســب احلكــم القطعيــة بتصديــق محكمــة االســتئناف مبوجــب‬\n‫قرارهــم ‪ 33332198‬وتاريــخ ‪1433/7/8‬ه ـ وحيــث أن مــن ضمــن‬\n‫الوصيــة إقامــة املدعــى عليهــم أوصيــاء علــى القصــر مــن أوالده كمــا هــو‬\n‫منصــوص يف وصيــة مــورث املدعــن واملدعــى عليهــم يف الصحيفــة رقــم‬\n\n\n                                                                                  ‫‪306‬‬\n\f      ‫‪ 6‬مــن صــك احلكــم وملــا أن وصــي األب مقــدم علــى غيــره كمــا نــص‬\n      ‫علــى ذلــك فقهــاء احلنابلــة (ينظــر كشــاف القنــاع للبهوتــي (‪)383/8‬‬\n      ‫والــكايف البــن قدامــه ( ‪ )251/3‬وملــا أن مــا قدمــه املدعــي وكالــة مــن‬\n      ‫قــدح يف مجلــس الوصايــة ال يرقــى إلــى عــزل أوصيــاء األب كمــا أن‬\n      ‫الصــك الصــادر مــن ســلفي قــد تطــرق فيــه املدعــون مبثــل هــذه األمــور‬\n      ‫ومت صــرف النظــر عنهــا وملــا أن مــورث القصــر مشــهور بالتجــارة وأن‬\n      ‫مــا ورثــه القصــر مــن أمــوال كثيــرة حتتــاج إلــى مجلــس وصايــة يقــوم‬\n      ‫بأعبائهــا ممــا قــد ال تســتطيع معــه املدعيــة القيــام بــه لــذا فقــد رددت‬\n      ‫دعــوى املدعــي بإلغــاء وصايــة املدعــى عليهــم علــى القصــر مــن أوالد (‪)...‬‬\n      ‫لتقــدمي وصــي األب علــى غيــره ولتحقــق املصلحــة يف إبقــاء أوصيــاء األب‬\n      ‫أوصيــاء علــى القصــر وبــه حكمــت وبعــرض احلكــم علــى املدعــي قــرر‬\n      ‫عــدم القناعــة وطلــب رفعــه حملكمــة االســتئناف فأفهمتــه باحلضــور غدا‬\n      ‫الســتالم نســخة احلكــم واالعتــراض عليهــا خــال مــدة أقصاهــا ثالثــون‬\n      ‫يومـ ًا مــن تاريخــه وإن لــم يعترضــوا فيســقط حقهــم يف االعتــراض وقــرر‬\n      ‫املدعــى عليــه وكالــة القناعــة واختتمــت اجللســة الســاعة ‪ 02،00‬وعليــه‬\n      ‫جــرى التوقيــع وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                            ‫وصحبــه وســلم حــرر يف ‪1434/5/25‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الثانيــة‬\n      ‫املختصــة بنظــر قضايــا األحــوال الشــخصية واإلنهــاءات مبحكمــة‬\n      ‫االســتئناف علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة العامــة‬\n      ‫برقــم (‪ ).........‬وتاريــخ ‪1434/7/16‬ه املرفــق بهــا الصــك الصــادر مــن‬\n      ‫فضيلــة القاضــي باحملكمــة الشــيخ‪ ).........( /‬املســجل برقــم (‪).........‬‬\n      ‫وتاريــخ ‪1434/5/27‬ه ـ اخلــاص بدعــوى (‪ ).........‬ضــد (‪ ).........‬بعــض‬\n\n\n‫‪307‬‬\n\f‫ورثــة (‪ ).........‬يف قضيــة إلغــاء واليــة علــى القصــر وقــد تضمــن الصــك‬\n‫حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه‪ .‬وبدراســة الصــك وصــورة‬\n‫ضبطــه والالئحــة االعتراضيــة وأوراق املعاملــة تقــرر الدائــرة املصادقــة‬\n‫علــى احلكــم ‪.‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد و علــى آلــه‬\n                                                            ‫وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                 ‫‪308‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"8772d0b1-3c0f-5928-9c22-98c49da1913e","source_page_start":285,"source_page_end":308,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"3ef4e3138015135a395198cff715eee03f11a8a680a22acbeb53e04b78cc5902","normalized_text_hash":"39d6e9641752ed0f89ed12e88a9d80fee6f4539d5e585c129fc14d3a03add5d7","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v4-p285-34223712"},{"id":"381596aa-51d1-5eb6-bbf3-eacccae14927","document_type":"judgment","category":"judicial","subcategory":"general","title":"والية -إلغاء والية اجلد ألب وجعلها للجدة ألم -إحالة الطرفن إلى قسم الصلح وردت بعدم اختصاصهم -البينة بشهادة الشهود العدول -كبر سن الولي وسوء حالته الصحية -احلكم بنقل صالحية الوالية للمدعية ورفعها عن اجلد وإقامتها وليه على","document_number":"34193719","case_number":"92430313","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بجدة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/28","year":"1434","subject":"والية -إلغاء والية اجلد ألب وجعلها للجدة ألم -إحالة الطرفن إلى قسم الصلح وردت بعدم اختصاصهم -البينة بشهادة الشهود العدول -كبر سن الولي وسوء حالته الصحية -احلكم بنقل صالحية الوالية للمدعية ورفعها عن اجلد وإقامتها وليه على","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/4/28 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪34193719 :‬‬\n                         ‫َر ْق ُم الدعوى‪92430313 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 34245184‬تاريخه‪1434/6/19:‬هـ‬\n\n\n      ‫واليــة ‪ -‬إلغــاء واليــة اجلــد ألب وجعلهــا للجــدة ألم ‪ -‬إحالــة الطرفــن‬\n      ‫إلــى قســم الصلــح وردت بعــدم اختصاصهــم ‪ -‬البينــة بشــهادة الشــهود‬\n      ‫العــدول ‪ -‬كبــر ســن الولــي وســوء حالتــه الصحيــة ‪ -‬احلكــم بنقــل‬\n      ‫صالحيــة الواليــة للمدعيــة ورفعهــا عــن اجلــد وإقامتهــا وليــه علــى‬\n                                                                        ‫القصــر‪.‬‬\n\n\n\n\n                 ‫‪ .1‬قول تعالى (وال تقربوا مال اليتيم إال بالتي هي أحسن)‪.‬‬\n      ‫‪ .2‬قــال يف كشــاف القنــاع ‪( 443/3‬وال يجــوز لوليهمــا أي الصغيــر‬\n           ‫واملجنــون أن يتصــرف يف مالهمــا إال علــى وجــه احلــظ لهمــا)‪.‬‬\n\n\n\n\n      ‫ادعــت جــدة الم دعــوى تطالــب بإلغــاء واليــة اجلــد ألب علــى القصــر مــن‬\n      ‫أوالد ابنتهــا وجعلهــا لهــا وذكــرت أن املدعــى عليــه كبيــر يف الســن‬\n      ‫وال يســتطيع القيــام بأعبــاء الواليــة وأنــه أصــدر وكالــة إلبنــه الــذي هــو‬\n      ‫عــم األوالد للقيــام بشــؤون القصــر وأن املدعــى عليــه ووكيلــه لــم يقومــا‬\n      ‫بــأي شــيء جتــاه القاصريــن ‪ -‬صــادق املدعــى عليــه علــى الواليــة وأنــه‬\n      ‫لــم يقــم بشــيء جتــاه القاصريــن وادعــى أن ذلــك كان بســبب املدعيــة‬\n      ‫ألنهــا منعتــه مــن مشــاهدة القصــر ملــدة ســنتني ورفــض نــزع الواليــة منــه‬\n\n‫‪309‬‬\n\f‫‪ -‬حاولــت احملكمــة اإلصــاح بــن الطرفــن فلــم يصطلحــا وقــررت‬\n‫احملكمــة إحالــة الطرفــن لقســم الصلــح يف هــذه احملكمــة بــا جــدوى‬\n‫ثــم حضــرت املدعيــة ووكيــل املدعــى عليــه وذكــر وكيــل املدعــى عليــه‬\n‫أنــه يرقــد باملستشــفى للعــاج وأحضــرت املدعيــة معهــا شــاهدين شــهد ًا‬\n‫بأنهــا ذات أمانــة وكفــاءة وديانــة واقتــدار وجرى تعديل الشــاهدين وبناء‬\n‫عليــه ونظــر ًا لكبــر ســن املدعــى عليــه وســوء حالتــه الصحيــة وإلقــراره‬\n‫بأنــه لــم يعمــل شــيء جتــاه القاصريــن وألن املدعيــة جــدة للقصــر مــن‬\n‫جهــة األم لــذا ثبــت لــدى احملكمــة صالحيــة املدعيــة ألن تكــون وليــة‬\n‫علــى القصــر وقــررت نقــل الواليــة لهــا وأمرتهــا بالقيــام بشــؤون القصــر‬\n‫يف كل مــا يخصهــم‪ ،‬قــرر املدعــى عليــه عــدم القناعــة‪ ،‬صــدق احلكــم‬\n                                                  ‫مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد فلــدي‬\n‫أنــا (‪ ).....‬القاضــي يف احملكمــة العامــة بجــدة وبنــاء علــى املعاملــة‬\n‫احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة بجــدة املســاعد وتاريــخ‬\n‫‪1432/04/08‬ه ـ املقيــدة باحملكمــة وتاريــخ ‪1432/04/08‬ه ـ حضرت‬\n‫(‪ ).....‬ســعودي اجلنســية ولــم يحضــر املدعــى عليــه وال مــن ينــوب عنــه وقــد‬\n‫تبلــغ باملوعــد فادعــت قائلــة يف دعواهــا لقــد أصــدر فضيلــة ســلفكم‬\n‫الشــيخ (‪ ).....‬الصــك يف ‪1431/01/04‬ه ـ املتضمــن إقامــة املدعــى عليــه‬\n‫ولي ـ ًا علــى أحفــادي أوالد مــن ابنتــي ومبــا أن املدعــى عليــه طاعــن يف‬\n‫الســن ويبلــغ مــن العمــر ثمانــن عام ـ ًا وهــو ضعيــف البصــر ممــا جعلــه‬\n‫غيــر قــادر علــى القيــام بأعبــاء الواليــة علــى القصــر كمــا أنــه قــد أصــدر‬\n\n                                                                                       ‫‪310‬‬\n\f      ‫صــك وكالــة لعــم القصــر وهــو ابــن املدعــى عليــه ولــم يقــم املدعــى عليــه‬\n      ‫وال وكيلــه بــأي شــيء جتــاه القاصريــن لــذا أطلــب نــزع الواليــة منــه‬\n      ‫واحلكــم بهــا لــي هــذه دعــواي ويف جلســة أخــرى حضــرت املدعيــة (‪).....‬‬\n      ‫حضــر حلضورهــا (‪ ).....‬ســعودي اجلنســية ثــم جــرى عــرض الدعــوى علــى‬\n      ‫املدعــى عليــه فقــال مــا ذكرتــه املدعيــة من صك الواليــة ورقمه وتاريخه‬\n      ‫ومصــدره ومــا تضمنــه فهــو صحيــح ومــا ذكرتــه مــن أننــي طاعــن يف‬\n      ‫الســن وأننــي أبلــغ مــن العمــر ثمانــن عام ـ ًا فهــو غيــر صحيــح فأنــا مــن‬\n      ‫مواليــد عام‪1359‬ه ـ حســب مــا يتضــح لفضيلتكــم مــن بطاقــة الهويــة‬\n      ‫الوطنيــة ومــا ذكرتــه مــن أننــي ضعيــف البصــر فهــو صحيــح ولكــن‬\n      ‫ذلــك ال يطعــن يف واليتــي عليهــم ومــا ذكرتــه مــن أننــي لــم أقــم بشــيء‬\n      ‫جتــاه القاصريــن فهــو صحيــح ولكــن ذلــك بســبب املدعيــة لكونهــا‬\n      ‫منعتنــي مــن مشــاهدة أحفــادي القصــر ملــدة ســنتني وال أوافــق علــى نــزع‬\n      ‫الواليــة منــي وجعلهــا للمدعيــة هكــذا أجــاب وبعــد ســماع الدعــوى‬\n      ‫واإلجابــة جــرى منــي محاولــة اإلصــاح بــن الطرفــن فلــم يصطلحــا ثــم‬\n      ‫أبــرزت املدعيــة الصــك يف ‪1431/07/14‬ه ـ الصــادر مــن هذه احملكمة‬\n      ‫املتضمــن احلكــم بحضانــة القصــر للمدعيــة ضــد املدعــى عليــه ونظــر ًا‬\n      ‫لوجــود القرابــة والرحــم بــن الطرفــن فقــد قــررت إحالــة الطرفــن إلــى‬\n      ‫قســم الصلــح يف هــذه احملكمــة حملاولــة اإلصــاح بــن الطرفــن ورفعــت‬\n      ‫اجللســة لذلــك ويف جلســة أخــرى حضــرت املدعيــة واملعــرف بهمــا مــن‬\n      ‫قبــل زوجهــا (‪ ).....‬ســعودي اجلنســية وحضــر حلضورهــا املدعــى عليــه وقــد‬\n      ‫كانــت جــرت الكتابــة لقســم االصــاح من أجل االصــاح بني الطرفني‬\n      ‫مبوجــب خطابنــا يف ‪1433/03/13‬ه ـ فعــادت إلينــا بشــرحهم املــؤرخ يف‬\n      ‫‪1433/04/20‬ه ـ املتضمــن عــدم مراجعــة الطرفــن أ‪ .‬ه ـ ‪ .‬وبعــرض ذلــك‬\n\n\n‫‪311‬‬\n\f‫علــى الطرفــن اســتعدا مبراجعــة قســم االصــاح ورفعــت اجللســة لذلــك‬\n‫ويف جلســة اخــرى حضــرت املدعيــة واملعــرف ولــم يحضــر املدعــى عليــه‬\n‫وال مــن ينــوب عنــه وقــد تبلــغ باملوعــد وقــد كانــت جــرت الكتابــة لقســم‬\n‫اإلصــاح مبوجــب خطابنــا يف ‪1433/08/11‬ه ـ فعــادت إلينــا بشــرحهم‬\n‫املــؤرخ يف ‪1433/12/21‬ه ـ املتضمــن عــدم اختصاصهم وســألت املدعية‬\n‫عــن البينــة التــي وعــدت بإحضارهــا فقالــت أطلــب إمهالــي إلحضارهــا‬\n‫ورفعــت اجللســة لذلــك ويف جلســة اخــرى حضــرت املدعيــة واملعــرف (‪).....‬‬\n‫واملدعــى عليــه وكالــة (‪ ).....‬ســعودي اجلنســية بالوكالــة عــن مبوجــب‬\n‫الوكالــة يف ‪1431/12/03‬ه ـ الصــادرة مــن كتابــة العــدل الثانيــة (‪).....‬‬\n‫وبســؤال املدعــى عليــه وكالــة عــن ســبب عــدم حضــور موكلــه اجللســة‬\n‫الســابقة قــال إن موكلــي ‪ -‬وهــو والــدي ‪ -‬يرقــد يف املستشــفى حاليــا‬\n‫للعــاج مــن الغرغرينــة هكــذا أجــاب وبســؤال املدعيــة عــن البينــة التــي‬\n‫وعــدت بإحضارهــا أحضــرت (‪ ).....‬ســعودي اجلنســية وبســؤاله عمــا لديه‬\n‫قــال أشــهد هلل تعالــى أن املدعيــة صاحلــة للواليــة علــى أحفادهــا القصــر‬\n‫أوالد وهــي ذات أمانــة وكفــاءة وديانــة واقتــدار هكــذا شــهد كمــا‬\n‫أحضــرت املدعيــة للشــهادة (‪ ).....‬ســعودي اجلنســية وبســؤاله عمــا لديــه‬\n‫قــال أشــهد هلل تعالــى أن املدعيــة صاحلــة للواليــة علــى أحفادهــا القصــر‬\n‫أوالد وهــي ذات أمانــة وكفــاءة وديانــة واقتــدار هكــذا شــهد وبعــرض‬\n‫الشــهود وشــهادتهم علــى املدعــى عليــه وكالــة قــال ال نعرفهــم وال نقــول‬\n‫فيهــم شــيئا غيــر أن موكلــي يرفــض نقــل الواليــة للمدعيــة هكــذا قــرر‬\n‫وبســؤال املدعيــة هــل لديهــا معدلــن لشــهودها قالــت نعــم وأحضــرت‬\n‫(‪ ).....‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم (‪ ).....‬وبســؤاله‬\n‫عمــا لديــه قــال أشــهد هلل تعالــى أن الشــاهدين أوالد (‪ ).....‬عــدالن‬\n\n\n                                                                                   ‫‪312‬‬\n\f      ‫ثقتــان هكــذا شــهد كمــا أحضــرت (‪ ).....‬ســعودي اجلنســية مبوجــب‬\n      ‫الســجل املدنــي رقــم (‪ ).....‬وبســؤاله عمــا لديــه قــال أشــهد هلل تعالــى‬\n      ‫أن الشــاهدين أوالد (‪ ).....‬عــدالن ثقتــان هكــذا شــهد فبنــاء علــى مــا‬\n      ‫تقــدم مــن الدعــوى واإلجابــة وشــهادة الشــاهدين املعدلــن شــرع ًا ونظــر ًا‬\n      ‫لكبــر ســن املدعــى عليــه أصالــة وســوء حالتــه الصحيــة وملــا انــه قــد تبني‬\n      ‫مــن حضــوره يف جلســة ســابقة أنــه رجــل مقعــد ونظــرا إلقــراره بأنــه لــم‬\n      ‫يقــم بشــيء جتــاه القاصريــن وألن مــا بــرر بــه مــن أن عــدم قيامــه بذلــك‬\n      ‫هــو بســبب منــع املدعيــة لــه مــن مشــاهدة أحفــاده القصــر ‪ -‬علــى فــرض‬\n      ‫صحتــه وثبوتــه ‪ -‬غيــر ســائغ إذ ال ذنــب للقصــر يف ذلــك وذلــك يلحــق‬\n      ‫الضــرر بهــم وكان الواجــب عليــه أن يقــوم مبــا فيــه األحــظ للقصــر قــال‬\n      ‫يف كشــاف القنــاع ‪ 447/3‬وال يجــوز لوليهمــا أي الصغيــر واملجنــون أن‬\n      ‫يتصــرف يف مالهمــا إال علــى وجــه احلــظ لهمــا لقولــه تعالــى (وال تقربــوا‬\n      ‫مــال اليتيــم إال بالتــي هــي احســن) وألن املدعيــة جــدة للقصــر مــن جهــة‬\n      ‫األم لــذا كلــه فقــد ثبتــت لــدي صالحيــة املدعيــة ألن تكــون وليــا علــى‬\n      ‫القصــر املذكوريــن وقــررت نقــل الواليــة مــن املدعــى عليــه أصالــة إلــى‬\n      ‫املدعيــة وأقمتهــا وليــا علــى القصــر أوالد ترعــى شــؤونهم وحتافــظ علــى‬\n      ‫مصاحلهــم وتخاصــم وتدافــع عــن حقوقهــم ولهــا احلــق يف البيــع والشــراء‬\n      ‫واإلفــراغ وقبولــه واســتالم الثمــن والتأجيــر واســتالم األجــرة وتوقيــع‬\n      ‫العقــود واســتالم جميــع مــا لهــم مــن حقــوق واملطالبــة بهــا واملداعــاه‬\n      ‫واملخاصمــة وســماع الدعــوى والــرد عليهــا وإقامــة البينــة والرفــع يف‬\n      ‫أي قضيــة تقــام منهــم أو ضدهــم أمــام أي محكمــة ويف أي جهــة ولهــا‬\n      ‫مراجعــة الدوائــر احلكوميــة واملؤسســات والشــركات واألفــراد وأي‬\n      ‫جهــة أخــرى يف جميــع املعامــات اخلاصــة بهــم وإنهــاء كافــة اإلجــراءات‬\n\n\n‫‪313‬‬\n\f‫الشــرعية واإلداريــة املتعلقــة بذلــك ولهــا حــق توكيــل الغيــر وأفهمتهــا‬\n‫بــأن عليهــا أن ال تتصــرف بشــيء مــن عقــارات القاصريــن ببيــع أو شــراء‬\n‫أو بــدل إال بــإذن مــن حاكــم شــرعي وان تقــدم بيان ـ ًا ســنوي ًا مبــا قامــت‬\n‫بــه جتــاه أمــوال وحقــوق القاصريــن املذكوريــن ومبــا تقــدم حكمــت‬\n‫وبعــرض احلكــم علــى املدعــى عليــه وكالــة قــرر عــدم القناعــة وطلــب‬\n‫التمييــز فأجيــب لطلبــه وجــرى إفهامــه بــأن عليــه املراجعــة يــوم االثنــن‬\n‫املوافــق ‪1434/4/22‬ه ـ الســتالم نســخة مــن صــك احلكــم لالعتــراض‬\n‫عليــه وأن عليــه تقــدمي اعتراضــه خــال ثالثــن يومــا تبــدأ مــن التاريــخ‬\n‫املذكــور فــإن تأخــر عــن ذلــك ســقط حقــه يف االعتــراض واكتســب‬\n‫احلكــم القطعيــة وختمــت اجللســة الســاعة ‪08 : 45‬وبــاهلل التوفيــق‬\n‫‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n                                                              ‫‪1434/04/20‬ه ـ‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ويف يــوم‬\n‫الثالثاء املوافق ‪1434/07/04‬هـ افتتحت اجللســة بعد أن عادت املعاملة‬\n‫مــن محكمــة االســتئناف وبرفقهــا القــرار يف ‪1434/06/19‬ه ـ ونــص‬\n‫احلاجــة منــه (وبدراســة الصــك وصــورة ضبطــه والئحتــه االعتراضيــة‬\n‫تقــرر باألكثريــة املوافقــة علــى احلكــم مــع مالحظــة التنبيــه) قاضــي‬\n‫اســتئناف (‪ ).....‬ختــم وتوقيــع قاضــي اســتئناف (‪ ).....‬ختــم وتوقيــع رئيــس‬\n‫الدائــرة ‪ -‬لــي وجهــة نظــر ‪ -‬ختــم وتوقيــع ‪ ،‬وحتــى ال يخفــى أمــرت‬\n‫بإثباتــه علــى ضبطــه وســجله ‪ ،‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n                 ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/7/4‬ه ـ‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد فقــد‬\n‫جــرى منــا نحــن قضــاة الدائــرة الثالثــة لألحــوال الشــخصية واألوقــاف‬\n\n\n                                                                                     ‫‪314‬‬\n\f      ‫والوصايــا والقصــار وبيــوت املــال مبحكمة االســتئناف يف منطقة مكة‬\n      ‫املكرمــة االطــاع علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة‬\n      ‫العامــة املســاعد وتاريــخ ‪1434/6/7‬ه املرفــق بهــا الصــك الصــادر مــن‬\n      ‫فضيلــة الشــيخ (‪ ).....‬القاضــي باحملكمــة العامة وتاريخ ‪1434/4/21‬هـ‬\n      ‫‪ ،‬املتضمــن طلــب املــرأة نــزع واليــة عــن أحفادهــا‪ ،‬وبدراســة الصــك‬\n      ‫وصــورة ضبطــه والئحتــه االعتراضيــة تقــرر باألكثريــة املوافقــة علــى‬\n      ‫احلكــم مــع مالحظــة التنبيــه املرفــق‪ ،‬واهلل املوفــق ‪ .‬وصلــى اهلل علــى‬\n                                       ‫نبينــا محمــد وعلــى الــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪315‬‬\n\f316\n\f317\n\f318\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"8772d0b1-3c0f-5928-9c22-98c49da1913e","source_page_start":309,"source_page_end":318,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"a976bac48e0a5b7d31e6c37d479532318406284d349db829ba94263fd633ae2c","normalized_text_hash":"f6acc1e734ce03c4e089d1a843fcafb8747b4b15406f6d1473d0b651b330d160","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v4-p309-34193719"},{"id":"23434c3a-12ef-5b08-bbff-b6f635102d5a","document_type":"judgment","category":"judicial","subcategory":"general","title":"حجر -حجر لسفه -ابن يطالب باحلجر على والده لسفه بتبديد املال وصرفه يف غير مصلحه ومنع مستحقه -إنكار املدعى عليه والدفع بأن املدعى ولد عاق وغير سوي -ثبوت سامة املدعي عليه من الناحية النفسية والعقلية -صرف النظر عن دعوى املدعى .","document_number":"34209994","case_number":"50077","judgment_number":null,"decision_number":null,"circular_number":null,"court":null,"circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/9/17","year":"1434","subject":"حجر -حجر لسفه -ابن يطالب باحلجر على والده لسفه بتبديد املال وصرفه يف غير مصلحه ومنع مستحقه -إنكار املدعى عليه والدفع بأن املدعى ولد عاق وغير سوي -ثبوت سامة املدعي عليه من الناحية النفسية والعقلية -صرف النظر عن دعوى املدعى .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/9/17:‬هـ‬\n                      ‫ُ‬                ‫َر ْق ُم َّ‬\n                         ‫الص ِّك‪34209994 :‬‬\n                           ‫َر ْق ُم الدعوى‪50077 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n               ‫‪ 34295203‬تاريخه‪1434/8/13 :‬هـ‬\n\n\n      ‫حجــر ‪ -‬حجــر لســفه ‪ -‬ابــن يطالــب باحلجــر علــى والــده لســفه بتبديــد‬\n      ‫املــال وصرفــه يف غيــر مصلحــه ومنــع مســتحقه ‪ -‬إنــكار املدعــى عليــه‬\n      ‫والدفــع بــأن املدعــى ولــد عــاق وغيــر ســوي ‪ -‬ثبــوت ســامة املدعــي عليــه‬\n         ‫مــن الناحيــة النفســية والعقليــة ‪ -‬صــرف النظــر عــن دعــوى املدعــى ‪.‬‬\n\n\n\n\n      ‫مــا أســتند إليــه القاضــي مــن القواعــد العامــة ومبــادئ العدالــة يف‬\n                                                             ‫تســبيب حكمــه‪.‬‬\n\n\n\n\n      ‫إقامــة ابــن دعــوى حجــر علــى والــده لســفهه ‪ ،‬ذكــر املدعــي أن املدعــى‬\n      ‫عليــه يقــوم بتبديــد األمــوال ورهــن املنــازل وحتمــل الديــون وتواجــده‬\n      ‫خــارج البــاد بشــكل دائــم وإهمالــه ألهــل بيتــه وعــدم اإلنفــاق عليهــم‬\n      ‫النفقــة الواجبــة وذكــر تصرفــات لوالــده اســتدل بهــا علــى ســفهه ‪ ،‬لــم‬\n      ‫تعتبــر احملكمــة هــذا التصرفــات موجبــه إلثبــات ســفه املدعــى عليــه ‪،‬‬\n      ‫انكــر املدعــى عليــه مــا جــاء يف دعــوى املدعــي وذكــر بــأن املدعــي عــاق‬\n      ‫ويتعاطــى املخــدرات وأن بينــه وبــن املدعــى عــدة دعــاوى ‪ ،‬طلــب املدعــي‬\n      ‫الكشــف علــى والــده لتحديــد ســامته مــن املــرض ‪ ،‬قــررت احملكمــة‬\n      ‫الكتابــة للمستشــفى املختــص ‪ ،‬فــورد تقريــر مــن اجلهــة املختصــة يثبــت‬\n\n‫‪319‬‬\n\f‫ســامة املدعــى عليــه مــن الناحيــة النفســية والعقليــة ‪ ،‬لــذا حكمــت‬\n‫احملكمــة بصــرف النظــر عــن دعــوى املدعــى ‪ ،‬اعتــرض املدعــي علــى‬\n                 ‫احلكــم ‪ ،‬صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ ).....‬القاضــي يف احملكمــة العامــة‬\n‫بالريــاض حضــر وحضــر حلضــوره وادعــى األول قائـاً‪ :‬إن دعــواي علــى‬\n‫والــدي علــى قيامــه بتبديــد أمــوال التركــه ورفــع دعــوى علــى والــده بعــد‬\n‫املمــات مبطالبــة ماليــة ومطالبــة الورثــة ببيــع الوقــف جلــدي ورهــن املنــازل‬\n‫التــي نعيــش بهــا وحتميلنــا ديــون ملصلحتــه وتواجــده خــارج الســعودية‬\n‫بشــكل دائــم وهــو مبتلــى بفتنــة النســاء وظلمــه لنــا ولوالدتنــا ونحــن‬\n‫جاهــزون لتحضيــر الشــهود أنــا وإخوتــي وأطلــب احلجــر علــى والــدي‬\n‫لعــدم أهليتــه يف صــرف األمــوال وحمايتــه مــن نفســه وحمايتنــا منــه ورد‬\n‫حقــوق النــاس هــذه دعــواي وبعــرض دعــوى املدعــي علــى املدعــى عليــه‬\n‫وكالــة أجــاب جوابـ ًا محــرر ًا هــذا نصــه ‪ :‬احلمــد هلل علــى مــا قــدر واحلمد‬\n‫هلل علــى مــا شــاء وكمــا قــال تعالــى وقولــه احلــق جــل يف عــاه يف كتابــه‬\n‫الكــرمي (إن مــن أزواجكــم وأوالدكــم عــدو لكــم) ســورة التغابــن‬\n‫اســمحوا لــي أن لوضــح لكــم الوقائــع الســابقة بينــي وبــن املدعــي (‬\n‫ابنــي العــاق ) وهــي مــا يلــي ‪ -1 :‬قــام ابنــي العــاق يف بيــع عــدد ‪ 52‬تأشــيرة‬\n‫واملســجلة باســم مؤسســة (‪ ).......‬للديكــورات لصاحبهــا (‪ ،).......‬قــام‬\n‫ابنــي العــاق ببيعهــا ملؤسســات وشــركات وبــدون علمــي وموافقتــي‬\n‫وجــراء بيعــه للتأشــيرات فقــد ضــر مبصاحلــي التجاريــة وبعــد مناقشــة‬\n‫ابنــي العــاق بشــان بيعــه للتأشــيرات قــام بتهديــدي بالقتــل والتلفــظ علــى‬\n\n                                                                                         ‫‪320‬‬\n\f      ‫باســوا األلفــاظ التــي ال تليــق بابــن عاقــل أن يتلفــظ بهــا علــى والــده ويف‬\n      ‫العشــر األواخــر مــن رمضــان مــن عــام ‪1431‬ه ـ قامــت الدوريــات األمنيــة‬\n      ‫بالقبــض عليــه للشــك يف تعاطيــه للمخــدرات ‪ ،‬وبعــد إجــراء الكشــف‬\n      ‫الطبــي عليــه ثبــت تعاطيــه للمخــدرات بنــاء علــى التقريــر الطبــي الصــادر‬\n      ‫مــن مستشــفى (‪ ).......‬والــذي ســبق وان زودناكــم بصــورة منــه ومرفــق‬\n      ‫صــورة منــه ‪-2 .‬تفاجئــت يف يــوم عيــد الفطــر لعــام ‪ 1431‬ه ـ بخــروج ابنــي‬\n      ‫العــاق مــن املستشــفى مــع املفتــرض أن يبقــي فتــرة طويلــة متتــد ألشــهر‬\n      ‫للعــاج فــا أعلــم كيــف خــرج مــن املستشــفى ‪ ،‬ولهــذا الســبب قــرر‬\n      ‫أن ينتقــم منــي برفعــه لهــذه الدعــوى املنظــورة لــدي فضيلتكــم فضيلــة‬\n      ‫الشــيخ أفيدكــم بأنــه بتاريــخ ‪1432/03/12‬ه ـ تقدمــت بخطــاب‬\n      ‫لصاحــب الســمو امللكــي األميــر (مرفــق صــورة مــن اخلطــاب) ومت إحالــة‬\n      ‫اخلطــاب مــن أمــارة الريــاض إلــي احملكمــة اجلزئيــة لنظــر موضوعــي‬\n      ‫شــرع ًا ضــد ابنــي العــاق وقامــت احملكمــة اجلزئيــة بإحالــة ملــف القضيــة‬\n      ‫إلــى فضيلــة الشــيخ الدكتــور (‪ ، ).......‬حيــث تتعلــق الدعــوى بعقــوق‬\n      ‫ابنــي ولكــن تخلــف ابنــي عــن حضــور اجللســات ومت طلبــه أكثــر مــن‬\n      ‫مــرة مــن فضيلــة القاضــي واتصــل بــه عــدة مــرات ولــم يحضــر ‪ ،‬وقــد‬\n      ‫أرســل فضيلــة القاضــي ملركــز شــرطة امللــز خطاب ـ ًا ذي الرقــم ‪5699‬‬\n      ‫وتاريــخ ‪1432/8/17‬ه ـ للقبــض عليــه بالقــوة وإحضــاره مخفــور ًا ومت‬\n      ‫التعميــم عليــه يف املباحــث إلحضــاره للقبــض عليــه بالقــوة اجلبرية ولكن‬\n      ‫لــم يتــم القبــض عليــه حتــى هــذا التاريــخ وال يــزال حــر ًا طليق ـ ًا وميــارس‬\n      ‫إدمانــه للمخــدرات ‪ ،‬واملباحــث يف أدارة مكافحــة املخــدرات تبحــث‬\n      ‫عنــه ألكثــر مــن أربعــة شــهور ولــم جتــده حتــى اآلن فضيلــة الشــيخ كمــا‬\n      ‫أوضحــت يف اجللســة الســابقة لفضيلتكــم بأننــي تأســفت بــان املدعــي‬\n\n\n‫‪321‬‬\n\f‫ابنــي الــذي قمــت طــوال هــذه الســنوات املنطويــة بتربيتــه وتعليمــه يف‬\n‫ارقــي اجلامعــات وتكلفــت بتكاليــف زواجــه كاملــة مــن مهــر ومعيشــة‬\n‫كرميــة وقدمــت لــه مــن التســهيالت املاليــة فــوق حاجتــه وســلمته اجلمــل‬\n‫ومــا حمــل وحــررت لــه وكاالت شــرعية ( مرفــق صــورة منهــا ) يحــق لــه‬\n‫البيــع والشــراء والقبــض وغيرهــا مــن الصالحيــات وقــد ضعفــت نفســه‬\n‫الدنيئــة للشــيطان واســتجاب لشــياطني اإلنــس واجلــن وأصبــح عــدوا لــي‬\n‫ويريــد احلجــر علــي وأن يســتحل مالــي بــدون مســوغ شــرعي أو نظامــي‪.‬‬\n‫احلمــد هلل وحــده وبعــد فلــدي (‪ ).......‬القاضــي يف احملكمــة العامــة‬\n‫بالريــاض ففــي يــوم الســبت املوافــق ‪1433/03/19‬ه ـ افتتحــت اجللســة‬\n‫الســاعة ‪10 : 30‬ص لســماع دعــوى ضــد وفيهــا حضــر املدعــى عليــه‬\n‫ولــم يحضــر املدعــي أو مــن ينــوب عنــه يف هــذه اجللســة وقــد قــدم املدعــي‬\n‫طلــب تأجيــل الدعــوى برقــم يف ‪1433/03/14‬ه ـ لكونــه غيــر متواجــد‬\n‫يف هــذا التاريــخ احملــدد لســماع الدعــوى وعليــه رفعــت اجللســة حلــن‬\n‫مراجعــة املدعــي وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n‫آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1433/03/19‬ه ـ الســاعة احلاديــة عشــرة‬\n                                                                         ‫صباحــا‪.‬‬\n‫احلمــد هلل وحــده وبعــد ففــي يــوم الثالثــاء املوافــق ‪1434/03/17‬ه ـ‬\n‫افتتحــت اجللســة الســاعة ‪09 : 00‬وفيهــا حضــر الطرفــان ولــم يحــرر‬\n‫املدعــي رده علــى مــا جــاء يف جــواب املدعــى عليــه يف اجللســة املاضيــة‬\n‫وجــرى إفهــام املدعــي بتحريــر دعــواه ورفعــت اجللســة وتأجلــت ليــوم‬\n‫األربعــاء ‪1434/5/1‬ه ـ الســاعة ‪ 11 : 30‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل‬\n‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/3/17‬ه ـ‬\n‫فضيلــة الشــيخ أن ابنــي العــاق أخــذ برفــع هــذه الدعــوى ليمــارس االنتقام‬\n\n\n                                                                                    ‫‪322‬‬\n\f      ‫والضغــط العصبــي ضــدي ويكســب مــن وراءهــا التســتر علــى أعمالــي‬\n      ‫واســتغالله للــوكاالت الشــرعية الصــادرة لــي واســتغل كبــر ســني يف‬\n      ‫عــدم متابعتــه للجلســات القضائيــة والرضــوخ لــي ولكــن فــات علــى ابني‬\n      ‫ا‬\n      ‫العــاق بانــه اســتمد قوتــه مــن اهلل ســبحانه وتعالــي والدعــاء عليــه لي ـ ً‬\n      ‫ونهــار ًا ويف الســر والعالنيــة فضيلــة الشــيخ اطلــب مــن فضيلتكم صرف‬\n      ‫النظــر عــن الدعــوى وعــدم التأخيــر يف البــت يف هــذه القضيــة مــع حفــظ‬\n      ‫كامــل حقوقــي الشــرعية والنظاميــة ضــد ابنــي العــاق ومــا ســببه لــي‬\n      ‫مــن أســى وتعــب جــراء تصرفاتــه بحقــي هكــذا أجــاب وبعــرض جــواب‬\n      ‫املدعــى عليــه علــى املدعــي قــال أطلــب مهلــة للجــواب جواب ـ ًا محــرر ًا يف‬\n      ‫اجللســة القادمــة ‪ .‬ويف جلســة أخــرى حضــر املدعــي وحضــر حلضــوره‬\n      ‫املدعــى عليــه يرافقــه بصفتــه وكيــا عنــه مبوجــب الوكالــة والصــادرة‬\n      ‫مــن كتابــة العــدل الثانيــة بالريــاض واملخــول لــه فيهــا باملطالبــة واملرافعة‬\n      ‫واإلقــرار والصلــح والتنــازل ‪ ...‬إلــخ وبســؤال املدعــي عمــا اســتمهل مــن‬\n      ‫ا أن مــا طرحــه خصمــي يف دعــواي مــن أننــي ابــن‬          ‫أجلــه أجــاب قائ ـ ً‬\n      ‫عــاق واســتخدم مخــدرات فاجلــواب أن فحــوى قضيتنــا هــذه أننــي أطلــب‬\n      ‫احلجــر علــى الوالــد لســفهه وعــدم حســن تصرفــه باملــال وأطلــب إصــدار‬\n      ‫صــك واليــة عليــه وردي علــي ادعائــه أننــي ابــن عــاق فهــذه قضيــة أخــري‬\n      ‫ومنظــورة لــدي فضيلــة القاضــي (‪ ).......‬باحملكمــة اجلزئيــة وقــد انتهــت‬\n      ‫بحفظهــا لــدي القاضــي بعــد حضــوري للجلســة وتقــدمي كفالــة حضوريــة‬\n      ‫حلضــوري يف أي وقــت يتــم اســتدعائي وأنــا مســتعد وجاهــز وبالنســبة‬\n      ‫الدعائــه أننــي اســتخدم مخــدرات وســارق فقــد صــدر تقريــر مــن إمــارة‬\n      ‫الريــاض ببطــان هــذا االدعــاء وجتــدون القــرار لديكــم يف األوراق‬\n      ‫ولــدي منــه صــورة أعــود إلــى صلــب املوضــوع فــإن والــدي قــد اســتلم‬\n\n\n‫‪323‬‬\n\f‫مبلــغ حوالــي ‪ 70‬مليــون ريــال ورثــه مــن والــده منــذ ثــاث ســنوات تقريبــا‬\n‫ولديكــم اإلثبــات ولــدي منهــا صــوره أيــن املــال اآلن ولدينــا بينــه اآلن‬\n‫أنــه يتســلف مبالــغ صغيــرة مــن العمــال وكذلــك يســكن شــقة إيجــار‬\n‫وكذلــك مت توقيفــه بشــرطه امللــز بقضيــه مبلــغ ‪170‬الــف ريــال إضافــة‬\n‫إلــى أن والــدي قــام ببيــع عمــارة بامللــز مببلــغ ثالثــة ماليــن وثالثمائة ألف‬\n‫ريــال يف ‪1432/9/2‬ه ـ وهــي مســيومة مببلــغ أربعــة ماليــن وســتمائة‬\n‫ألــف ريــال عــن طريــق مكتــب (‪ ).......‬العقــاري وخالــي كان وســيطا‬\n‫ثــم بعــد خمســة أشــهر مت توقيــف والــدي بشــرطة امللــز يف ‪1433/2/1‬ه ـ‬\n‫أطلــب ســؤاله أيــن ذهــب املــال الثالثــة ماليــن خــال اخلمســة أشــهر‬\n‫فأنــا ادعــي أن والــدي بــاع هــذه العمــارة ســفها حيــث باعهــا بأقــل مــن‬\n‫قيمتهــا مبليــون ريــال واعتقــد شــرع ًا أن هــذا مبــرر قــوي لرفــع واليتــه‬\n‫عــن البيــع والشــراء وبالنســبة إلضاعــة املــال خــال خمســة أشــهر ولدينــا‬\n‫الدليــل وهــذا يعتبــر تفريــط وهــذان املبــرران أعتقــد أنهمــا كافيــان‬\n‫لنــزع واليتــه علــى التصــرف باملــال كمــا أن والــدي بــاع فيــا بالربــوة‬\n‫قبــل أربعــن يومــا تقريبــا مببلــغ ثالثــة ماليــن ومائتــي ألــف ريــال فأطلــب‬\n‫ســؤاله أيــن ذهــب هــذا املــال وأطلــب مــن احملكمــة نــدب جلنــة لتقييــم‬\n‫العقــار ألننــي اعتقــد أنــه بــاع هــذا العقــار بالنقــص مــن قيمتــه بكثيــر‬\n‫وبالنســبة لألمــور الباقيــة لــدى والــدي والتــي معــي عليهــا دليــل وهــي‬\n‫التــي دفعتنــي لطلــب احلجــر عليــه هــي متلكــه لقصــر باملغــرب وللعلــم فــان‬\n‫والــدي قــد طلــب منــي أن أتنــازل عــن أرضــه بحائــل أو أنــه ســوف يتعامــل‬\n‫معــي بقســاوة ولــدي دليــل علــى مســاومته وعنــدي شــاهد ضابــط يعمــل‬\n‫بالشــرطة وأنــا مســتعد بإحضــاره وبالنســبة الدعائــه بتربيتنــا فلتعلــم‬\n‫احملكمــة أن أكثــر إقامتــه كانــت باملغــرب وتركنــي أنــا ووالدتــي‬\n\n\n                                                                                       ‫‪324‬‬\n\f      ‫بحائــل وبإمــكان احملكمــة طلــب تقريــر مــن جــوزات الريــاض عــن‬\n      ‫عــدد الســنوات التــي أقامهــا يف املغــرب وقبــل ذلــك كان يقيــم بالريــاض‬\n      ‫وأطلــب تقريــر حديــث مــن الصحــة النفســية لتحديــد ســامة والــدي‬\n      ‫مــن املــرض النفســي وقــد أحضــر للمحكمــة تقريــر حديــث يفيــد أنــه‬\n      ‫ســليم وأن ملفــه جديــد لــم يتعــد أشــهر وهــذا باطــل ولدينــا الدليــل أن‬\n      ‫ملفــه بالصحــة النفســية بالريــاض مفتــوح وقائــم منــذ خمســة عشــر ســنة‬\n      ‫ورقــم امللــف إضافــة إلــى أن علــى والــدي مطالبــة ماليــة قائمــة باحملكمــة‬\n      ‫مببلــغ أربعــة ماليــن ريــال ولــدي الدليــل فضيلــه القاضــي كيــف أن‬\n      ‫شــخص يســتلم حوالــي ســبعني مليــون ريــال منــذ ثالثــة ســنوات تقريبــا‬\n      ‫واآلن مفلــس مــع العلــم انــه لــم يدخــل ســوق األســهم إمنــا كانــت إقامتــه‬\n      ‫بــ(‪ ).....‬للنزهــة أليــس هــذا ســفها أطلــب مــن الشــرع حمايــة باقــي احلــال‬\n      ‫هكــذا أجــاب هــذا وبعرضــه علــى املدعــى عليــه أجــاب املدعــى عليــه‬\n      ‫وكالــة بــأن املدعــي قــد أقــام علــى والــده عشــرة قضايــا حقوقيــة حديثــة‬\n      ‫لــم يتســلم موكلــي تبليغــات احلضــور بهــا فكيــف يدعــي علــى والــده‬\n      ‫الســفه ويقيــم عليــه هــذه القضايــا هكــذا أجــاب وبعرضــه علــى املدعــي‬\n      ‫أجــاب بــأن مــا ذكــره املدعــى عليــه وكالــة غيــر دقيــق والصحيــح أننــي‬\n      ‫رفعــت علــى والــدي خمســة قضايــا حقوقيــة حديثــة وقضيــة سادســة‬\n      ‫جنائيــة تتضمــن طلــب كــف أذى وقــد رفضــت املدعــى عليــه وكالــة‬\n      ‫اســتالم التبليغــات وهــذا ال يتعــرض مــع دعــوى الســفهة هكــذا أجــاب‬\n      ‫هــذا وقــد جــرت الكتابــة منــي بتاريــخ ‪1433/6/7‬ه ـ ملجمــع (‪).......‬‬\n      ‫بالريــاض فوردتنــي اإلفــادة بخطــاب املديــر التنفيــذي ملجمــع (‪).......‬‬\n      ‫برقــم ‪ 44/22/5704/4441‬وتاريــخ ‪1433/7/5‬ه ـ واملتضمنــة عــرض‬\n      ‫املذكــور علــى اللجنــة الطبيــة يــوم األربعــاء ‪1433/6/25‬ه ـ وباالطــاع‬\n\n\n‫‪325‬‬\n\f‫علــى ملفــه لدينــا وأخــذ التاريــخ املرضــي مــن أحــد أقاربــه وإجــراء املقابلة‬\n‫النفســية وفحــص احلالــة العقليــة تبــن التالــي‪ :‬لــم يســبق لــه أنــه راجــع‬\n‫لدينــا مــن قبــل ال يوجــد تاريــخ ألي اضطرابــات نفســية ســابقة حســب‬\n‫ادعائــه ومبناظرتــه اليــوم وجــد أنــه هــاديء متعــاون مزاجــه معتــدل‬\n‫كالمــه مترابــط مــدرك للزمــان واملــكان واألشــخاص والوظائــف‬\n‫املعرفيــة ضمــن احلــدود الطبيعيــة حكمــه علــى األمــور جيــد ومســتبصر‬\n‫بحالتــه التوصيــات تــرى اللجنــة الطبيــة أن املذكــور ســليم مــن الناحيــة‬\n‫النفســية والعقليــة يف الوقــت الراهــن وعليــه فهــو ال يحتــاج إلــى ولــي‬\n‫يرعــى شــؤونه أخصائــي طــب نفســي د‪ .‬أ(‪ ).......‬ختــم وتوقيــع د‪).......( .‬‬\n‫أخصائــي طــب نفســي ختــم وتوقيــع رئيــس اللجنــة الطبيــة (‪ ).......‬توقيــع‬\n‫وبعــرض التقريــر علــى الطرفــن قــرر املدعــي عــدم القناعــة بــه وقــرر‬\n‫املدعــى عليــه القناعــة بــه فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة‬\n‫وبنــاء علــى التقريــر الطبــي املرصــود بعاليــه وفيــه أن املذكــور ســليم مــن‬\n‫الناحيــة النفســية والعقليــة يف الوقــت الراهــن وعليــه فهــو ال يحتــاج إلــى‬\n‫ولــي يرعــى شــؤونه لــذا فقــد أفهمــت املدعــي بعــدم اســتحقاقه ملــا يدعيــه‬\n‫وصرفــت النظــر عــن دعــواه وبإعــان احلكــم علــى الطرفــن فقــرر‬\n‫املدعــى عليــه القناعــة وقــرر املدعــي عــدم القناعــة فأفهمتــه باملراجعــة‬\n‫يف يــوم الســبت ‪1434/5/11‬ه ـ الســتالم نســخة احلكــم لتقــدمي الالئحــة‬\n‫االعتراضيــة خــال ثالثــن يومـ ًا مــن تاريخــه وإن لــم يتقــدم خــال املــدة‬\n‫املذكــورة فــإن حقــه يف االســتئناف يســقط ويكتســب احلكــم القطعية‬\n‫وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آله وصحبه وســلم‬\n                                                      ‫‪ .‬حــرر يف ‪1434/5/1‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ‪ ،‬فقــد اطلعنــا نحــن قضــاة الدائــرة السادســة‬\n\n\n                                                                                       ‫‪326‬‬\n\f      ‫لتمييــز القضايــا احلقوقيــة مبحكمــة االســتئناف بالريــاض علــى‬\n      ‫املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة العامــة بالريــاض برقــم‬\n      ‫وتاريــخ املرفــق بهــا الصــك الصــادر مــن فضيلــة القاضــي باحملكمــة‬\n      ‫الشــيخ (‪ ).......‬اخلــاص بدعــوى (‪ ).......‬ضــد (‪ ).......‬يف دعــوى احلجــز علــى‬\n      ‫األوليــاء واملفلســن علــى الصفــة املوضحــة بالصــك واملتضمــن حكــم‬\n      ‫فضيلتــه بــأن املدعــى عليــه ال يحتــاج إلــى ولــي يرعــى شــؤونه وعــدم‬\n      ‫اســتحقاق املدعــي ملــا يدعيــه وصــرف النظــر عــن دعــواه‪ ،‬وبدراســة‬\n      ‫الصــك وصــورة ضبطــه والالئحــة االعتراضيــة وأوراق املعاملــة قررنــا‬\n      ‫باألكثريــة املصادقــة علــى احلكــم‪ .‬والل ــه املوفــق وصلــى اهلل علــى نبينــا‬\n                                                       ‫محمـ ــد وآل ــه وصحب ــه وســلم ‪.‬‬\n\n\n\n\n‫‪327‬‬\n\f328\n\f329\n\f330\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"8772d0b1-3c0f-5928-9c22-98c49da1913e","source_page_start":319,"source_page_end":330,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"d7fe8c7df9566c9996923d7e87d4601544942415df98e6a47af80d06d0ce1efc","normalized_text_hash":"f69135793bc596ca7bad08f98d2fb3c4f6d7b9e6c0f513eda447042ffd5ada28","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v4-p319-34209994"},{"id":"b33c98aa-fb26-5736-adf9-f6376e4133d9","document_type":"judgment","category":"judicial","subcategory":"general","title":"عقد وكالة بعوض -اتفاق املدعي واملدعى عليه على شراء املدعى عليه سيارات مبواصفات معينة خال مدة محددة -دفع املدعي للمدعى عليه مبلغ مالي -عدم إيفاء املدعى عليه مبا مت االتفاق عليه -مصادقة املدعى عليه على الدعوى -حلف املدعي اليمن- إلزام املدعى عليه بدفع املبلغ املطالب به قول النبي صلى اهلل عليه وسلم ( :البينة على املدعي واليمن على من أنكر) أخرجه البيهقي .","document_number":"34221359","case_number":"3489887","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالطائف والقائم بعمل املكتب القضائي الثامن","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/5/25","year":"1434","subject":"عقد وكالة بعوض -اتفاق املدعي واملدعى عليه على شراء املدعى عليه سيارات مبواصفات معينة خال مدة محددة -دفع املدعي للمدعى عليه مبلغ مالي -عدم إيفاء املدعى عليه مبا مت االتفاق عليه -مصادقة املدعى عليه على الدعوى -حلف املدعي اليمن- إلزام املدعى عليه بدفع املبلغ املطالب به قول النبي صلى اهلل عليه وسلم ( :البينة على املدعي واليمن على من أنكر) أخرجه البيهقي .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/5/25 :‬هـ‬\n                       ‫ُ‬                 ‫َر ْق ُم َّ‬\n                           ‫الص ِّك‪34221359 :‬‬\n                           ‫َر ْق ُم الدعوى‪3489887 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                     ‫‪ 342919‬تاريخه‪1434/8/8:‬هـ‬\n\n\n      ‫عقــد وكالــة بعــوض‪ -‬اتفــاق املدعــي واملدعــى عليــه علــى شــراء املدعــى‬\n      ‫عليــه ســيارات مبواصفــات معينــة خــال مــدة محــددة‪ -‬دفــع املدعــي‬\n      ‫للمدعــى عليــه مبلــغ مالــي‪ -‬عــدم إيفــاء املدعــى عليــه مبــا مت االتفــاق‬\n      ‫عليــه‪ -‬مصادقــة املدعــى عليــه علــى الدعــوى‪ -‬حلــف املدعــي اليمــن‪-‬‬\n                                    ‫إلــزام املدعــى عليــه بدفــع املبلــغ املطالــب بــه‬\n\n\n\n\n      ‫قــول النبــي صلــى اهلل عليــه وســلم‪ ( :‬البينــة علــى املدعــي واليمــن علــى‬\n                                                     ‫مــن أنكــر) أخرجــه البيهقــي ‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي بأنــه اتفــق مــع املدعــى عليــه علــى أن يشــتري لــه ســيارة‬\n      ‫مبواصفــات مذكــورة يف دعــواه خــال مــدة محــددة وســلم لــه مبلغــا‬\n                                      ‫ماليــا مقابــل ذلــك إال أن املدعــى عليــه لــم يـ ِ‬\n      ‫ـف مبــا مت االتفــاق عليــه ولــم‬\n      ‫يقــم بشــراء الســيارة لــه‪ ،‬ولــذا طلــب إلزامــه بدفــع املبلــغ الــذي اســتلمه‬\n      ‫منــه حــاال‪ -‬أقــر املدعــى عليــه مبــا جــاء يف الدعــوى ودفــع بأنــه وســيط‬\n      ‫بــن املدعــي وبــن طــرف ثالــث إال أنــه عجــز عــن إثبــات ذلــك الدفــع‬\n      ‫وطلــب ميــن املدعــي علــى نفــي مــا دفــع بــه فأداهــا املدعــي طبــق مــا‬\n      ‫طلــب منــه‪ -‬املدعــى عليــه أقــر مبــا جــاء يف دعــوى املدعــي وعجــز عــن‬\n‫‪331‬‬\n\f‫إثبــات كونــه وســيط ًا واملدعــي حلــف اليمــن التــي طلبــت منــه‪ -‬قضــت‬\n‫احملكمــة بإلــزام املدعــى عليــه بــأن يســلم للمدعــي املبلــغ املدعــى بــه‬\n‫حــا ًال دون تأخيــر أو مماطلــة‪ -‬عــارض املدعــى عليــه علــى احلكــم‪-‬‬\n                     ‫قــررت محكمــة االســتئناف املوافقــة علــى احلكــم ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا القاضــي يف احملكمــة العامــة بالطائف‬\n‫والقائــم بعمــل املكتــب القضائــي الثامــن وبنــاء علــى املعاملــة احملالــة‬\n‫لنــا مــن فضيلــة رئيــس احملكمــة العامــة بالطائــف برقــم ‪3489887‬‬\n‫وتاريــخ ‪ 1434/02/24‬ه ـ املقيــدة باحملكمــة برقــم ‪ 34459611‬وتاريــخ‬\n‫‪ 1434/02/24‬ه ـ ففــي يــوم األحــد املوافــق‪ 1434/03/22‬ه ـ افتتحــت‬\n‫اجللســة الســاعة التاســعة صباحــا للنظــر يف الدعــوى املرفوعــة مــن ‪........‬‬\n‫ضد ‪ ........‬للمطالبة بتســليم مبيع وفيها حضر ســعودي اجلنســية مبوجب‬\n‫الســجل املدنــي رقــم ولــم يحضــر املدعــى عليــه وال مــن ميثلــه بوكالــة‬\n‫شــرعية ولــم يردنــا مــا يفيــد تبلغــه وبنــاء علــى املــادة الثالثــة واخلمســن‬\n‫مــن نظــام املرافعــات الشــرعية رفعــت اجللســة ثــم لــدي أنــا القاضــي يف‬\n‫احملكمــة العامــة بالطائــف ويف يــوم الســبت املوافــق‪ 1434/04/20‬ه ـ‬\n‫افتتحــت اجللســة الســاعة التاســعة صباحــا وفيهــا حضــر املدعــي ســعودي‬\n‫اجلنســية مبوجــب الســجل املدنــي رقــم وحضــر حلضــوره املدعــى عليــه‬\n‫ســعودي اجلنســية مبوجــب بطاقــة الهويــة الوطنيــة رقــم وأدعــى املدعــي‬\n‫قائــا يف حتريــر دعــواه أنــي دفعــت لهــذا احلاضــر معــي مبلــغ وقــدرة‬\n‫أربعــة وخمســون ألــف ريــال مقابــل أن يشــتري لــي ســيارة مــن نــوع ‪....‬‬\n‫موديــل ‪2010‬م بلــون ســمني والداخلــي بلــون هلــوز اســتعمال أمريكــي‬\n\n                                                                                       ‫‪332‬‬\n\f      ‫ـف مبا مت‬ ‫ببطاقــة جمركيــة خــال أربعــن يومــا إال أن املدعــى عليــه لــم يـ ِ‬\n      ‫االتفــاق عليــه ولــم يحضــر لــي شــيئ ًا حتــى تاريــخ أطلــب إلزامــه بدفــع هــذا‬\n      ‫املبلــغ لــي حــاال هــذه دعــواي وإنــي أســأله اجلــواب وبســؤال املدعــي عليــه‬\n      ‫عــن دعــوى املدعــي أجــاب قائــا ‪ :‬مــا ذكــره املدعــي مــن اســتالم املبلــغ‬\n      ‫وقــدرة أربعــة وخمســون ألــف فصحيــح وكنــت اتفقــت معــه علــى أن‬\n      ‫اســتلم منــه املبلــغ وأشــتري لــه ســيارة باملواصفــات املذكــورة يف دعــواه‬\n      ‫ويســتلم الســيارة مــن شــخص يدعــى هــذ إجابتــي ولضيــق وقــت اجللســة‬\n      ‫ودخــول وقــت اجللســة التــي تليهــا جــرى رفــع اجللســة ويف يــوم الســبت‬\n      ‫‪ 1434/05/25‬ه ـ افتتحــت اجللســة الســاعة التاســعة والنصــف صباحــا‬\n      ‫وفيهــا حضــر املدعــي ســعودي اجلنســية مبوجــب بطاقــة الهويــة الوطنيــة‬\n      ‫رقــم وحضــر حلضــوره املدعــى عليــه ‪ .....‬ســعودي اجلنســية مبوجــب بطاقــة‬\n      ‫الهويــة الوطنيــة رقــم ‪ .....‬وبســؤال املدعــى عليــه عــن االتفــاق الــذي بينــه‬\n      ‫وبــن املدعــي أجــاب قائ ـاً‪ :‬إمنــا أنــا مجــرد وكيــل للمدعــي يف إيصــال‬\n      ‫املبلــغ وتســليم املدعــي كمبيالــة باملبلــغ‪ ،‬هــذه إجابتــي ‪ ،‬وبســؤال‬\n      ‫املدعــى عليــه هــل لديــك بينــة؟ أجــاب قائ ـاً‪ :‬ليــس لــدي بينــة وأطلــب‬\n      ‫ميــن املدعــي هكــذا أجــاب ‪ ،‬وبعرضــه علــى املدعــي اســتعد باحللــف‬\n      ‫ا ‪ :‬واهلل الــذي ال إلــه إال هــو الــذي يعلــم الســر والعالنيــة‬  ‫وحلــف قائ ـ ً‬\n      ‫ويعلــم الغيــب والشــهادة إننــي اتفقــت مــع هــذا احلاضــر معــي علــى أن‬\n      ‫يحضــر لــي ســيارة مــن نــوع ‪ 2010 ....‬لونهــا ســمني وداخلهــا هلــوز خــال‬\n      ‫مــدة أربعــن وليــس وكيــا لــي يف إيصــال املبلــغ ولــم أتفــق معــه علــى أن‬\n      ‫يكــون االســتالم عنــد ‪ .......‬وال أعرفــه إال بعــد حصــول هــذه املشــكلة‬\n      ‫ولــم أســتلم منــه الســيارة ولــم أكشــف عليهــا واهلل واهلل واهلل هكــذا‬\n      ‫حلــف ‪ ،‬فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة املتضمنــة مصادقــة‬\n\n\n‫‪333‬‬\n\f‫املدعــى عليــه لدعــوى املدعــي وعجــزه عــن إثبــات كونــه وســيط ًا ومبا أن‬\n‫املدعــي حلــف اليمــن التــي طلبــت منــه ‪ ،‬وملــا جــاء عــن النبــي صلــى اهلل‬\n‫عليــه وســلم ‪ ( :‬البينــة علــى املدعــي واليمــن علــى مــن أنكــر) أخرجــه‬\n‫البيهقــي (‪ )252/10‬عــن ابــن عبــاس ‪-‬رضــي اهلل عنــه‪ -‬وحســنه احلافــظ‬\n‫يف الفتــح (‪ ،)283/5‬لذلــك كلــه فقــد ثبــت لــدي أن بذمــة املدعــى عليــه‬\n‫مبلــغ قــدره أربعــة وخمســون ألــف ريــال يدفعهــا للمدعــي ‪ ............‬حــا ًال‬\n‫دون تأخيــر أو مماطلــة هــذا مــا ظهــر لــي وبــه حكمــت وبعرضــه علــى‬\n‫املدعــى عليــه قــرر اعتراضــه علــى احلكــم وطلــب االســتئناف بالئحــة‬\n‫اعتراضيــة ويف نفــس اجللســة جــرى تســليم املدعــى عليــه نســخة احلكــم‬\n‫وأفهــم بــأن لــه مــدة ثالثــن يــوم لتقــدمي اعتراضــه علــى احلكــم تبــدأ مــن‬\n‫تاريــخ اليــوم وإذا لــم يقــدم اعتراضه خاللها فيســقط حقه يف االعتراض‬\n‫ويكتســب احلكــم القطعيــة ففهــم ذلــك ‪ ،‬وكان رفــع اجللســة الســاعة‬\n‫العاشــرة صباحــا وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد‬\n                       ‫وعلــى آلــه وصحبــه أجمعــن‪ ،‬حــرر يف ‪1434/5/25‬هــ‪.‬‬\n‫احلمــد هلل وحــده‪ ،‬والصــاة والســام علــى مــن ال نبــي بعــده‪ ،‬وبعــد ‪:‬‬\n‫ثــم عــادت املعاملــة مــن محكمــة االســتئناف مبكــة املكرمــة مصادقـ ًا‬\n‫عليهــا بالقــرار رقــم ‪ 34291917‬يف ‪1434/8/8‬ه ـ ونصــه احلمــد هلل‬\n‫والصــاة والســام علــى رســول اهلل وبعــد فقــد جــرى اطالعنــا نحــن‬\n‫رئيــس وعضــوي الدائــرة احلقوقيــة الرابعــة يف محكمــة االســتئناف‬\n‫مبنطقــة مكــة املكرمــة االطــاع علــى الصــك الصــادر مــن فضيلــة‬\n‫الشــيخ ‪ /‬القاضــي باحملكمــة العامــة بالطائف واملســجل بعــدد املتضمن‬\n‫دعــوى ضــد‪ /‬احملكــوم فيــه مبــا دون باطنــه ‪ ،‬وبدراســة الصــك وصــورة‬\n‫ضبطــه والئحتــه االعتراضيــة تقــررت املوافقــة علــي احلكــم وبــاهلل‬\n\n\n                                                                                      ‫‪334‬‬\n\f      ‫التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم قاضــي‬\n      ‫اســتئناف ختــم وتوقيــع‪ .‬قاضــي اســتئناف موقــع يف األصــل وموافــق علــى‬\n      ‫احلكــم ومنتــدب‪ .‬رئيــس الدائــرة ختــم وتوقيــع‪ .‬وصلــى اهلل وســلم علــى‬\n                                        ‫نبينــا محمــد ‪.‬حــرر يف ‪1434/8/25‬هــ‪.‬‬\n\n\n\n\n‫‪335‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"8772d0b1-3c0f-5928-9c22-98c49da1913e","source_page_start":331,"source_page_end":335,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"c13afab8d7f3b8cd84e20dbd6754fbf1dfb7cbf61ec2811d018d247639fff444","normalized_text_hash":"ffe8e147da425234329387791f2fb689a318fab0d5b31d3cf6efe996e12cc896","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v4-p331-34221359"},{"id":"bac9ee3f-c417-599e-bb80-d56f2a060a04","document_type":"judgment","category":"judicial","subcategory":"general","title":"عقد وكالة بعوض -اتفاق املدعي مع املدعى عليه على شراء املدعى عليه سيارات محددة الوصف خال مدة محددة -الرجوع وسداد الثمن حال عدم التسليم يف املوعد -عدم إيفاء املدعى عليه مبا مت االتفاق عليه -املطالبة باملبلغ املدفوع -تقدمي املدعي بينة- شهادة شاهد عدل -حلف اليمن -عدم حضور املدعى عليه دون عذر -إلزام املدعى عليه غيابي ا بدفع املبلغ املدعى به -املدعى عليه على حجته متى حضر .","document_number":"34227273","case_number":"3499675","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالطائف ف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/5/29","year":"1434","subject":"عقد وكالة بعوض -اتفاق املدعي مع املدعى عليه على شراء املدعى عليه سيارات محددة الوصف خال مدة محددة -الرجوع وسداد الثمن حال عدم التسليم يف املوعد -عدم إيفاء املدعى عليه مبا مت االتفاق عليه -املطالبة باملبلغ املدفوع -تقدمي املدعي بينة- شهادة شاهد عدل -حلف اليمن -عدم حضور املدعى عليه دون عذر -إلزام املدعى عليه غيابي ا بدفع املبلغ املدعى به -املدعى عليه على حجته متى حضر .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/5/29 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪34227273 :‬‬\n                    ‫َر ْق ُم الدعوى‪3499675 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34274574‬تاريخه‪1434/7/22:‬هـ‬\n\n\n‫عقــد وكالــة بعــوض‪ -‬اتفــاق املدعــي مــع املدعــى عليــه علــى شــراء‬\n‫املدعــى عليــه ســيارات محــددة الوصــف خــال مــدة محــددة‪ -‬الرجــوع‬\n‫وســداد الثمــن حــال عــدم التســليم يف املوعــد‪ -‬عــدم إيفــاء املدعــى عليــه‬\n‫مبــا مت االتفــاق عليــه‪ -‬املطالبــة باملبلــغ املدفــوع‪ -‬تقــدمي املدعــي بينــة‪-‬‬\n‫شــهادة شــاهد عــدل‪ -‬حلــف اليمــن‪ -‬عــدم حضــور املدعــى عليــه دون‬\n‫عــذر‪ -‬إلــزام املدعــى عليــه غيابيـ ًا بدفــع املبلــغ املدعــى بــه‪ -‬املدعــى عليــه‬\n                                                       ‫علــى حجتــه متــى حضــر ‪.‬‬\n\n\n\n\n‫‪ -1‬حديــث ابــن عبــاس رضــي اهلل عنهمــا‪( :‬أن النبــي صلــى اهلل عليــه‬\n                         ‫وســلم قضــى بشــاهد وميــن )‪ .‬أخرجــه مســلم‬\n‫‪ -2‬ذكــر ابــن قدامــة يف الــكايف (‪ )128/6‬مــا نصــه‪« :‬فــإن امتنــع اخلصــم‬\n                      ‫مــن احلضــور عنــد احلاكــم حكــم عليه‪..‬إلخ»‪.‬أ‪.‬هـ‪.‬‬\n‫‪ -3‬ذكــر أبــو إســحاق إبراهيــم بــن حســن يف معــن احلــكام مــا نصــه‪:‬‬\n‫«مســألة قــال املــاوردي يف تفســير قولــه تعالــى (وإذا دعــوا إلــى اهلل‬\n                            ‫ورســوله ليحكــم بينهــم‪ ..‬اآليــة) ‪..‬إلخ»‪.‬أ‪.‬ه ـ‬\n       ‫‪ -4‬املادة (‪ )55‬من نظام املرافعات الشرعية ولوائحها التنفيذية‪.‬‬\n\n\n\n\n                                                                                          ‫‪336‬‬\n\f      ‫ادعــى املدعــي بأنــه اتفــق مــع املدعــى عليــه علــى أن يشــتري لــه ســيارات‬\n      ‫مبواصفات مذكورة يف دعواه خالل مدة محددة وأنه إذا لم يحضرها‬\n      ‫خــال تلــك املــدة فيحــق للمدعــي الرجــوع واســتعادة الثمــن‪ ،‬وقــد ســلم‬\n      ‫ـف مبــا مت االتفــاق‬ ‫لــه مبلغــا ماليــا مقابــل ذلــك إال أن املدعــى عليــه لــم يـ ِ‬\n      ‫عليــه ولــم يقــم بشــراء الســيارات حتــى انقضــت املــدة املتفــق عليهــا‪ ،‬ولــذا‬\n      ‫طلــب إلزامــه بإعــادة املبلــغ الــذي اســتلمه منــه حــاال‪ -‬املدعــى عليــه لــم‬\n      ‫يحضــر مــع تبلغــه لغيــر شــخصه لــذا فقــد قــررت احملكمــة مواصلــة‬\n      ‫الســير يف الدعــوى غيابيــا وطلبــت مــن املدعــي البينــة علــى دعــواه‬\n      ‫فأبــرز كمبيالــة مــن املدعــى عليــه لصاحلــه تتضمــن التزامــه لــه باملبلــغ‬\n      ‫املدعــى بــه كمــا أحضــر شــاهدا واحــد ًا فشــهد بصحــة دعــوى املدعــي‬\n      ‫وجــرى تعديلــه شــرعاً‪ -‬قــررت احملكمــة توجيــه اليمــن إلــى املدعــى‬\n      ‫ا لبينتــه فأداهــا طبــق مــا طلــب‬    ‫عليــه اســتظهار ًا حلــال الغائــب وتكمي ـ ً‬\n      ‫منــه‪ -‬قضــت احملكمــة غيابيـ ًا بإلــزام املدعــى عليــه بــأن يســلم للمدعــي‬\n      ‫املبلــغ املدعــى بــه حــا ًال وهــو علــى حجتــه إذا حضــر‪ -‬تعــذر تبليــغ املدعــى‬\n      ‫عليــه باحلكــم فقــررت احملكمــة رفعــه حملكمــة االســتئناف لتدقيقــه‪-‬‬\n                              ‫قــررت محكمــة االســتئناف املوافقــة علــى احلكــم ‪.‬‬\n\n\n\n\n‫‪337‬‬\n\f‫احلمــد هلل وحــده‪ ،‬والصــاة والســام علــى مــن ال نبــي بعــده‪ ،‬وبعــد ‪:‬‬\n‫ـدي أنــا ‪ ..........‬القاضــي يف احملكمــة العامــة بالطائــف ففــي يــوم‬\n                                                                      ‫فلـ َّ‬\n‫األربعــاء ‪1434/4/25‬ه ـ افتتحــت اجللســة الســاعة التاســعة صباح ـ ًا‬\n‫لســماع دعــوى ضــد وفيهــا حضــر ‪ ....‬ســعودي اجلنســية بالســجل املدنــي‬\n‫الوكيــل الشــرعي عــن بالوكالة رقــم ‪ 33463624‬يف ‪1433/12/21‬هـ‬\n‫الصــادرة مــن كتابــة عــدل الطائــف الثانيــة والتــي تخولــه املطالبــة‬\n‫وإقامــة الدعــاوي واملرافعــة واملدافعــة وســماع الدعــاوي والــرد عليهــا‬\n‫واإلقــرار واإلنــكار والصلــح والتنــازل و إحضــار الشــهود والبينــات‬\n‫والطعــن فيهــا واإلجابــة واجلــرح والتعديــل والطعــن بالتزويــر ونفيهــا‬\n‫واالعتــراض علــى األحــكام وطلــب االســتئناف وإنهــاء مــا يلــزم حضــور‬\n‫اجللســات يف جميــع الدعــاوى لــدى جميــع احملاكــم واســتالم املبالــغ‬\n‫واســتالم صكــوك األحــكام و االســتالم والتســليم ومراجعــة جميــع‬\n‫اجلهــات ذات العالقــة وإنهــاء جميــع اإلجــراءات الالزمــة والتوقيــع فيمــا‬\n‫يتطلــب ذلــك‪ ،‬ولــم يحضــر املدعــى عليــه وال مــن ميثلــه بوكالــة شــرعية‬\n‫(( وقــد وردنــا مــن قســم شــرطة الســامة خطابهــم رقــم ‪/1308‬ع يف‬\n‫‪1434/3/15‬ه ـ املتضمــن مت البحــث عــن املذكــور باملنــزل ولــم يعثــر‬\n‫عليــه ومت تســليم الطلــب وموعــد اجللســة لذويــه باملنــزل وذلــك حســبما‬\n‫تضمــن طيــه مــن إقــرار منــدوب العمــدة )) واســتناد ًا للمــادة اخلامســة‬\n‫واخلمســن مــن نظــام املرافعــات الشــرعية رفعــت اجللســة ويف يــوم الســبت‬\n‫املوافــق ‪ 1434/04/20‬ه ـ افتتحــت اجللســة الســاعة وفيهــا حضــر‬\n‫املدعــي وكالــة ســعودي اجلنســية مبوجــب بطاقــة الهويــة الوطنيــة رقــم‬\n‫ولــم يحضــر املدعــى عليــه وال مــن ينــوب عنــه ولــم يردنــا مــا يفيــد تبلغــه‬\n                                                                                       ‫‪338‬‬\n\f      ‫باجللســة مــن عدمــه واســتنادا علــى املــادة اخلامســة واخلمســن مــن نظــام‬\n      ‫املرافعــات الشــرعية جــرى رفــع اجللســة ويف يــوم األربعــاء ‪1434/5/29‬هـ‬\n      ‫الســاعة التاســعة صباحـ ًا افتتحــت اجللســة وفيهــا حضــر املدعــي ســعودي‬\n      ‫اجلنســية مبوجــب بطاقــة الهويــة الوطنيــة رقــم ولــم يحضــر املدعــى عليــه‬\n      ‫رغــم تبلــغ ذويــه يف موعــد جلســة ســابقة حســب خطــاب مديــر مركــز‬\n      ‫شــرطة الســامة رقــم ‪/1308‬ع يف ‪1434/3/15‬ه ـ ورفــض شــقيقه‬\n      ‫اســتالم التبليــغ جللســة اليــوم حســب خطــاب مديــر مركــز شــرطة‬\n      ‫ا يف‬ ‫الســامة رقــم ‪/2159‬ع يف ‪1434/4/30‬ه ـ فادعــى املدعــي قائ ـ ً‬\n      ‫حتريــر دعــواه ‪ :‬إننــي ســلمت الغائــب املجلــس احلكــم الشــرعي‪ /‬مبلــغ‬\n      ‫وقــدره مائــة وواحــد وســبعون ألــف ريــال مقابــل أن يحضــر لــي ثــاث‬\n      ‫ســيارات مــن نــوع ‪ ....‬موديــل ‪2010‬م اســتعمال أمريكــي لونهــا ســمني‬\n      ‫يســلمني إياهــا بتاريــخ ‪1433/5/20‬ه ـ كمــا اتفقــت معــه علــى أنــه إذا‬\n      ‫لــم يحضرهــا باملوعــد احملــدد فيحــق لــي الرجــوع وإعــادة الثمــن لــي وقــد‬\n      ‫مضــت املــدة احملــدد ولــم يســلمني املدعــى عليــه أي شــيء لــذا أطلــب‬\n      ‫إلــزام املدعــى عليــه بإعــادة الثمــن لــي وقــدره مائــة وواحــد وســبعون ألــف‬\n      ‫ريــال لــي حــاالً‪ ،‬هــذه دعــواي هكــذا ادعــى املدعــي وبطلــب البينــة‬\n      ‫مــن املدعــي أبــرز لنــا كمبيالــة برقــم ‪ 41665‬بتاريــخ ‪1433/5/20‬ه ـ‬\n      ‫باســم املديــن مبلــغ الكمبيالــة مائــة وواحــد وســبعون ألــف ريــال ال غيــر‬\n      ‫كمــا أحضــر للشــهادة وأدائهــا ســعودي اجلنســية مبوجــب بطاقــة الهويــة‬\n      ‫الوطنيــة رقــم معلــم بــإدارة التربيــة والتعليــم مبحافظــة مهــد الذهــب ال‬\n      ‫ا ‪:‬أشــهد هلل تعالــى إنــه تقريبـ ًا يف‬\n                                             ‫تربطــه باملدعــي أي قرابــة وشــهد قائـ ً‬\n      ‫شــهر صفــر مــن عــام ‪1433‬ه حضــرت اجتمــاع بــن املدعــي مــع املدعــى‬\n      ‫عليــه ودفــع املدعــي للمدعــى عليــه مبلــغ قــدره مائــة وواحــد وســبعون‬\n\n\n‫‪339‬‬\n\f‫ألــف ريــال عوض ـ ًا عــن ثالثــة ســيارات فــورد ماركيــز م ‪ /2010‬بلــون‬\n‫ســمني واتفقــا علــى أن يحضــر املدعــى عليــه الســيارات للمدعي يف نهاية‬\n‫‪1433/5/20‬ه ـ وإذا لــم يحضرهــا فيحــق املطالبــة بثمــن الــذي دفعــه‬\n‫وحــرر كمبيالــة بهــذا املبلــغ وكتبهــا املدعــى عليــه بيــده هكــذا شــهد‬\n‫‪ ،‬ثــم طلبــت مــن املدعــي مزكــن لشــاهده فأحضــر للتزكيــة وأدائهــا‬\n‫ال مــن ســعودي اجلنســية بالهويــة الوطنيــة رقــم ســعودي اجلنســية‬           ‫ك ً‬\n‫مبوجــب الهويــة الوطنيــة رقــم وشــهد كل واحــد منهمــا بعدالــة الشــاهد‬\n‫وأنــه يقبــل شــهادته لــه وعليــه ثــم طلبــت مــن املدعــي اليمــن علــى صحــة‬\n‫ا ‪ /‬واهلل العظيــم الــذي ال إلــه إال هــو‬ ‫دعــواه فاســتعد بهــا وحلــف قائ ـ ً‬\n‫الــذي يعلــم اجلهــر ومــا يخفــى ويعلــم خائنــة األعــن ومــا تخفــي الصــدور‬\n‫إن املدعــى عليــه أخــذ منــي مبلــغ وقــدرة مائــة وواحــد وســبعون ألــف ريــال‬\n‫ثمنـ ًا لثــاث ســيارات مــن نــوع فــورد موديــل ‪2010‬م لــون ســمني اســتعمال‬\n‫أمريكــي يســلمها لــي يف موعــد أقصــاه ‪1433/5/20‬ه ـ واتفقــت معــه‬\n‫علــى أنــه يف حــال عــدم إحضارهــا يف املوعــد احملــدد فــإن لــي الرجــوع‬\n‫وإعــادة الثمــن لــي وقــد مضــت املــدة احملــددة ولــم يحضــر لــي الســيارات‬\n‫حتــى اآلن ولــم يعــد لــي املبلــغ ولــم أبرئــه منهــا أي شــيء واهلل واهلل واهلل‪.‬‬\n‫هكــذا حلــف فبنــاء علــى مــا تقــدم مــن الدعــوى والبينــة املعدلــة ومبــا‬\n‫أن املدعــي حلــف اليمــن التــي طلبــت منــه وملــا جــاء عــن ابــن عبــاس‬\n‫رضــي اهلل عنــه ‪( :‬أن النبــي صلــى اهلل عليــه وســلم قضــى بشــاهد وميــن‬\n‫) أخرجــه مســلم يف صحيحــه برقــم ‪ )1712( :‬ص‪ ،)711( :‬واســتنادا‬\n‫علــى املــادة اخلامســة واخلمســن مــن نظــام املرافعــات الشــرعية ولوائحهــا‬\n‫التنفيذيــة ومبــا أن املدعــى عليــه لــم يحضــر ولــم يقــدم عــذرا عــن ســبب‬\n‫عــدم احلضــور ولــم يقــدم دفاعــه علــى هــذه الدعــوى مــع أنــه تبلــغ لغيــر‬\n\n\n                                                                                        ‫‪340‬‬\n\f      ‫شــخصه يف جلســة ماضيــة ورفــض شــقيقه اســتالم التبليــغ جللســة هــذا‬\n      ‫اليــوم بهــا حســب التعليمــات ‪ ،‬وقــد ذكــر ابــن قدامــه رحمــه اهلل تعالــى‬\n      ‫يف كتابــه الــكايف ‪ 128/6‬مــا نصــه‪« :‬فــإن امتنــع اخلصــم مــن احلضــور‬\n      ‫عنــد احلاكــم حكــم عليــه ألنــه لولــم يحكــم عليــه جلعــل االمتنــاع‬\n      ‫واالســتتار طريقــا لتضييــع احلقوق»‪.‬أ‪.‬ه ـ وقــد ذكــر أبــو إســحاق إبراهيــم‬\n      ‫بــن حســن يف كتابــه معــن احلــكام علــى القضايــا واألحــكام مــا‬\n      ‫نصــه‪« :‬مســالة قــال املــاوردي يف تفســير قولــه تعالــى (وإذا دعــوا إلــى اهلل‬\n      ‫ورســوله ليحكــم بينهــم )اآليــة دليــل علــى أنــه مــن دعــي إلــى حاكــم مــن‬\n      ‫حــكام املســلمني فعليــه اإلجابــة ويحــرج إن تأخــر وقــد ورد عــن احلســن‬\n      ‫بــن علــي رضــي اهلل عنهمــا أن النبــي صلــى اهلل عليــه قــال (مــن دعــي‬\n      ‫إلــى حاكــم مــن حــكام املســلمني ولــم يجــب فهــو ظالــم ال حــق لــه «‪.‬أ‪.‬ه ـ‬\n      ‫لذلــك كلــه فقــد حكمــت بإلــزام املدعــى عليــه الغائــب عــن مجلــس‬\n      ‫احلكــم الشــرعي أن يدفــع للمدعــي مبلــغ مائــة وواحــد وســبعون ألــف‬\n      ‫ريــال حــاال هــذا مــا ظهــر لــي وبــه حكمــت ‪ ،‬واملدعــى عليــه علــى حجتــه‬\n      ‫متــى حضــر‪ ،‬وقــررت بعــث نســخة مــن صــك احلكــم للمدعــى عليــه‬\n      ‫ليقــدم اعتراضــه خــال ثالثــن يومــا مــن تاريــخ التبليــغ باحلكــم وإذا‬\n      ‫لــم يقــدم اعتراضــه خاللهــا فيســقط حقــه يف االعتــراض ويكتســب‬\n      ‫احلكــم القطعيــة‪ ،‬وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد‬\n                         ‫وعلــى آلــه وصحبــه أجمعــن‪ ،‬حــرر يف ‪1434/5/29‬هــ‪.‬‬\n      ‫ويف يــوم الســبت ‪ 1434/06/17‬ه ـ افتتحــت اجللســة الســاعة الثامنــة‬\n      ‫والنصــف صباحــا وفيهــا وردتنــا تبليــغ صــورة احلكــم مــن رئيــس قســم‬\n      ‫محضــري اخلصــوم باحملكمــة برقــم ‪ 341318618‬املتضمــن (حيــث‬\n      ‫أن املدعــى عليــه املذكــور مطلــوب يف عــدة قضايــا ومت الذهــاب إلــى‬\n\n\n‫‪341‬‬\n\f‫العنــوان املــدون أعــاه ولعــدة مــرات ولكنــه غيــر متواجــد حتــى عنــد‬\n‫تبليغــه باحلضــور للجلســات غيــر متواجــد ممــا تعــذر علينــا تســليمه اســم‬\n‫احملضــر توقيعــه) أ‪ .‬ه ـ لــذا قــررت رفعهــا حملكمــة االســتئناف لتدقيــق‬\n‫احلكــم وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                  ‫وصحبــه وســلم ‪ .‬حــرر يف ‪1434/6/17‬هــ‪.‬‬\n‫احلمــد هلل وحــده‪ ،‬والصــاة والســام علــى مــن ال نبــي بعــده‪ ،‬وبعــد ‪:‬‬\n‫ثــم عــادت املعاملــة مــن محكمــة االســتئناف مبكــة املكرمــة مصادقـ ًا‬\n‫عليهــا بالقــرار رقــم ‪ 34274574‬يف ‪1434/7/22‬ه ـ ونصــه احلمــد هلل‬\n‫والصــاة والســام علــى رســول اهلل وبعــد فقــد جــرى اطالعنــا نحــن‬\n‫رئيــس وعضــوي الدائــرة احلقوقيــة الرابعــة محكمــة االســتئناف‬\n‫مبنطقــة مكــة املكرمــة علــى الصــك الصــادر مــن فضيلــة الشــيخ ‪/‬‬\n‫القاضــي باحملكمــة العامــة بالطائــف واملســجل بعــدد ‪34227273‬‬\n‫وتاريــخ ‪1434/5/29‬ه ـ املتضمــن دعــوى ضــد‪ /‬واحملكــوم فيــه مبــا‬\n‫دون باطنــة وبدراســة الصــك وصــورة ضبطــه تقــررت املوافقــة علــي‬\n‫احلكــم وعلــى فضيلتــه مراعــاة التنبيــه املرفــق باملعاملــة وصلــى اهلل علــى‬\n‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم قاضــي اســتئناف ختــم وتوقيــع‪.‬‬\n‫قاضــي اســتئناف ختــم وتوقيــع‪ .‬رئيــس الدائــرة ختــم وتوقيــع‪ .‬وصلــى اهلل‬\n                       ‫وســلم علــى نبينــا محمــد ‪.‬حــرر يف ‪1434/8/6‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده‪ ،‬وبعــد لــدي أنــا القاضــي باحملكمــة العامــة بالطائــف‬\n‫والقائــم بعمــل املكتــب الثامــن ففــي يــوم اخلميــس ‪1435/1/11‬ه ـ‬\n‫افتتحت اجللســة الســاعة العاشــرة والنصف صباح ًا بناء على االســتدعاء‬\n‫املقــدم مــن املدعــو‪ ............ /‬واملقيــد باحملكمــة برقــم ‪342825300‬‬\n‫يف ‪1434/12/19‬ه ـ واملتضمــن رغبتــه يف التهميــش علــى الصــك رقــم‬\n\n\n                                                                                    ‫‪342‬‬\n\f      ‫ال‬\n      ‫‪ 34227273‬يف ‪1434/5/29‬هـ باســتالمه املبلغ املدون بالصك كام ً‬\n      ‫وحضــر فيهــا املدعــي وكالــة ســعودي اجلنســية مبوجــب بطاقــة الهويــة‬\n      ‫الوطنيــة رقــم بصفتــه وكيــل عــن املدعــي ســعودي مبوجــب ســجل مدنــي‬\n      ‫رقــم مبوجــب الوكالــة الصــادرة مــن كتابــة عــدل الطائــف الثانيــة برقــم‬\n      ‫‪ 33463624‬يف ‪1433/12/21‬ه ـ املتضمنــة املطالبــة وإقامــة الدعــاوي‬\n      ‫واملرافعــة واملدافعــة و اإلقــرار واالســتالم والتســليم ‪ ،‬وقــرر أنــه اســتلم‬\n      ‫كامــل املبلــغ احملكــوم بــه ضــد املدعــى عليــه بخصــوص هــذا الصــك‬\n      ‫‪ ،‬وأنــه بعــد اســتالم املبلــغ ال يطالــب املدعــى عليــه وال غيــره بشــيء‬\n      ‫بخصــوص هــذه الدعــوى‪ ،‬وبهــذا انتهــت هــذه الدعــوى‪ ،‬وبــاهلل التوفيق‪،‬‬\n                       ‫وصلــى اهلل علــى نبينــا محمــد‪ .‬حــرر يف ‪1435/1/11‬ه ـ ‪.‬‬\n\n\n\n\n‫‪343‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"8772d0b1-3c0f-5928-9c22-98c49da1913e","source_page_start":336,"source_page_end":343,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"15cd393efb027412e92b043e1b171f4287ee4d3eb9867bf6de07a60a6dbc0506","normalized_text_hash":"379c94fec16ec2d69a48ebe0d7e68119a95d779d3d567c2890d409f452994a6b","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v4-p336-34227273"},{"id":"575fa9a7-1faf-52d9-a8cc-d55de96ed2ca","document_type":"judgment","category":"judicial","subcategory":"general","title":"عقد وكالة بغير عوض -دفع املدعي للمدعى عليه مبلغ مالي مقابل استخراج تأشيرة سفر -التأشيرة مزورة -املطالبة باملبلغ- حلف املدعى عليه اليمن بتسليم مبلغ استخراج التأشيرة ملكتب خدمات عامة -ثبوت الغش والتزوير على مكتب اخلدمات -الوكيل يده يد أمانة وال ضمان عليه إال إذا تعدى أو فرط -رد الدعوى وإخاء سبيل املدعى عليه منها .","document_number":"34234533","case_number":"34183370","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة باملويه","circuit":"الدائرة احلقوقية الثالثة رقم 34278741","issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/6/7","year":"1434","subject":"عقد وكالة بغير عوض -دفع املدعي للمدعى عليه مبلغ مالي مقابل استخراج تأشيرة سفر -التأشيرة مزورة -املطالبة باملبلغ- حلف املدعى عليه اليمن بتسليم مبلغ استخراج التأشيرة ملكتب خدمات عامة -ثبوت الغش والتزوير على مكتب اخلدمات -الوكيل يده يد أمانة وال ضمان عليه إال إذا تعدى أو فرط -رد الدعوى وإخاء سبيل املدعى عليه منها .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫تاريخه‪1434/6/7 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪34234533 :‬‬\n                   ‫َر ْق ُم الدعوى‪34183370 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n            ‫‪ 34311444‬تاريخه‪1434/9/2:‬هـ‬\n\n\n‫عقــد وكالــة بغيــر عــوض‪ -‬دفــع املدعــي للمدعــى عليــه مبلــغ مالــي‬\n‫مقابــل اســتخراج تأشــيرة ســفر‪ -‬التأشــيرة مــزورة‪ -‬املطالبــة باملبلــغ‪-‬‬\n‫حلــف املدعــى عليــه اليمــن بتســليم مبلــغ اســتخراج التأشــيرة ملكتــب‬\n‫خدمــات عامــة‪ -‬ثبــوت الغــش والتزويــر على مكتب اخلدمــات‪ -‬الوكيل‬\n‫يــده يــد أمانــة وال ضمــان عليــه إال إذا تعــدى أو فــرط‪ -‬رد الدعــوى‬\n                                       ‫وإخــاء ســبيل املدعــى عليــه منهــا ‪.‬‬\n\n\n\n\n‫‪ -1‬الوكيــل يــده يــد أمانــة باتفــاق الفقهــاء وال ضمــان عليــه إال إذا‬\n‫تعــدى أو فــرط ويــد األمانــة يترتــب عليهــا أن يكــون القــول قــول األمــن‬\n‫مــع ميينــه يف دفــع الضمــان عــن نفســه‪ .‬انظــر املوســوعة الفقهيــة‬\n                                                         ‫الكويتيــة (‪.)86/45‬‬\n‫‪ -2‬املــواد (‪ )176‬و(‪ )178‬مــن نظــام املرافعــات الشــرعية ولوائحــه‬\n                                                                 ‫ا لتنفيذ يــة ‪.‬‬\n\n\n\n\n‫ادعــى املدعــي بأنــه ســلم املدعــى عليــه مبلغــا مالي ـ ًا وطلــب منــه أن‬\n‫يســتخرج تأشــيرة لزوجــة أخيــه بعــد أن علــم بأنــه ســيذهب الســتخراج‬\n‫تأشــيرة لزوجتــه عــن طريــق أحــد مكاتــب اخلدمــات العامــة ثــم بعــد أن‬\n\n                                                                                   ‫‪344‬‬\n\f      ‫مت اســتخراج التأشــيرة تبــن أنهــا مــزورة‪ ،‬ولــذا فقــد طلــب إلــزام املدعــى‬\n      ‫عليــه بإعــادة ذلــك املبلــغ الــذي ســلمه لــه‪ -‬أقــر املدعــي باســتالم املبلــغ‬\n      ‫املذكــور ودفــع بأنــه ســلمه إلــى مكتــب اخلدمــات املذكــور كمــا طلب‬\n      ‫منــه املدعــي إال أن املكتــب قــام بخداعهمــا وأصــدر لهمــا تأشــيرات‬\n      ‫مــزورة وقــد قــدم ضــده شــكوى لــدى اجلهــات املختصــة ولذلــك فهــو غيــر‬\n      ‫مســتعد بإعــادة املبلــغ‪ -‬قــررت احملكمــة توجيــه اليمــن إلــى املدعــى‬\n      ‫عليــه علــى صحــة مــا دفــع بــه فأداهــا طبــق مــا طلــب منــه‪ -‬الوكيــل يــده‬\n      ‫يــد أمانــة وال ضمــان عليــه إال إذا تعــدى أو فــرط فيقبــل قولــه مــع ميينــه يف‬\n      ‫دفــع الضمــان عــن نفســه‪ -‬قضــت احملكمــة بــرد دعــوى املدعــي وأخلــت‬\n      ‫ســبيل املدعــى عليــه منهــا‪ -‬قنــع املدعــى عليــه باحلكــم وعــارض عليــه‬\n                 ‫املدعــي‪ -‬قــررت محكمــة االســتئناف املوافقــة علــى احلكــم ‪.‬‬\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ........‬رئيــس احملكمــة العامــة باملويــه‬\n      ‫وبنــاء علــى املعاملــة الــواردة لنــا مــن قســم اإلحــاالت برقــم ‪34183370‬‬\n      ‫وتاريــخ ‪ 1434/04/21‬ه ـ املقيــدة باحملكمــة برقــم ‪ 34978975‬وتاريــخ‬\n      ‫‪ 1434/04/21‬ه ـ ففــي يــوم األحــد املوافــق ‪1434/05/26‬ه ـ افتتحــت‬\n      ‫اجللســة الســاعة ‪ 08 : 30‬وفيها حضر ‪ .......‬باكســتاني اجلنســية مبوجب‬\n      ‫اإلقامــة رقــم واملدعــى عليه ‪ .......‬باكســتاني اجلنســية حامل االقامة رقم‬\n      ‫والــذي يجيــد اللغــة العربيــة واملترجــم باكســتاني اجلنســية مســلم الديانة‬\n      ‫اقامــة رقــم وادعــى املدعــي عــن طريــق املترجــم قائــا يف دعــواه انــه يف‬\n      ‫تاريــخ ‪1434/2/3‬ه ـ اتفقــت مــع املدعــى عليــه علــى أن يســتخرج تأشــيرة‬\n      ‫لزوجــة أخــي لكونــي علمــت أنــه ســوف يذهــب إلــى الريــاض الســتخراج‬\n\n‫‪345‬‬\n\f‫تأشــيرة لزوجتــه وأخبرنــي بذلــك مــن يعمــل بجــوار محــل املدعــى عليــه‬\n‫وهــو مهنــدس األجهــزة الكهربائيــة واســمه وجنســيته باكســتاني وبعــد‬\n‫أســبوع ســلمت املدعــى عليــه مبلــغ وقــدره اثنــا عشــر ريــال‪ 12000‬وبعــد‬\n‫يومــن اتصــل بــي ليــا وأخبرنــي بأنــه مت اســتخراج التأشــيرة وأنــه ســلم‬\n‫املبلــغ للمكتــب وأرســل لــي رقــم التأشــيرة وقــال ســوف أحضــر غــدا‬\n‫وأســلمك ورقــة التأشــيرة ويف الصبــاح قمــت بتســليم الرقــم لصديــق لــي‬\n‫يدعــى ‪ ......‬يعمــل يف كهربــاء املويــه وقــام بإدخــال الرقــم علــى شــبكة‬\n‫اإلنترنــت ولــم يخــرج أي نتيجــة فأخبــرت املدعــى عليــه بذلــك فقــال‬\n‫بــل التأشــيرة صحيحــة وأرســلها لباكســتان كمــا قــام املدعــى عليــه‬\n‫بتســليمي الورقــة الصفــراء اخلاصــة بالتأشــيرة وســلمتها ألخــي ‪......‬‬\n‫مبكــة فأرســلها بالفاكــس لباكســتان فقــام أخــي الثالــث ويدعــى‬\n‫‪ ......‬فذهــب لســفارة الســعودية بباكســتان فقالــوا لــه إن التأشــيرة‬\n‫مــزورة وأنــا اآلن اطلــب املدعــى عليــه تســليمي املبلــغ الــذي دفعتــه لــه‬\n‫وقــدره اثنــا عشــر ألــف ‪ 12000‬لكــون التأشــيرة مــزورة‪ ،‬وبعــرض‬\n‫الدعــوى علــى املدعــى عليــه قــال مــا ذكــره املدعــي صحيــح كلــه جملــة‬\n‫وتفصيــا ماعــدا قولــه انــه اتصــل بــي صباحــا واخبرنــي أن الرقــم غيــر‬\n‫صحيــح بــل إن ‪ ......‬أخبرنــي بأنــه ال يعــرف الدخــول ملوقــع وزارة اخلارجيــة‬\n‫الســعودية كمــا أخبرنــي املدعــي بــأن أخــاه ‪ ......‬تأكــد مــن التأشــيرة‬\n‫يف مكــة فوجدهــا صحيحــة وأنــا لســت مســتعدا بإرجــاع هــذا املبلــغ ألن‬\n‫املكتــب الــذي تعاملــت معــه غشــني وغــش املدعــى عليــه وقــد شــكيته‬\n‫لــدى شــرطة املربــع بالريــاض ورقــم املعاملــة ‪ ........‬يف ‪1434/2/24‬ه ـ‬\n‫واســم صاحــب املكتــب ‪ .....‬واســم املكتــب ‪ .....‬للخدمــات العامــة وقــد‬\n‫وكلــت شــخص ًا علــى شــكايته ومكتبــه مغلــق وبالفعــل ابــرز صــورة‬\n\n\n                                                                                    ‫‪346‬‬\n\f      ‫وكالــة صــادرة مــن هــذه احملكمــة برقــم ‪ 34413900‬يف ‪1434/4/6‬هـ‬\n      ‫املتضمنــة ( وقــد مت اإلقــرار بتوكيــل ســعودي اجلنســية ســجل مدنــي رقــم‬\n      ‫فيمــا يخــص اجلهــات احلكوميــة وذلــك يف مراكــز الشــرطة ملراجعــة‬\n      ‫احلقــوق يف شــرطة املربــع بالريــاض الســتالم جميــع مســتحقاتي املاليــة‬\n      ‫‪-‬االســتالم والتســليم‪ -‬ومراجعــة جميــع اجلهــات ذات العالقــة وإنهــاء‬\n      ‫جميــع اإلجــراءات الالزمــة والتوقيــع فيمــا يتطلــب ذلــك ) انتهــى كمــا‬\n      ‫ابــرز صــورة ورقــة باســم تذكــرة مراجعــة تأشــيرات لإلقامــة اســتقدام‬\n      ‫الريــاض وعليهــا شــعار وزارة الداخليــة اإلدارة العامــة لشــؤون الوافديــن‬\n      ‫إدارة شــؤون االســتقدام رقــم الصــادر يف ‪1434/2/16‬ه ـ املتضمنــة‬\n      ‫(حيــث تقــرر املوافقــة علــى طلــب رقــم صاحــب العمــل) انتهــى وبســؤال‬\n      ‫املدعــي عــن التأشــيرة ورقمهــا ابــرز صــورة ورقــة باســم تذكــرة مراجعــة‬\n      ‫تأشــيرات لإلقامــة اســتقدام الريــاض وعليهــا شــعار وزارة الداخليــة‬\n      ‫اإلدارة العامــة لشــؤون الوافديــن إدارة شــؤون االســتقدام رقــم الصــادر‬\n      ‫يف ‪1434/2/16‬ه ـ املتضمنــة (حيــث تقــرر املوافقــة علــى طلــب رقــم‬\n      ‫صاحــب العمــل) انتهــى وبعــرض صــورة التأشــيرة علــى املدعــى عليــه‬\n      ‫قــال نعــم هــذه صورتهــا ويف جلســة أخــرى حضــر املتداعيــان وحضــر‬\n      ‫حلضورهمــا املترجــم باكســتاني اجلنســية مبوجــب اإلقامــة رقــم ثــم‬\n      ‫جــرى ســؤالي للمدعــي عــن طريــق املترجــم هــل اتفقــت مــع املدعــى‬\n      ‫عليــه علــى مبلــغ مالــي مقابــل إصــدار التأشــيرة املذكــورة بالدعــوى‬\n      ‫فأجــاب عــن طريــق املترجــم بـ ــا ثــم ســألته هــل تريــد ميينــه علــى انــه‬\n      ‫ســلم املبلــغ للمكتــب الــذي قــام باســتخراج التأشــيرة ولــم يســتخدمه‬\n      ‫يف شــيء غيــره وانــه لــم يســتلم املبلــغ بعــد ذلــك وال شــيء منــه فقــال‬\n      ‫ال فطلبــت أنــا مــن املدعــى عليــه احللــف علــى ذلــك بعــد حتذيــري لــه‬\n\n\n‫‪347‬‬\n\f‫بخطــر اليمــن ان كانــت كاذبــة فأصــر فأذنــت لــه فحلــف قائــا واهلل‬\n‫العظيــم أننــي ســلمت املبلــغ الــذي ســلمنيه املدعــي وقــدره اثنــا عشــر‬\n‫ألــف ريــال‪ 12000‬الســتخراج تأشــيرة لزوجــة أخيــه إلــى موظــف ســعودي‬\n‫مبكتــب للخدمــات العامــة ولــم اســتخدمه يف شــيء غيــره وال اســتلم‬\n‫املبلــغ بعــد ذلــك وال شــيء منــه واهلل العظيــم فبنــاء علــى مــا ســبق مــن‬\n‫الدعــوى واإلجابــة وملصادقــة املدعــى عليــه علــى دعــوى املدعــي ولكــون‬\n‫املدعــي يدعــي بــان املدعــى عليــه اصــدر لــه تأشــيرة مــزورة ولكــون‬\n‫املدعــى عليــه يف املعاملــة احلاصلــة بينهمــا عبــارة عــن وكيــل ولكــون‬\n‫املدعــى عليــه دفــع بــأن تأشــيرته اخلاصــة بــه والصــادرة لزوجتــه مــزورة‬\n‫أيضــا بســبب غــش مكتــب اخلدمــات العامــة لــه ولكونــه قــام مبــا طلــب‬\n‫منــه املدعــي ولكــون الغــش مــن عدمــه ليــس مــن شــأن املدعــى عليــه وال‬\n‫بســببه بــل بســبب صاحــب املكتــب وهــذا ليــس تعديــا وال تفريطــا منــه‬\n‫ولكــون الوكيــل يــده يــد أمانــة باتفــاق الفقهــاء وأنــه ال ضمــان عليــه إال‬\n‫إذا تعــدى أو فــرط وملــا قــرره الفقهــاء مــن أن يــد األمانــة يترتــب عليهــا أن‬\n‫يكــون القــول قــول األمــن مــع ميينــه يف دفــع الضمــان عــن نفســه انظــر‬\n‫ذلــك كلــه يف املوســوعة الفقهيــة الكويتيــة (‪ )86/45‬وحللــف املدعــى‬\n‫عليــه اليمــن املطلوبــة بطلبــي وبعــد اذنــي وحتذيــري لــه مــن خطرهــا ان‬\n‫كانــت كاذبــة بعــد ان قــرر املدعــي رفضهــا لذلــك كلــه فقــد رددت‬\n‫دعــوى املدعــي وأخليــت ســبيل املدعــى عليــه منهــا هــذا مــا ظهــر لــي وبــه‬\n‫حكمــت وبعرضــه علــى الطرفــن قــرر املدعــي عــدم القناعــة ورغــب‬\n‫بتقــدمي الئحــة اعتراضيــه وبعرضــه علــى املدعــى عليــه قــرر قناعتــه‬\n‫باحلكــم وقــررت تنظيــم صــك هــذا اليــوم وجــرى تســليم املعتــرض نســخة‬\n‫منــه هــذا اليــوم وأفهمتــه بــأن لــه مهلــة ثالثــون يومـ ًا لتقــدمي مــا لديــه مــن‬\n\n\n                                                                                             ‫‪348‬‬\n\f      ‫اعتــراض علــى احلكــم واذا انتهــت هــذه املهلــة ولــم يتقــدم بشــي فيســقط‬\n      ‫ـاء علــى املادتــن‬\n                        ‫حقــه يف طلــب التمييــز ويكتســب احلكــم القطعيــة بنـ ً‬\n      ‫السادســة والســبعني بعــد املائــة والثامنــة والســبعني بعــد املائــة مــن نظــام‬\n      ‫املرافعــات الشــرعية ولوائحــه التنفيذيــة وقــد كانــت جميــع أســئلتي‬\n      ‫للمدعــي وأجوبتــه واإلفهــام عــن طريــق املترجــم وأغلقــت اجللســة الســاعة‬\n      ‫الثامنــة والنصــف‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                      ‫وســلم ‪ .‬حــرر يف ‪1434/6/7‬هــ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ففــي يــوم األحــد ‪ 1434/08/21‬ه ـ افتتحــت‬\n      ‫اجللســة الســاعة الثامنــة وقــد عــادت املعاملــة مــن فضيلــة رئيــس محكمة‬\n      ‫االســتئناف مبنطقــة مكــة املكرمــة املكلــف رقــم ‪341667730‬‬\n      ‫بتاريــخ ‪1434/7 /30‬ه ـ وبرفقهــا قــرار أصحــاب الفضيلــة قضــاة‬\n      ‫الدائــرة احلقوقيــة الثالثــة رقــم ‪ 34278741‬بتاريــخ ‪1434/7/25‬ه ـ‬\n      ‫وفيــه (وبدراســة احلكــم وصــورة ضبطــه والئحتــه االعتراضيــة تقــرر‬\n      ‫باألكثريــة إعادتهــا لفضيلتــه إلدخــال املكتــب طــرف ثالــث حســب‬\n      ‫النظــام وفــق اهلل اجلميــع للصــواب ) انتهــى وعليــه أجيــب صاحبــي‬\n      ‫الفضيلــة وفقنــي اهلل وإياهــم لــكل خيــر أوال بــأن طلــب اإلدخــال الــوارد‬\n      ‫يف النظــام طلــب جــوازي وثانيــا أن املكتــب غيــر معــروف لدينــا املعرفــة‬\n      ‫التــي متكــن احملكمــة نظامــا مــن تبليغــه والداللــة عليــه وكل مــا لــدى‬\n      ‫املدعــى عليــه ورقــة عاديــة مصــورة حتمــل اســم املكتــب ولــم يتبــن فيهــا‬\n      ‫ال رقــم ترخيصــه وال غيــره ويف هــذا تطويــل للدعــوى ومضــارة للقاضــي‬\n      ‫يف اســتقصاء ذلــك كلــه وقــررت رفــع املعاملــة إلــى محكمة االســتئناف‬\n      ‫وعليــه أغلقــت اجللســة الســاعة الثامنــة والنصــف وصلــى اهلل علــى نبينــا‬\n                    ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/8/21‬ه ـ‬\n\n\n‫‪349‬‬\n\f‫احلمــد هلل وحــده وبعــد ففــي يــوم الثالثــاء ‪ 1434/10/6‬ه ـ افتتحــت‬\n‫اجللســة الســاعة التاســعة والنصــف وقــد عــادت املعاملــة مــن فضيلــة‬\n‫رئيــس محكمــة االســتئناف مبنطقــة مكــة املكرمــة املكلــف برقــم‬\n‫‪ 341021262‬بتاريــخ ‪1434/9/13‬ه ـ وبرفقهــا قــرار أصحــاب الفضيلــة‬\n‫قضــاة الدائــرة احلقوقيــة الثالثــة رقــم ‪ 34311444‬بتاريــخ ‪1434/9/2‬ه ـ‬\n‫ونــص احلاجــة منــه ( بدراســة احلكــم وصــورة ضبطــه والئحتــه‬\n‫االعتراضيــة تقــررت املوافقــة علــى احلكــم بعــد اإلجــراء األخيــر ) انتهــى‬\n‫وعليــه أغلقــت اجللســة الســاعة العاشــرة وصلــى اهلل علــى نبينــا محمــد‬\n                         ‫وعلــى الــه وصحبــه وســلم حــرر ‪1434/10/6‬ه ـ ‪.‬‬\n\n\n\n\n                                                                                   ‫‪350‬‬\n\f                     ‫كشاف املوضوعات‬\n\n‫الصفحة‬                     ‫املوضوع‬                      ‫التصنيف‬   ‫م‬\n\n\n          ‫مطالبة املدعي للمدعى عليه بسداد القرض‬\n  ‫‪5‬‬                                                      ‫قرض‬      ‫‪1‬‬\n                    ‫الذي أقرضه إياه‬\n\n\n           ‫مطالبة املدعي للمدعى عليها بسداد باقي‬\n  ‫‪23‬‬                                                     ‫قرض‬      ‫‪2‬‬\n           ‫القرض الذي أقرضه إياها مورث املدعي‬\n\n\n          ‫مطالبة املدعية للمدعى عليه بسداد القرض‬\n  ‫‪28‬‬      ‫الذي أقرضته إياه مستندة على إقرار خطي‬          ‫قرض‬      ‫‪3‬‬\n                   ‫منسوب للمدعى عليه‬\n\n\n          ‫مطالبة املدعي للمدعى عليه بسداد القرض‬\n  ‫‪33‬‬      ‫الذي أقرضه إياه واتفقا على تسديده بثالث‬        ‫قرض‬      ‫‪4‬‬\n                  ‫دفعات ولم يسدد أي ًا منها‬\n\n\n           ‫مطالبة املدعي للمدعى عليه بسداد القرض‬\n  ‫‪40‬‬     ‫الذي أقرضه إياه بينما اعترض املدعى عليه بأن‬     ‫قرض‬      ‫‪5‬‬\n                ‫املبلغ كان للمتاجرة وليس قرضاً‪.‬‬\n\n\n          ‫مطالبة املدعي للمدعى عليه بسداد القرض‬\n  ‫‪45‬‬       ‫الذي أقرضه إياه ولتخلف املدعى عليه عن‬         ‫قرض‬      ‫‪6‬‬\n          ‫احلكم مت التنويه بأنه على حجته متى حضر‬\n\n\n           ‫مطالبة املدعي للمدعى عليه بسداد القرض‬\n         ‫الذي أقرضه إياه بينما اعترض املدعى عليه بأن‬\n  ‫‪50‬‬     ‫املبلغ ليس قرض ًا بل كان مقابل تنازله للمدعي‬    ‫قرض‬      ‫‪7‬‬\n          ‫عن قطعة أرض وإشرافه على عمارته القائمة‬\n                        ‫على تلك األرض‬\n\f‫الصفحة‬                      ‫املوضوع‬                       ‫التصنيف‬   ‫م‬\n\n\n          ‫مطالبة املدعي للمدعى عليه بسداد القرض‬\n         ‫الذي أقرضه لطرف ثالث وضمنه املدعى عليه‬\n  ‫‪57‬‬                                                       ‫قرض‬      ‫‪8‬‬\n         ‫فيما بقي من املبلغ حيث اختفى الطرف الثالث‬\n                      ‫وال يعرف له مكان‬\n\n\n          ‫مطالبة املدعي للمدعى عليه بسداد القرض‬\n  ‫‪63‬‬                                                       ‫قرض‬      ‫‪9‬‬\n          ‫الذي أقرضه إياه بشيك قام بصرفه من البنك‬\n\n\n         ‫مطالبة املدعي للمدعى عليه بسداد املبلغ املالي‬\n          ‫الذي أعطاه إياه للمضاربة به مع األرباح بينما‬\n  ‫‪68‬‬                                                       ‫قرض‬      ‫‪10‬‬\n           ‫اعترض املدعى عليه بأن املبلغ كان مقابل‬\n         ‫قرض حسن سبق أن أعطاه املدعى عليه للمدعي‬\n\n\n         ‫مطالبة املدعي للمدعى عليه بسداد املبلغ املالي‬\n  ‫‪72‬‬      ‫الذي قام املدعى املدعي بسداده عنه لطرف‬           ‫قرض‬      ‫‪11‬‬\n                 ‫ثالث لكونه ضامنا له ولم يسدد‬\n\n\n         ‫مطالبة املدعية للمدعى عليه بسداد املبلغ املالي‬\n         ‫الذي قام باقتراضه من مورثها وسدد جزء منه‬\n  ‫‪79‬‬                                                       ‫قرض‬      ‫‪12‬‬\n          ‫حال حياته وقام بأداء اليمني على ذلك لرفض‬\n                          ‫املدعية أداء اليمني‬\n\n\n           ‫مطالبة املدعي للمدعى عليه بسداد القرض‬\n  ‫‪89‬‬     ‫الذي أقرضه إياه بينما اعترض املدعى عليه بأن‬       ‫قرض‬      ‫‪13‬‬\n                   ‫مهلة السداد لم تنتهي بعد‬\n\n\n           ‫مطالبة املدعي للمدعى عليه بسداد القرض‬\n  ‫‪93‬‬                                                       ‫قرض‬      ‫‪14‬‬\n           ‫الذي أقرضه إياه وأنكر املدعى عليه ذل‬\n\f‫الصفحة‬                     ‫املوضوع‬                     ‫التصنيف‬   ‫م‬\n\n\n          ‫مطالبة املدعي للمدعى عليه بسداد القرض‬\n         ‫الذي أقرضه إياه وكتب له سند ًا بناء على ذلك‬\n ‫‪100‬‬                                                    ‫قرض‬      ‫‪15‬‬\n         ‫حيث سبق أن صدر به قرار من مكتب الفصل‬\n                         ‫باألوراق التجارية‬\n\n\n           ‫مطالبة املدعي للمدعى عليه بسداد القرض‬\n ‫‪113‬‬       ‫الذي أقرضه إياه وقدم بينة على ذلك شاهد‬       ‫قرض‬      ‫‪16‬‬\n                           ‫وميينه‬\n\n\n           ‫مطالبة املدعي للمدعى عليه بسداد القرض‬\n            ‫الذي أقرضه إياه واعترض املدعي أن املبلغ‬\n ‫‪117‬‬                                                    ‫قرض‬      ‫‪17‬‬\n         ‫املذكور لم يكن وإمنا كان مقابل عدة مشاريع‬\n                         ‫يف مجال اإلنشاء‬\n\n\n           ‫مطالبة املدعية للمدعى عليه بسداد القرض‬\n ‫‪128‬‬        ‫الذي أقرضته إياه عندما قامت ببيع صوري‬       ‫قرض‬      ‫‪18‬‬\n         ‫للذهب اخلاص بها لسداد بعض الديون التي عليه‬\n\n\n           ‫مطالبة املدعي بإثبات إعساره مع أن الديون‬\n ‫‪139‬‬     ‫اخلاصة به مترتبة على أفعال مجرمة ‪،‬وهي مما‬      ‫إعسار‬    ‫‪19‬‬\n                  ‫ال ينظر فيها دعوى اإلعسار‬\n\n\n           ‫مطالبة املدعي بإثبات إعساره وثبوت ذلك‬\n ‫‪145‬‬      ‫لكون الدين لزمه بغير اختياره وأدى اليمني‬      ‫إعسار‬    ‫‪20‬‬\n                           ‫على ذلك‬\n\n\n          ‫مطالبة املدعي بإثبات إعساره وثبوت ذلك بناء‬\n ‫‪154‬‬                                                    ‫إعسار‬    ‫‪21‬‬\n                      ‫على شهادة الشهود‬\n\f‫الصفحة‬                     ‫املوضوع‬                     ‫التصنيف‬   ‫م‬\n\n\n          ‫مطالبة املدعي بإثبات إعساره وثبوت ذلك بناء‬\n ‫‪163‬‬                                                    ‫إعسار‬    ‫‪22‬‬\n                ‫على شهادة الشهود وميينه على ذلك‬\n\n\n         ‫مطالبة املدعي بإثبات إعساره وعدم إثبات ذلك‬\n ‫‪173‬‬     ‫لكون الدين املستحق عليه ناجت عن عملية نصب‬      ‫إعسار‬    ‫‪23‬‬\n            ‫واحتيال أدين بها بحكم شرعي سابق‬\n\n\n          ‫مطالبة املدعي بإثبات إعساره وثبوت ذلك بناء‬\n ‫‪177‬‬                                                    ‫إعسار‬    ‫‪24‬‬\n                      ‫على شهادة الشهود‬\n\n\n          ‫مطالبة املدعي بإثبات إعساره بناء على دين‬\n ‫‪184‬‬     ‫مستحق يف ذمته صادر به حكم شرعي وثبوت‬           ‫إعسار‬    ‫‪25‬‬\n                ‫ذلك بناء على شهادة الشهود‬\n\n\n          ‫مطالبة املدعي بإثبات إعساره بناء على حداث‬\n ‫‪189‬‬     ‫مروري نتج عنه وفاة مورث املدعى عليهما وثبوت‬    ‫إعسار‬    ‫‪26‬‬\n                  ‫ذلك بناء على شهادة الشهود‬\n\n\n         ‫مطالبة املدعي بإثبات إعساره باإلضافة لوجود‬\n ‫‪195‬‬     ‫غرماء كثر غير املدعى عليهم وثبوت ذلك بناء‬      ‫إعسار‬    ‫‪27‬‬\n                      ‫على شهادة الشهود‬\n\n\n          ‫مطالبة املدعي بإثبات إعساره وإنكار املدعى‬\n ‫‪205‬‬      ‫عليه لذلك وإقراره بأنه مليء دون إحضار بينة‬    ‫إعسار‬    ‫‪28‬‬\n         ‫على ذلك وثبوت إعساره بناء على شهادة الشهود‬\n\n\n          ‫مطالبة املدعي بإثبات إعساره وثبوت ذلك بناء‬\n ‫‪210‬‬                                                    ‫إعسار‬    ‫‪29‬‬\n                      ‫على شهادة الشهود‬\n\f‫الصفحة‬                       ‫املوضوع‬                       ‫التصنيف‬     ‫م‬\n\n\n            ‫مطالبة املدعي بإثبات إعساره مع عدم علم‬\n ‫‪216‬‬      ‫املدعى عليه بذلك وثبوت ذلك بناء على شهادة‬         ‫إعسار‬      ‫‪30‬‬\n                           ‫الشهود‬\n\n\n          ‫مطالبة املدعي بإثبات إعساره وثبوت ذلك بناء‬\n ‫‪223‬‬                                                        ‫إعسار‬      ‫‪31‬‬\n                      ‫على شهادة الشهود‬\n\n\n          ‫مطالبة املدعي بإثبات إعساره ورد ذلك لكون‬\n ‫‪229‬‬                                                        ‫إعسار‬      ‫‪32‬‬\n            ‫الديون ناجتة عن سرقات قام بها املدعي‬\n\n\n          ‫مطالبة املدعي بإثبات إعساره ورد ذلك لثبوت‬\n ‫‪235‬‬                                                        ‫إعسار‬      ‫‪33‬‬\n                           ‫احتياله‬\n\n\n            ‫مطالبة املدعي بإثبات إعساره وثبوت ذلك‬\n ‫‪244‬‬                                                        ‫إعسار‬      ‫‪34‬‬\n                        ‫بشهادة الشهود‬\n\n\n          ‫مطالبة املدعي بإثبات إعساره لتقاعده وعدم‬\n ‫‪249‬‬                                                        ‫إعسار‬      ‫‪35‬‬\n            ‫قدرته على النفقة املتقررة عليه لوالده‬\n\n\n          ‫مطالبة املدعي بإثبات إعساره وعاقلته وثبوت‬\n ‫‪254‬‬                                                        ‫إعسار‬      ‫‪35‬‬\n                     ‫ذلك بشهادة الشهود‬\n\n\n             ‫مطالبة املدعي ببراءة ذمته من املديونية ألحد‬\n ‫‪263‬‬                                                       ‫براءة ذمة‬   ‫‪36‬‬\n          ‫مقدمي اخلدمة على العقار الذي اشتراه مؤخر ًا‬\n\n\n         ‫مطالبة أم ابن زوجها بفسخ واليته عن أخيه الذي‬\n ‫‪273‬‬       ‫هو ابن املدعية وجعلها للمدعية ألنها األحق‬         ‫والية‬     ‫‪37‬‬\n                            ‫بالوالية‬\n\f‫الصفحة‬                      ‫املوضوع‬                       ‫التصنيف‬         ‫م‬\n\n\n            ‫مطالبة املدعية أبيها الغائب بإسقاط والية‬\n ‫‪280‬‬                                                         ‫والية‬        ‫‪38‬‬\n                 ‫التزويج عنه لغيبته وجعلها ألخيها‬\n\n\n         ‫مطالبة أم بفسخ والية األوصياء املعينني من والد‬\n ‫‪285‬‬                                                         ‫والية‬        ‫‪39‬‬\n                    ‫القصر وجعلها للمدعية‬\n\n\n             ‫مطالبة اجلدة الم بإلغاء والية اجلد ألب على‬\n           ‫القصر من أوالد ابنتها وجعلها لها ألن املدعى‬\n                       ‫عليه كبير يف السن‬\n            ‫وال يستطيع القيام بأعباء الوالية وأنه أصدر‬\n ‫‪309‬‬                                                         ‫والية‬        ‫‪40‬‬\n                      ‫وكالة البنه الذي هو‬\n         ‫عم األوالد للقيام بشؤون القصر وأن املدعى عليه‬\n                        ‫ووكيله لم يقوما‬\n                    ‫بأي شيء جتاه القاصرين‬\n\n\n ‫‪319‬‬          ‫مطالبة االبن باحلجر على والده لسفهه‬         ‫حجر ل َِس َفه‬   ‫‪41‬‬\n\n\n          ‫مطالبة املدعي للمدعى عليه بإعادة املبلغ الذي‬\n ‫‪331‬‬                                                        ‫وكالة‬         ‫‪42‬‬\n                     ‫سلمه له ليشتري له سيارة‬\n\n\n          ‫مطالبة املدعي للمدعى عليه بإعادة املبلغ الذي‬\n ‫‪336‬‬      ‫سلمه له ليشتري له سيارات خالل مدة معينة‬           ‫وكالة‬         ‫‪43‬‬\n                        ‫لكونه لم يقم بذلك‬\n\n\n         ‫مطالبة املدعي للمدعى عليه بإعادة املبلغ الذي‬\n ‫‪344‬‬     ‫سلمه له ليستخرج له تأشيرة سفر لزوجته حيث‬           ‫وكالة‬         ‫‪44‬‬\n              ‫تبني أن التأشيرة املستخرجة مزورة‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"8772d0b1-3c0f-5928-9c22-98c49da1913e","source_page_start":344,"source_page_end":356,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"bf1a6e3a5458bccb49a1f16c584db8c31f3306cf2549118f8de645c8c503984b","normalized_text_hash":"6fb9677b07aad5a92710d8c82966a0c98eb3f6f2ac17f1bde5cd95bc3be572b1","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v4-p344-34234533"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS legal_documents,
       (SELECT count(*) FROM public.document_files WHERE document_id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"972e8276-8bbe-597e-b976-502c3a84d7a4","document_type":"judgment","category":"judicial","subcategory":"general","title":"والية -مطالبة أم بإلغاء صك وصية وإقامتها ولية على أوالدها- املدعى عليهم مجلس وصاية أقامه األب قبل وفاته وهو يف حالته املعتبرة شرعا -القدح يف األوصياء دون إثبات ذلك -الوصي مقدم يف الوالية على األم وغيرها من األقرباء -احلكم برد الدعوى.","document_number":"34223712","case_number":"33681315","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/5/27","year":"1434","subject":"والية -مطالبة أم بإلغاء صك وصية وإقامتها ولية على أوالدها- املدعى عليهم مجلس وصاية أقامه األب قبل وفاته وهو يف حالته املعتبرة شرعا -القدح يف األوصياء دون إثبات ذلك -الوصي مقدم يف الوالية على األم وغيرها من األقرباء -احلكم برد الدعوى.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/5/27 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪34223712 :‬‬\n                         ‫َر ْق ُم الدعوى‪33681315 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 342284817‬تاريخه‪1434/8/1 :‬هـ‬\n\n\n      ‫واليــة ‪ -‬مطالبــة أم بإلغــاء صــك وصيــة وإقامتهــا وليــة علــى أوالدهــا‪-‬‬\n      ‫املدعــى عليهــم مجلــس وصايــة أقامــه األب قبــل وفاتــه وهــو يف حالتــه‬\n      ‫املعتبــرة شــرعا ‪ -‬القــدح يف األوصيــاء دون إثبــات ذلــك ‪ -‬الوصــي مقــدم‬\n            ‫يف الواليــة علــى األم وغيرهــا مــن األقربــاء ‪ -‬احلكــم بــرد الدعــوى‪.‬‬\n\n\n\n      ‫قــال البهوتــي (إن وصــي األب مقــدم علــى غيــره) كشــاف القنــاع‬\n                       ‫‪ -383/8‬وانظــر‪ :‬الــكايف البــن قدامــه (‪. )251/3‬‬\n\n\n\n      ‫ادعــت أم بطلــب إلغــاء صــك الوصايــة الصــادر مــن احملكمــة علــى‬\n      ‫أوالدهــا وإقامتهــا وليــة عليهــم ‪ -‬املدعــى عليهــم أوصيــاء معينــن مــن‬\n      ‫قبــل والــد القصــر وهــو يف حالتــه املعتبــرة شــرعا ‪ -‬رفــض املدعــى عليهــم‬\n      ‫إلغــاء صــك الوصايــة ألنــه صــادر مــن والدهــم وثابــت لــدى احملكمــة‬\n      ‫بصــك شــرعي ‪ -‬حاولــت املدعيــة القــدح يف صــك الوصايــة بأنــه ال يلــزم‬\n      ‫املضــي فيــه ويجــوز العــدول عنــه للمصلحــة وأن مصلحــة القصــر أن‬\n      ‫تتولــى عليهــم أمهــم املدعيــة وذكــرت أن األوصيــاء فرطــوا يف الواليــة‬\n      ‫وتصرفــوا يف أمــوال القصــر مبــا يقــدح يف أمانتهــم ثــم طلبــت بشــكل‬\n      ‫عاجــل إثبــات رشــد أحــد القاصــرات لبلوغهــا ‪ -‬أنكــر املدعــى عليهــم‬\n      ‫التهــم التــي ذكــرت املدعيــة وذكــروا أن التهــم التــي ذكــرت املدعيــة‬\n‫‪285‬‬\n\f‫ســبق إثارتهــا مــن املدعيــة يف قضيــة ســابقة لــدى احملكمــة ولــم تســتطع‬\n‫إثباتهــا وطالبوهــا بالبينــة كمــا ذكــر املدعــى عليهــم أن وصــي األب‬\n‫مقــدم علــى األم يف الواليــة وأن والــد أوالد املدعيــة واملدعــى عليهــم‬\n‫أقــام مجلــس األوصيــاء لعلمــه أن نصيــب القصــر مــن املــال كبيــر جــد ًا‬\n‫وال تســتطيع أم األوالد القيــام بــه وال اســتثماره ولهــذا أقــام والدهــم‬\n‫مجلــس األوصيــاء ‪ -‬لــم تســتطع املدعيــة إثبــات القــدح يف املدعــى عليهــم‬\n‫وأبــرز املدعــى عليهــم أوراق ومســتندات تــدل علــى قيامهــم باســتثمار‬\n‫أمــوال القصــر بشــكل صحيــح ‪ -‬وألن وصــي األب مقــدم علــى األم‬\n‫وألن الوصيــة ثابتــة بصــك شــرعي مــن والــد أوالد املدعيــة وهــو يف‬\n‫حالتــه املعتبــرة شــرع ًا ومكتســب للقطعيــة بتصديقــه مــن محكمــة‬\n‫االســتئناف وألن مــا قدمتــه املدعيــة مــن قــدح يف املدعــى عليهــم ال يرقــى‬\n‫إلــى عــزل األوصيــاء لــذا ردت احملكمــة دعــوى املدعيــة ‪ -‬اعترضــت‬\n                      ‫املدعيــة ‪ -‬صــدق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ ).....‬القاضــي يف احملكمــة العامــة‬\n‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بالريــاض املســاعد برقــم ‪ 33681315‬وتاريــخ ‪1433/11/29‬ه ـ‬\n‫املقيــدة باحملكمــة برقــم ‪ 332140020‬وتاريــخ ‪1433/11/29‬ه ـ‬\n‫ففــي يــوم الســبت املوافــق ‪1434/02/16‬ه ـ افتتحــت اجللســة األولــى‬\n‫ا عــن مبوجــب‬  ‫الســاعة ‪ 11 : 30‬وفيهــا حضــر (‪ ).....‬بصفتــه وكي ـ ً‬\n‫الوكالــة رقــم ‪ 73002‬يف ‪1429/09/03‬ه ـ جلــد صــادر مــن كتابــة‬\n‫العــدل الثانيــة جنــوب الريــاض واملتضمنــة لــه حــق ســماع الدعــوى والــرد‬\n\n                                                                                   ‫‪286‬‬\n\f      ‫عليهــا واالقــرار واالنــكار والصلــح وطلــب اليمــن ورده وقبــول احلكــم‬\n      ‫ونفيــه واالعتــراض عليــه وطلــب متييــزه وحضــر (‪ ).....‬حلضــوره مبوجــب‬\n      ‫ا عــن ســجل مدنــي رقــم (‪).....‬‬         ‫ســجل مدنــي رقــم (‪ )....‬بصفتــه وكي ـ ً‬\n      ‫بصفتــه (‪ )....‬وولي ـ ًا عــن وابنــاء مبوجــب صــك الواليــة رقــم ‪33356475‬‬\n      ‫بتاريــخ ‪1433/7/26‬ه ـ صــادر مــن احملكمــة العامــة بالوكالــة رقــم‬\n      ‫ا عــن ســجل مدنــي‬      ‫‪ 33431602‬يف ‪1433/11/29‬ه ـ وبصفتــه وكي ـ ً‬\n      ‫رقــم (‪ )....‬بصفتــه ولي ـ ًا عــن (‪ )....‬و(‪ )....‬وابنــاء مبوجــب صــك الواليــة‬\n      ‫رقــم ‪ 33356475‬بتاريــخ ‪1433/07/26‬ه ـ صــادر مــن احملكمــة العامــة‬\n      ‫بالريــاض مبوجــب الوكالــة رقــم ‪ 33433031‬يف ‪1433/11/29‬ه ـ‬\n      ‫ا عن‬  ‫صــادره مــن كتابــة العــدل الثانيــة بجنــوب الريــاض وبصفتــه وكيـ ً‬\n      ‫(‪ )....‬ســعودي ســجل مدنــي رقــم (‪ )....‬بصفتــه وليـ ًا عــن (‪ )....‬و(‪ )....‬وابنــاء‬\n      ‫مبوجــب صــك الواليــة رقــم ‪ 33356475‬بتاريــخ ‪1433/07/26‬ه ـ صــادر‬\n      ‫مــن احملكمــة العامــة بالوكالــة رقــم يف ‪1433/11/29‬ه ـ مبوجــب‬\n      ‫الوكالــة رقــم ‪ 34115197‬يف ‪1434/01/28‬ه ـ صــادره مــن كتابــة‬\n      ‫ا عــن بصفتــه ولي ـ ًا عــن‬   ‫العــدل الثانيــة جنــوب الريــاض وبصفتــه وكي ـ ً‬\n      ‫أبنــاء مبوجــب صــك الواليــة رقــم ‪ 33356475‬بتاريــخ ‪1433/07/26‬ه ـ‬\n      ‫صــادر مــن احملكمــة العامــة بالريــاض مبوجــب الوكالــة رقــم‬\n      ‫‪ 33434106‬يف ‪1433/11/29‬ه ـ صــادر مــن كتابــة العــدل الثانيــة‬\n      ‫بجنــوب الريــاض واملتضمنــة جميعهــا (املطالبــة واقامــة الدعــاوي‬\n      ‫واملرافعــة واملدافعــة وســماع الدعــاوي والــرد عليهــا واالقــرار واالنــكار‬\n      ‫والصلــح وطلــب اليمــن ورده واالمتنــاع عنــه ) وادعــى املدعــي وكالــة‬\n      ‫قائــا أقــدم دعــواي هــذه ضــد املدعــى عليهــم املوضــح اســمائهم بعاليــه‬\n      ‫وموضــوع الدعــوى بالتفصيــل مــا يلــي حيــث إنــه قــد صــدر منكــم صــك‬\n\n\n‫‪287‬‬\n\f‫إثبــات إقامــة وصــي رقــم ‪ 33356475‬وتاريــخ ‪1433/7/26‬ه ـ واملتضمــن‬\n‫إقامــة كل مــن أوصيــاء علــى كل مــن (‪ )....‬و(‪ ).....‬وأبنــاء (‪ ).....‬رحمــه‬\n‫اهلل وحيــث إن والدهــم قــد تــويف يــوم الثالثــاء ‪1433/11/9‬ه وحيــث إن‬\n‫والدتهــم هــي مــن ترعــى مصاحلهــم والقيــام علــى شــؤونهم مبوجــب صــك‬\n‫اإلعالــة رقــم ‪ 31/100/338‬وتاريــخ ‪1430/8/12‬ه ـ وحيــث إنهــا أرئــف‬\n‫بحالهــم وأكثــر حرص ـ ًا علــى مصاحلهــم وخشــية وقــوع الضــرر عليهــم‬\n‫مــن تنصيــب هــؤالء أوصيــاء يف حــال وفــاة والدهــم أطلــب احلكــم بإلغــاء‬\n‫صــك الوصايــة املذكــور أعــاه وإقامــة موكلتــي (والــدة األبنــاء) وليــة‬\n‫عليهــم هــذه دعــواي وبعــرض ذلــك علــى املدعــى عليــه وكالــة أجــاب‬\n‫مبــا يلــي‪ -1 :‬ســبق وأن عـ ّـن الشــيخ (‪ ).....‬يف حياتــه مجلس ـ ًا للواليــة‬\n‫ـاء علــى وصيتــه املثبتــة برقــم ‪3339658‬‬     ‫علــى القصــر مــن أبنائــه بنـ ً‬\n‫ـاء عليهــا صــدر صــك شــرعي مــن مكتــب‬        ‫وتاريــخ ‪1433/1/22‬ه ـ وبنـ ً‬\n‫فضيلتكــم برقــم ‪ 33356475‬وتاريــخ ‪1433/7/26‬ه ـ بإقامــة كل مــن‬\n‫‪ :‬أبنــاء الشــيخ(‪ ).....‬أوصيــاء علــى القصــر يرعــون شــؤونهم ومصاحلهــم‬\n‫وحيــث إن هــذا الصــك الصــادر مــن فضيلتكم ســاري املفعــول حتى بعد‬\n‫وفــاة الشــيخ (‪ ).....‬كمــا جــاء يف حاشــيتكم علــى خطــاب الشــيخ (‪)....‬‬\n‫القاضــي يف هــذه احملكمــة فــا وجــه للمطالبــة بإلغائــه ال شــرع ًا وال‬\n‫نظامــا ً‪ -2‬مــن الثابــت عنــد فقهــاء احلنابلــة وهــو املعمــول بــه يف محاكــم‬\n‫القصــر واإلشــراف‬\n                 ‫ّ‬     ‫أن وصـ ّـي األب مقــدم علــى األم يف رعايــة‬\n                                                                 ‫اململكــة َّ‬\n‫عليهــم قــال ابــن قدامــة ‪ « :‬ويتولــى األب مــال الصبــي واملجنــون ألنهــا‬\n‫واليــة علــى الصغيــر فقــدم فيهــا األب كواليــة النــكاح ثــم وصيــة‬\n‫بعــده ألنــه نائبــه فأشــبه وكيلــه يف احليــاة « الــكايف (‪ ،)251/3‬وقــال‬\n‫البهوتــي « ثــم تثبــت الواليــة علــى صغيــر ومجنــون بعــد األب لوصيــة‬\n\n\n                                                                                     ‫‪288‬‬\n\f      ‫العــدل « كشــاف القنــاع (‪ )383/8‬لذلــك كلــه نأمــل التكــرم بإمضــاء‬\n      ‫الصــك الواليــة الصــادر مــن مكتــب فضيلتكــم برقــم ‪33356475‬‬\n      ‫وتاريــخ ‪1433/7/26‬ه ـ واحلكــم بــرد الدعــوى كونهــا تأتــي مخالف ـ ًا‬\n      ‫ملــا عليــه الوصيــة وملــا قــرره فقــاء املذهــب وبعــرض ذلــك علــى املدعــي‬\n      ‫وكالــة أجــاب أطلــب مهلــة للــرد علــى دفــع املدعــى عليــه وكالــة هكــذا‬\n      ‫أجــاب ثــم يف يــوم الثالثــاء ‪1434/04/16‬ه ـ افتتحــت اجللســة الثانيــة‬\n      ‫الســاعة ‪ 08:30‬وفيهــا حضــر املدعــي وكالــة واملدعــى عليــه وكالــة‬\n      ‫وبســؤال املدعــي وكالــة عــن جوابــه أبــرز مذكــرة مكونــة مــن ســبع‬\n      ‫صفحــات ومتضمنــه مــا نصــه أو ًال ‪ :‬أن الصــك الصــادر مــن فضيلتكــم‬\n      ‫برقــم ‪ 33356475‬وتاريــخ ‪1433/7/26‬ه ـ املتضمــن تعيــن املذكوريــن‬\n      ‫أوصيــاء علــى أوالد موكلتــي قــد صــدر يف غيــر اختصــاص ‪ ،‬حيــث‬\n      ‫إن صــدور ذلــك الصــك كان يف وقــت حيــاة ‪ ،‬وقــد أقامــت موكلتــي‬\n      ‫الدعــوى رقــم ‪ 29/131631‬وتاريــخ ‪1429/10/18‬ه ـ واحملالــة إلــى‬\n      ‫مكتب فضيلة الشيخ (‪ )......‬بطلب نزع الوالية من على أوالد موكلتي‬\n      ‫لفقــده األهليــة ‪ ،‬وحيــث إن الدعــوى بعــد حضــور جلســتني فيهــا قــد‬\n      ‫أوقفــت بنــاء علــى املــادة ‪ 82‬مــن نظــام املرافعــات الشــرعية حلــن االنتهــاء‬\n      ‫ـاء عليــه فإنــه بانتهــاء‬\n                              ‫مــن نظــر القضيــة املتعلقــة باحلجــر علــى (‪ )......‬وبنـ ً‬\n      ‫القضيــة املذكــورة يكــون تعيــن أوصيــاء أو أوليــاء علــى القصــر هــو‬\n      ‫مــن اختصــاص مــن قــام عنــده النــزاع ابتــداء ثاني ـ ًا ‪:‬أن احتجــاج املدعــى‬\n      ‫عليــه وكالــة بالوصيــة املنســوبة لــ(‪( ).........‬وهــو مــا لــم نســلم بثبوتــه)‬\n      ‫ال يلــزم منــه إطالق ـ ًا لــزوم توليــة املذكوريــن علــى أوالد موكلتــي ملــا‬\n      ‫ـاء هــو جــواز عــدول القاضــي عــن نــص‬       ‫يلــي ‪ 1 :‬ـ أن الثابــت فقه ـ ًا وقضـ ً‬\n      ‫املوصــي متــى تبــن لــه املصلحــة يف ذلــك وعلــى ذلــك جــاءت نصــوص‬\n\n\n‫‪289‬‬\n\f‫األئمــة ‪ -‬قــال شــيخ اإلســام كمــا يف االختيــارات (( يجــوز تغييــر نــص‬\n‫الواقــف فيمــا هــو أحــب إلــى اهلل ورســوله وأكثــر مصلحــة دينيــة ممــا‬\n‫حلظــه الواقــف ))‪ ،‬وقــال يف موضــع آخــر (( ويجــوز تغييــر شــرط الواقــف‬\n‫إلــى مــا هــو أصلــح منــه وإن اختلــف ذلــك باختــاف الزمــان واملــكان ))‬\n‫‪ ،‬فاملتعــن هــو التحــوط ملــال ومصلحــة املولــى عليــه بأقصــى مــا ميكــن‬\n‫ولــو كان بتغييــر وصيــة املولــي ‪ ،‬والواليــة علــى لقاصــر أولــى مــن الوقف‬\n‫يف هــذا لكونهــا تتعلــق بحقــوق اآلدميــن املبنيــة علــى املشــاحة وليســت‬\n‫كالوقــف الــذي هومــن بــاب التبرعــات باجلملــة ‪2‬ـ أن مقصــد إقامــة‬\n‫الوصــي هــو حفــظ حقــوق القصــر ومراعــاة مصاحلهــم ‪ ،‬فــإذا تبــن أن‬\n‫املصلحــة يف غيــر مــن ســماه املوصــي أو أن الضــرر ممــن ســماه محقــق‬\n‫جــازت املخالفــة بــل تعينــت ‪ ،‬فاحتجــاج املدعــى عليــه مبــا ذكــره مــن‬\n‫تســمية املذكوريــن ال محــل لــه إذا حصلــت العــداوة بينهــم وبــن القصــر‬\n‫‪ ،‬وأي عــداوة أســرية أشــد ممــا شــاهدناه يف هــذه الدعــوى مــن إقامــة‬\n‫دعــوى القــذف وتطليــق األم مرتــن وطردهــا وأوالدهــا القصــر مــن‬\n‫ا ثالثـ ًا ‪ -:‬أن تضــاد املصالــح‬‫منزلهــم كمــا ســوف يأتــي ذكــره تفصيـ ً‬\n‫بــن املوصــي بهــم ( أوالد موكلتــي ) وبــن األوصيــاء املســمني ظاهــر‬\n‫‪ ،‬حيــث إن األوصيــاء املذكوريــن هــم الذيــن عينــوا أنفســهم وكالء‬\n‫عــن الوالــد فتــرة مرضــه وذلــك مــن عــام ‪1428‬ه ـ مــرور ًا بتاريــخ إقامــة‬\n‫موكلتــي الدعــوى بطلــب احلجــر يف شــهر محــرم عــام ‪1429‬ه ـ إلــى وقــت‬\n‫تعيينهــم أوليــاء علــى الوالــد وتصديــق ذلــك من التمييــز يف ‪1433/7/8‬هـ‬\n‫‪ ،‬وحيــث إن تصرفاتهــم الســابقة كلهــا حتتــاج إلــى محاســبة وأن هــذه‬\n‫احلقــوق التــي ســوف يحاســب املعينــون عليهــا قــد انتقلــت مــن الوالــد‬\n‫(املــورث) إلــى الورثــة ( ومنهــم القصــر ) لــذا فــإن مــن حــق القصــر أن‬\n\n\n                                                                                   ‫‪290‬‬\n\f      ‫يقــوم علــى شــأنهم مــن ال مينعــه مانــع مــن محاســبة األوليــاء والــوكالء و‬\n      ‫املتصرفــن عنــوة يف أمــوال والدهــم وتعيــن املذكوريــن يف الوصيــة هــو‬\n                                                   ‫يف حقيقتــه منــع للمحاســبة املتعينــة‬\n      ‫رابع ـ ًا ‪ -:‬اعتــداء بعــض املذكوريــن بانفرادهــم علــى حقــوق والدهــم‬\n      ‫وتعــن محاســبتهم بإقامــة الدعــاوى عليهــم بطلــب مــا بأيديهــم مــن أمــوال‬\n                           ‫التركــة والتــي بعضهــا حــق للقصــر ومــن ذلــك مــا يلــي‪:‬‬\n      ‫‪ -1‬اعتــداء يزيــد علــى مبلــغ قــدره مائــة مليــون ريــال حيــث اســتغل مــرض‬\n      ‫والــده وأخــذ منــه توقيــع علــى حتويــل مائــة ألــف ســهم مــن أســهم شــركة‬\n      ‫(‪ ).........‬األهليــة مــن محفظــة الوالــد الشــيخ (‪ ).........‬رقــم (‪ ).........‬إلــى‬\n      ‫محفظــة (‪ ،).........‬وبنــاء عليــه فــإن علــى العضــو املعــن يف الوصيــة إعــادة‬\n      ‫نصيــب القصــر إليهــم بنــاء علــى طلــب مــن املجلــس فكيــف يكــون هــذا‬\n                                                                                            ‫‪.‬‬\n      ‫‪ -2‬اعتــداء املذكوريــن جميع ـ ًا علــى أســهم (‪ )...‬يف حــال حياتــه ونقلهــا‬\n      ‫ألســمائهم وأخــذ األربــاح ملــدة ثــاث ســنوات والواجــب إرجاعهــا إلــى‬\n      ‫التركــة بكاملهــا‪ ،‬حيــث إن جميــع ممتلــكات الشــيخ (‪ - )...‬رحمــه‬\n      ‫اهلل ‪ -‬كانــت ضمــن مؤسســة (‪ )...‬للتجــارة والزراعــة بالســجل رقــم (‪)...‬‬\n      ‫وقــام مــن يديــر املــال حينهــا بإحالــة املمتلــكات إلــى شــركة (‪ )...‬التــي‬\n      ‫ال ميتلــك فيهــا (‪ )...‬ســوى ‪ %12‬وقــد قــام أبنــاء الشــيخ (‪ )...‬رحمــه اهلل ‪-‬‬\n      ‫بأخــذ توقيــع والدهــم علــى خطــاب تنــازل عــن جميــع الرصيــد الدائــن‬\n      ‫يف شــركة (‪ )...‬لالســتثمار والتطويــر العقــاري ‪ ،‬ويعتبــر هــذا اخلطــاب‬\n      ‫مبثابــة تنــازل عــن جميــع املمتلــكات التــي نقلــت مــن املؤسســة إلــى‬\n      ‫شــركة (‪ ،)...‬وهــذا يعنــي أن الشــيخ (‪ - )...‬رحمــه اهلل ‪ -‬قــام بتوزيــع‬\n      ‫مــا نســبته ‪ %88‬مــن مالــه وهــو املســجل يف شــركة (‪ )...‬بأســماء بقيــة‬\n\n\n‫‪291‬‬\n\f                                                                   ‫الشــركاء‪.‬‬\n‫‪ -3‬قيــام بعــض طالبــي الواليــة بصفتهــم وكالء عــن والدهــم بنقــل‬\n‫أمالكه يف مؤسســة (‪ )......‬للتجارة والزراعة (ســجل جتاري رقم(‪)).....‬‬\n‫والتــي تبلــغ قيمتهــا الدفتريــة ‪ 3.400.000.000‬ريــال (ثــاث مليــارات‬\n‫وأربعمائــة مليــون ريــال) مســتغلني صفتهــم أعضــاء يف مجلــس إدارتهــا‬\n‫وذلــك إلــى شــركة (‪ ).....‬اململوكــة باألغلبيــة لهــم وحرمــان إخوانهــم‬\n                                           ‫القصــر منهــا (أوالد موكلتــي(‪.‬‬\n‫‪ -4‬قيــام بعــض طالبــي الواليــة مســتغلني صفتهــم بأنهــم أعضــاء مجلــس‬\n‫إدارة مؤسســة (‪ )....‬للتجــارة والزراعــة القائمــة علــى إدارة أمالك وأعيان‬\n‫الشــيخ(‪ ،)....‬وذلــك بالتصــرف يف أســهمه املوجــودة يف احملفظــة رقــم‬\n‫يف البنــك (‪ )....‬وذلــك بنقلهــا إلــى محافــظ أخــرى باســم شــركة (‪).....‬‬\n‫وجــاء هــذا التصــرف بعــد إلغــاء وكاالتهــم مبوجــب أمــر احملكمــة‬\n‫‪ ،‬وبالتالــي فــإن ضمــان هــذا التصــرف هــو مســئوليتهم وهــو مــن حــق‬\n                       ‫القصــر فكيــف تتــم املطالبــة بــه واحلــال كذلــك ‪.‬‬\n‫خامس ـاً‪ -:‬ظهــور العــداوة بــن املذكوريــن أو بعضهــم وبــن موكلتــي‬\n                                     ‫وأوالدهــا وذلــك علــى النحــو التالــي‪-:‬‬\n‫‪-1‬قيــام املذكوريــن وخاصــة (‪ )....‬و(‪ )....‬بطــرد موكلتــي وأوالدهــا مــن‬\n‫قصرهــم يف نهايــة عــام ‪1428‬ه ـ وعــدم تســليمهم شــيء مــن أغراضهــم‬\n‫الشــخصية طيلــة هــذه الســنوات وعــدم قبولهــم الرجــوع إلــى بيتهــم‬\n‫ورفضهــم االســتجابة لنــداء العقــل واملنطــق بحســب تقريــر شــرطة ملقــام‬\n‫اإلمــارة وســلوكهم مختلــف الســبل لالمتنــاع مــن تنفيــذ مــا أمــرت‬\n‫بــه اجلهــات املســئولة مــن إعــادة موكلتــي وأوالدهــا إلــى بيتهــم‪ ،‬وإنــي‬\n‫هنــا أكتفــي مبــا جــاء يف خطــاب صاحــب الســمو امللكــي األميــر يف‬\n\n\n                                                                                  ‫‪292‬‬\n\f      ‫خطابــه رقــم ‪ 97782‬وتاريــخ ‪1432/7/19‬ه ـ واملؤكــد عليــه بخطــاب‬\n      ‫صاحــب الســمو امللكــي أميــر منطقــة الريــاض بالنيابــة برقــم ‪138356‬‬\n      ‫يف ‪1432/11/11‬ه ـ ونــص احلاجــة منــه مــا يلــي‪ :‬أوالً‪ :‬متكــن املــرأة‬\n      ‫املدعيــة وأوالدهــا مــن العــودة ملنزلهــم وأن يؤثــث لهــم ويعــاد علــى مــا‬\n      ‫كان عليــه ســابق ًا بــراءة للذمــة وإحقاق ـ ًا للعدالــة ثاني ـاً‪ :‬أن يعامــل‬\n      ‫املدعــى عليهمــا مبوجــب الئحــة اإلجــراءات اجلزائيــة لقــاء اعتدائهــم علــى‬\n      ‫منــزل إخوانهــم وســرقة األثــاث واجلــوازات وتغييــر أقفــال األبــواب وفصــل‬\n      ‫لذلــك أوراق مســتقلة‪ ،‬ومــع ذلــك فــإن موكلتــي مــا تــزال خــارج بيتهــا‪،‬‬\n      ‫وال يــزال أوالدهــا يف غرفــة مــن غــرف بيــت خالهــم رغــم صــدور التوجيــه‬\n      ‫الكــرمي ملقــام شــرطة منطقــة الريــاض منــذ مــا يقــارب العامــن لكــن‬\n      ‫(‪ ).........‬و(‪ ).........‬مياطــان مبختلــف الطــرق والوســائل لعــدم التنفيــذ‬\n      ‫‪ ،‬بــل إن األمــر قــد بلــغ باملذكوريــن مبلغــه حيــث قامــوا مبنــع القصــر‬\n      ‫أوالد موكلتــي مــن رؤيــة والدهــم أثنــاء مرضــه وأرفــق لفضيلتكــم‬\n      ‫ا عــن اعتــداء أحدهــم‬    ‫صــورة مــن محضــر احلالــة منع ـ ًا لإلطالــة فض ـ ً‬\n      ‫وهــو علــى أحــد إخوانــه وقــت كان قاصــر ًا وذلــك بالضــرب الــذي‬\n      ‫أدخــل الطفــل علــى إثــره إلــى املستشــفى وفق ـ ًا للتقريــر املرفــق ‪2‬ـ قيــام‬\n      ‫املذكوريــن أثنــاء فتــرة مــرض والدهــم بصــرف النفقــات مــن أمــوال‬\n      ‫الوالــد ألشــقائهم ومــن يرغبــون وحرمــان القصــر ( أوالد موكلتــي )‬\n      ‫مــن ذلــك حتــى اضطــرت موكلتــي للجــوء إلــى احملاكــم الشــرعية ولــم‬\n      ‫تســتطع احلصــول حتــى علــى عشــر مــا يصــرف مــن أمــوال والــده علــى‬\n      ‫ســباق الســيارات ‪ ،‬حيــث إنهــا لــم حتصــل إال علــى مائــة وخمســن‬\n      ‫ألــف ريــال ســنوي ًا ‪ ،‬بينمــا دعمــت شــركة (‪ ).........‬للســيارات بأحــد‬\n      ‫عشــر مليــون ريــال وفــق التقاريــر اإلعالميــة املنشــورة بتصريــح مديــر‬\n\n\n‫‪293‬‬\n\f‫الشــركة ‪ ،‬وقــد امتنــع عــن اإلنفــاق علــى أوالد موكلتــي القصــر ولــم‬\n‫يلتــزم باالتفــاق الــذي التــزم فيــه بــأن يدفــع مبلــغ شــهري قــدره ‪12.000‬‬\n‫ريــال إضافــة إلــى حتملــه رســوم املــدارس ‪ ،‬ولــم يقــم بدفــع أو ســداد أيــة‬\n‫مبالــغ إال بعــد أن تقدمنــا بالشــكوى لفضيلــة الشــيخ (‪ ).........‬مبوجــب‬\n‫خطابنــا رقــم ‪ 11/3/110‬املرفــق صــورة منــه والــذي همــش عليه فضيلته‬\n‫لــ(‪ ، ).........‬فلــو كان حريــص علــى مصالــح إخوانــه القصــر مــا امتنــع‬\n‫عــن أداء النفقــة لهــم وتعطيــل شــئونهم عــن طريــق االمتنــاع عــن تســديد‬\n‫مصاريــف املــدارس ‪ ،‬والشــاهد هنــا هــو عــدم أحقيــة يف الوصايــة علــى‬\n‫إخوانــه القصــر أوالد موكلتــي لعــدم حرصــه علــى مصاحلهــم ‪ -3 .‬قيــام‬\n‫املذكوريــن بالســعي الشــديد لتطليــق موكلتــي وهــي أم القصــر املــراد‬\n‫التوليــة عليهــم مــن زوجهــا ‪ ،‬ويكفــي داللــة لذلــك أن الشــاهد علــى‬\n‫الطــاق األول هــو ‪ ،‬ويكفــي أيض ـ ًا أن الشــيخ (‪ ).........‬طلــب حضــور‬\n‫أكثــر مــن مــرة بنــاء علــى دعــوى موكلتــي املقامــة يف ‪1429/1/12‬ه ـ‬\n‫ورفــض الــوكالء ذلــك ‪ ،‬ويف جلســة ‪1430/7/4‬ه ـ أفهــم الوكيــل بعدم‬\n‫طــاق موكلــه (‪ ).........‬ملوكلتــي أو تزوجــه بخامســة حتــى يحضــر إلــى‬\n‫مجلــس احلكــم‪ ،‬ويف ‪1430/7/10‬ه ـ أحضــر (‪ ).....‬إلــى القاضــي (‪).....‬‬\n‫يف محكمــة الضمــان واألنكحــة ومت إثبــات ســت طلقــات علــى لســانه‬\n‫وهــو الصــك املنقــوض واملصــادق علــى نقضــه مــن محكمــة التمييــز وهو‬\n‫هنــا مــن أكبــر أدلــة العــداوة بــن القصــر وبــن أكثــر أعضــاء مجلــس‬\n‫الوصايــة املعــن يف الصــك املعتــرض عليــه ‪ -4‬قيــام (‪ ).....‬و(‪ ).....‬مــع‬\n‫وكالء آخريــن باالحتيــال لالســتيالء علــى حصــة موكلتــي يف شــركة‬\n‫(‪ ).........‬وأوالده للتجــارة والصناعــة والزراعــة ( القابضــة حاليـ ًا ) والتــي‬\n‫تبلــغ أكثــر مــن ثمانــن مليــون ريــال وذلــك باســتخراج وكالــة للتنــازل‬\n\n\n                                                                                     ‫‪294‬‬\n\f      ‫عــن احلصــة ثــم قامــوا بنقــل تلــك احلصــة بالكامــل إلــى اســم والدهــم‬\n      ‫يف مظلمــة شــهد عليهــا اهلل تعالــى وصــدر حكــم نهائــي مصــدق مــن‬\n      ‫محكمــة االســتئناف بإقــرار هــذا التصــرف ويبقــى املوضــوع محــا ًال‬\n      ‫إلــى محكمــة اآلخــرة‪ ،‬وشــاهدنا هنــا درجــة العــداوة التــي حملهــا قلــب‬\n      ‫هذيــن املعينــن أوصيــاء علــى أوالد موكلتــي والتــي حملهــم علــى هــذا‬\n      ‫الصنيــع الــذي ميتنــع منــه أهــل املروءات ‪ ،‬لكن العداوة إذا اســتحكمت‬\n      ‫أنســت العاقــل عقلــه ‪ ،‬فكيــف يســوغ إقــرار هــؤالء أوصيــاء علــى أوالد‬\n      ‫موكلتــي مــع كل هــذه العــداوة مــع والدتهــم‪-5 .‬قيــام املذكوريــن‬\n      ‫(‪ ).........‬و(‪ ).........‬بتهديد موكلتي يف قضية أرض (‪ ).....‬املعروضة على‬\n      ‫فضيلتكــم برقــم (‪ ).....‬وتاريــخ ‪1429/1/12‬ه ـ وإجبارهــا علــى التنــازل‬\n      ‫عــن األرض والقضيــة منظــورة لــدى فضيلتكــم ‪ ،‬ومحــل الشــاهد هنــا‬\n      ‫بيــان درجــة العــداوة لتجريــد موكلتــي مــن كل حــق سادسـ ًا ‪ -:‬حصــول‬\n      ‫االعتــداء الظاهــر علــى أمــوال ابــن موكلتــي (‪ ).........‬حيــث إنــه بتاريــخ‬\n      ‫‪1433/5/17‬ه ـ اســتصدر (‪( ).........‬ابــن موكلتــي) بطاقــة أحــوال‬\n      ‫لبلوغــه الســن القانونيــة لذلــك ‪ ،‬ومبراجعتــه للبنــك وجــد أن هنــاك‬\n      ‫حســاب باســمه وأن املفــوض بالتوقيــع علــى هــذا احلســاب هــو (‪، ).........‬‬\n      ‫وبطلــب كشــف احلســاب وجــد أن إجمالــي اإليداعــات هــو مبلــغ وقــدره‬\n      ‫(‪ )44.863.674.69‬ريــال وأن املوجــود فعليـ ًا منهــا يف هــذا احلســاب هــو‬\n      ‫مبلــغ وقــدره ‪328.91‬ريــال فقــط ال غيــر ‪ ،‬واملوجــود باحلافظــة اخلاصــة‬\n      ‫باألســهم املربوطــة باحلســاب هــو مبلــغ وقــدره ‪ 19.642.370.26‬ريــال‬\n      ‫وذلــك بنقــص قــدره ‪ 25.221.304.43‬ريــال ‪ ،‬وقــد أقــام الدعــوى علــى‬\n      ‫بطلــب احملاســبة لكونــه املتصــرف باحلســاب واملقيــدة يف احملكمــة‬\n      ‫العامــة بالريــاض برقــم (‪ ).....‬وتاريــخ ‪1434/4/10‬ه ـ واحملالــة إلــى‬\n\n\n‫‪295‬‬\n\f‫فضيلــة الشــيخ (‪ ).........‬وجنــزم أن فضيلتكــم لــو طلــب مــن مؤسســة‬\n‫النقــد كشــف حلســابات القصــر لوجــد احلــال نفســه ‪ ،‬فهــل يســوغ‬\n‫املخاطــرة بأمــوال القصــر إلــى هــذا احلــد أم يعمــل باالحتيــاط والنصــح‬\n‫لهــم ســابع ًا ‪ -:‬عــدم ائتمــان طالبــي الوصايــة علــى القصــر‪ ،‬حيــث جعلــوا‬\n‫والدهــم يوقــع علــى إبــراء لهــم عــن كل مــا فعلــوه يف املاضــي أو احلاضــر‬\n‫أو املســتقبل عــن قصــد أو عــن غيــر قصــد فيمــا يتعلــق مبــال (‪ ).........‬أو‬\n‫مــال أحــد مــن أوالده القصــر (ومــن هــم أوالده القصــر إال أوالد موكلتــي‬\n‫اللذيــن يطلبــون الوصايــة عليهــم ؟ ) ثامن ـ ًا ‪ -:‬مخاطــرة املذكوريــن‬\n‫بأمــوال القصــر ومحاولتهــم بيــع كامــل نصيبهــم مــن إرثهــم الشــرعي‬\n‫مــن والدهــم علــى شــركة (‪ ).....‬القابضــة مببلــغ أقــل بكثيــر مــن ثمــن‬\n‫املثــل وقــدره ‪25.000.000‬ريــال (خمســة وعشــرون مليــون ريــال فقــط)‪،‬‬\n‫وقــد تقــدم أعضــاء مجلــس الوصايــة املذكــور واللذيــن مت تعيينهــم‬\n‫مبوجــب صــك الوصايــة الصــادر مــن فضيلتكــم بطلــب البيــع املذكــور‬\n‫مبوجــب املعاملــة املقيــدة يف مكتــب فضيلــة الشــيخ (‪ ).........‬القاضــي‬\n‫باحملكمــة العامــة بالريــاض برقــم ‪ 34303191‬وتاريــخ ‪1434/2/5‬ه ـ‬\n‫‪ ،‬وهــذا اإلجــراء فيــه أشــد الضــرر مبصلحــة القصــر ‪ ،‬لكــون الهــدف‬\n‫مــن هــذا البيــع هــو مــا عبــر عنــه محامــي مجلــس الوصايــة املذكــور‬\n‫بالتخلــص مــن واليــة احملكمــة علــى بيــع عقــارات القصــر ‪ ،‬وحيــث إن‬\n‫التخلــص مــن واليــة احملكمــة يخالــف مقصــود الشــارع احلكيــم بربطــه‬\n‫التصرفــات الناقلــة مللكيــة عقــارات القصــر باملوافقــة القضائيــة ‪ ،‬وإن‬\n‫تعيــن املذكوريــن أوصيــاء علــى القصــر يعنــي أن احملكمــة تقــر هــذا‬\n‫التصــرف بــل وتعطــي لــه الغطــاء القانونــي وكأنهــا تقــول لألوصيــاء‬\n‫وبــكل بســاطة إليكــم مــال القصــر لتتصرفــوا فيــه كمــا تشــاءون دون‬\n\n\n                                                                                    ‫‪296‬‬\n\f      ‫الرجــوع للمحكمــة ولكــم مطلــق احلريــة يف ذلــك وبنــاء علــى مــا تقــدم‬\n      ‫‪ ......‬نطلــب مــا يلــي‪ :‬أوالً‪ :‬الطلــب األصلــي التهميــش علــى صــك الواليــة‬\n      ‫الصــادر مــن فضيلتكــم بالرجــوع عنــه وإحالــة املعاملــة إلــى فضيلــة‬\n      ‫الشــيخ (‪ ).........‬خلــف الشــيخ (‪ ).....‬لســماع دعــوى موكلتــي بطلــب‬\n      ‫الواليــة وإجــراء الوجــه الشــرعي جتاههــا ثاني ـاً‪ -:‬الطلبــات االحتياطيــة‬\n      ‫‪ -1‬احلكــم بنــزع وصايــة املذكوريــن يف الوصيــة عــن القصــر أوالد‬\n                    ‫موكلتــي وتعيــن موكلتــي وليــة عليهــم حفظ ـ ًا حلقوقهــم‬\n      ‫‪ -2‬الكتابــة إلــى مؤسســة النقــد العربــي الســعودي لطلــب كشــف‬\n      ‫حلســابات القصــر وهــم (‪ ).....‬ســجل مدنــي (‪ ).....‬و(‪ ).....‬ســجل‬\n      ‫مدنــي (‪ ).....‬و(‪ ).....‬ســجل مدنــي (‪ ).....‬مــع تزويــدي بصــورة مــن تلــك‬\n      ‫الكشــوفات لبيــان مــا فيهــا مــن إهمــال وتقصيــر وتعــدي علــى أمــوال‬\n                             ‫القصــر شــبيهة مبــا حــل بأمــوال شــقيقهم (‪).........‬‬\n      ‫‪ -3‬ســحب أصــل صــك الوصايــة مــن املذكوريــن وإفهامهــم خطيـ ًا بدفتر‬\n      ‫الضبــط بعــدم التصــرف ســواء ببيــع أو رهــن أو نقــل ألمــاك القصــر‬\n                                                      ‫حتــى ينتهــي النظــر يف الدعــوى‬\n      ‫‪ -4‬حيــث إن (‪ )...‬بنــت (‪ )...‬قــد بلغــت مبلــغ النســاء ولرشــدها فــإن‬\n      ‫موكلتــي تطلــب إخــراج صــك رشــد مســتقل بهــا ومتكينهــا مــن الواليــة‬\n      ‫ا للنــزاع وحفظ ـ ًا حلقهــا هكــذا أجــاب‬       ‫علــى أموالهــا بنفســها تقلي ـ ً‬\n                               ‫وبعــرض ذلــك علــى املدعــى عليــه وكالــة أجــاب‪.‬‬\n      ‫‪ -1‬ســبق وأن أوصــى الشــيخ (‪ ).......‬يف حياتــه بأنــه يف حــال فقــده‬\n      ‫لألهليــة فيتولــى والياتــه مبــا فيهــم أوالده القصــر مجلس ـ ًا مــن ضمنهــم‬\n      ‫(‪ ).......‬و(‪ ).......‬واعترضــت علــى ذلــك املدعيــة وطعنــوا بهــم مــن خــال‬\n      ‫ذكــر أغلــب مــا ورد يف مذكــرة الــرد مــن طعــون وبعــد أنثبــت للقاضــي‬\n\n\n‫‪297‬‬\n\f‫عــدم صحــة ذلــك وثبــت لــه أهليتهــم للواليــة مــع بقيــة مــن عينهــم والدهــم‬\n‫صــدر بذلــك حكمـ ًا برقــم ‪ 3339658‬وتاريــخ ‪1433/1/22‬ه ـ ‪ ،‬وأويــد‬\n‫مــن محكمــة االســتئناف وبنــاء عليــه صــدر صــك شــرعي مــن مكتــب‬\n‫فضيلتكــم برقــم ‪ 33356475‬وتاريــخ ‪1433/7/26‬ه ـ بإقامــة كل‬\n‫مــن‪ ).......( :‬و(‪ ).......‬و(‪ ).......‬ابنــاء الشــيخ (‪ ،).......‬و(‪ ).......‬أوصيــاء‬\n‫علــى القصــر يرعــون شــؤونهم ومصاحلهــم كمــا أوصــى بذلــك والدهــم‬\n‫وحيــث أن هــذا الصــك الصــادر مــن فضيلتكــم ســاري املفعــول حتــى‬\n‫بعــد وفــاة الشــيخ (‪ ).........‬كمــا جــاء يف حاشــيتكم علــى خطــاب‬\n‫الشــيخ‪ ،).........( :‬القاضــي يف هــذه احملكمــة ‪ ،‬فــا وجــه للمطالبــة‬\n‫بإلغائــه ال شــرع ًا وال نظام ـ ًا ‪-2‬مــن الثابــت عنــد فقهــاء احلنابلــة ‪ ،‬وهــو‬\n‫أن وصـ ّـي األب مقــدم علــى األم يف‬        ‫املعمــول بــه يف محاكــم اململكــة َّ‬\n‫القصــر واإلشــراف عليهــم‪ ،‬قــال ابــن قدامــة ‪ « :‬ويتولــى األب‬       ‫ّ‬      ‫رعايــة‬\n‫مــال الصبــي واملجنــون ألنهــا واليــة علــى الصغيــر فقــدم فيهــا األب‬\n‫كواليــة النــكاح ثــم وصيــه بعــده ألنــه نائبــه فأشــبه وكيلــه يف احليــاة‬\n‫« الــكايف (‪ ، )251/8‬وقــال البهوتــي ‪ « :‬ثــم تثبــت الواليــة علــى صغيــر‬\n‫ومجنــون بعــد األب لوصيــه العــدل «‪ .‬كشــاف القنــاع (‪ )383/8‬لذلــك‬\n‫كلــه نأمــل مــن فضيلتكــم التكــرم بإمضــاء صــك الواليــة الصــادر‬\n‫مــن مكتــب فضيلتكــم برقــم ‪ 33356475‬وتاريــخ ‪1433/7/26‬ه ـ ‪،‬‬\n‫واحلكــم بــرد الدعــوى كونهــا تأتــي مخالفـ ًا ملــا عليــه الوصيــة وملــا قــرره‬\n‫فقــاء املذهــب ولكونــه صــدر حكــم ومصــدق مــن االســتئناف بأهليــة‬\n‫املجلــس الــذي أوصــى بــه الشــيخ (‪ ).........‬وعــدم ثبــوت الطعــن بعــدم‬\n‫أهليتهــم للواليــة هكــذا أجــاب وبعــرض ذلــك علــى املدعــي وكالــة‬\n‫أجــاب أطلــب مهلــة لذلــك ثــم يف يــوم الثالثــاء ‪1434/04/23‬ه ـ افتتحــت‬\n\n\n                                                                                         ‫‪298‬‬\n\f      ‫اجللســة الثالثــة الســاعة ‪ 01،15‬وفيهــا حضــر املدعــي وكالــة واملدعــى‬\n      ‫عليــه وكالــة وبســؤاله عــن جوابــه عمــا دفــع بــه املدعــى عليــه وكالــة‬\n      ‫يف اجللســة الســابقة أبــرز مذكــره مكونــة مــن صفحتــن ومتضمنــه مــا‬\n      ‫نصــه أوالً‪ :‬أن مــا جلــأ إليــه املدعــى عليهــم مــن التمســك باحلكــم املشــار‬\n      ‫إليــه واتخــاذه حجــة يف طلــب الوصايــة علــى القصــر هــو يف حقيقتــه حجــة‬\n      ‫عليهــم ال لهــم‪ ،‬حيــث تقــدم املنهــي (‪ ).....‬وكيــل عــن (‪ ).....‬يف الدعــوى‬\n      ‫الصــادر فيهــا احلكــم املذكــور للمحكمــة طالب ـ ًا مــا نصــه « وإقامــة‬\n      ‫مجلــس واليــة مبــا يحقــق مصلحــة املنهــى عنــه ومــن حتــت واليتــه مــن‬\n      ‫أوالده القصــر ويعتنــي بشــؤونه ويحفــظ أموالــه ويطالــب مبــا أخــذ منهــا‬\n      ‫« الصفحــة رقــم ( ‪ ) 2‬مــن الصــك املذكــور وقــد طلــب املدعــى عليهــم يف‬\n      ‫الدعــوى الصــادر فيهــا احلكــم املشــار إليــه تعيينهــم يف مجلــس الواليــة‬\n      ‫علــى والدهــم وتعينهــم أيض ـ ًا أوصيــاء علــى القصــر حســب الوصيــة‬\n      ‫وقــد مت ضبــط طلباتهــم املذكــورة يف الصفحــة رقــم ( ‪ ) 3‬مــن الصــك‬\n      ‫املشــار إليهــم ونصــه كمــا يلــي « إن موكلــي يطلبــون مــن فضيلتكــم‬\n      ‫إنفــاذ مــا ورد يف وصيــة الشــيخ (‪ ).........‬حفظــه اهلل واملوقعــة منــه بتاريــخ‬\n      ‫‪1428/4/28‬ه ـ وهــو بكامــل األهليــة (مرفــق‪ )1‬والتــي أشــهد عليهــا‬\n      ‫كل مــن (‪ ).......‬و(‪ ).......‬والتــي تضمنــت تعيينــه ألعضــاء مجلــس الواليــة‬\n      ‫عليــه عنــد وجــود عالمــات ضعــف يف ذاكرتــه وذلــك وفــق مــا جــاء يف‬\n      ‫الوصيــة أنهــم كل مــن‪ ).......( .3 ).......( .2 ).......( .1 .:‬و(‪( ).......‬إذا‬\n      ‫بلــغ راشــداً) وقــد نــص الشــيخ (‪ ).........‬أنــه علــى « املجلــس عنــد وجــود‬\n      ‫عالمــات الضعــف يف الذاكــرة واإلدارة والهــرم أن يحــل محلــي مباشــرة‬\n      ‫يف إدارة األعمــال واألمــوال واألوقــاف ويلغــي توقيعي وســلطتي الكاملة‬\n      ‫إذا بلغــت األصــوات أربعــة مــن أعضــاء املجلــس املذكوريــن» كمــا‬\n\n\n‫‪299‬‬\n\f‫نــص علــى أن « املجلــس املخــول بتنفيــذ هــذه الوصيــة هــم األوصيــاء علــى‬\n‫أوالدي القصــر ذكــور ًا وإناثـاً‪ ...‬وتكــون واليــة التزويــج لالبــن « ومرفــق‬\n‫صــورة الوصيــة ‪ .......‬إلــخ «‪ ،‬إال أن احلكــم يف الدعــوى املذكــورة قــد‬\n‫جــاء نصــه يف الصفحــة رقــم (‪ )59‬كمــا يلــي « ‪:‬ولــذ فقــد قــررت ‪ :‬أو ًال‬\n‫‪ :‬صرفــت النظــر عــن أي مطالبــة متــت يف أثنــاء املرافعــات ســوى إقامــة‬\n‫مجلــس الوصايــة وأفهمــت مــن لــه دعــوى أن يتقــدم بهــا بصفــة مســتقلة ‪.‬‬\n‫ثانيـ ًا ‪ :‬أقمــت كال مــن (‪ )...‬و(‪ )...‬و(‪ )...‬ابنــاء (‪ )...‬أوليــاء مجتمعــن علــى‬\n‫(‪ )...‬إلــخ « وبنــاء عليــه فــإن طلــب املذكوريــن قــد فصــل فيــه بصــرف‬\n‫النظــر وصــدق ذلــك مــن محكمــة االســتئناف ســابق ًا ثاني ـ ًا ‪ :‬إن ممــا‬\n‫يبــن عــدم صالحيــة املذكوريــن أن (‪ )...‬و(‪ )...‬ولــدي (‪ )...‬املطلــوب‬\n‫تنصيبهــم أوصيــاء علــى القصــر مقــام عليهمــا دعــوى باحلــق العــام يف‬\n‫ـزاء ملــا فعــا يف حــق موكلتــي وأوالدهــا‬  ‫احملكمــة اجلزئيــة بالريــاض جـ ً‬\n‫القصــر ‪ ،‬ونأمــل مــن فضيلتكــم التكــرم بالكتابــة إلــى احملكمــة‬\n‫اجلزائيــة بالريــاض لطلــب نســخة مــن صحيفــة الدعــوى املقامــة ضدهــم‬\n‫واملقيــدة برقــم ‪ 33933573‬وتاريــخ ‪1433/5/17‬ه ـ ثالثـ ًا ‪ -:‬نؤكد على‬\n‫متســكنا مبــا أبدينــاه يف مذكرتنــا املقدمــة يف اجللســة الســابقة بتاريــخ‬\n‫‪1434/4/16‬ه ـ مــن ضــرورة الكتابــة إلــى مؤسســة النقــد العربــي‬\n‫الســعودي لطلــب كشــف حلســابات القصــر وهــم (‪ )...‬و(‪ )...‬و(‪ )...‬مــع‬\n‫تزويــدي بصــورة مــن تلــك الكشــوفات لبيــان مــا فيهــا مــن إهمــال‬\n‫وتقصيــر وتعــدي علــى أمــوال القصــر شــبيهة مبــا حــل بأمــوال شــقيقهم‬\n‫(‪ )....‬وبنــاء علــى مــا تقــدم نأمــل التكــرم بالرجــوع عــن مــا حكمتــم‬\n‫بــه ســابق ًا مــن تعيــن املذكوريــن أوصيــاء علــى أوالد موكلتــي القصــر‬\n‫وتعيــن موكلتــي ( والدتهــم) وصيــة علــى أوالدهــا القصــر (‪ )....‬و(‪)...‬‬\n\n\n                                                                                       ‫‪300‬‬\n\f      ‫و(‪ )...‬حفظـ ًا لشــئونهم هكــذا أجــاب وبعــرض ذلــك علــى املدعــى عليــه‬\n                                                                     ‫وكالــة أجــاب‪:‬‬\n      ‫‪ -1‬ادعــاء وكيــل املدعيــة فيمــا ورد سادسـ ًا مــن املذكــرة مــن حصــول‬\n      ‫اعتــداء علــى أمــوال (‪ )...‬مــن قبــل أخيــه (‪ )...‬بســحب خمــس وعشــرين‬\n      ‫مليــون ريــال مــن حســابه ‪ ،‬وهــذا اتهــام باطــل ال أســاس لــه مــن الصحــة‬\n                                                                   ‫‪ ،‬وذلــك ملــا يلــي ‪:‬‬\n      ‫‪-2‬أن مجلــس الواليــة علــى القصــر كان حريص ـ ًا علــى أمــوال القصــر‬\n      ‫ورعايتهــا وتنميتهــا ‪ ،‬حيــث بلــغ إيــرادات االســتثمارات ووقــف الذريــة‬\n      ‫ألمــوال األخ (‪ )....‬مــا قيمتــه (‪ )41.769.686‬ريــا ًال (واحــد وأربعــون‬\n      ‫مليون وســبعمائة وتســع وســتون ألف وســتمائة وســت وثمانون رياالً)حتى‬\n      ‫تاريــخ ‪1433/5/9‬ه ـ وفقـ ًا للتقريــر املرفــق مــن مكتــب (‪ )....‬للمحاســبة‬\n      ‫‪ ،‬وهــذا التقريــر يدحــض االتهــام املوجــه ملجلــس الواليــة (مرفــق‪- )1‬‬\n      ‫يوضــح كشــف احلســاب اخلــاص بــاألخ (‪ )...‬يف الفتــرة مــن ‪1433/2/7‬‬\n      ‫ه ـ وحتــى تاريــخ ‪1433/6/18‬ه ـ وتقريــر احملاســب القانونــي عــدم وجــود‬\n      ‫أي عمليــة ســحب املبلــغ املذكــور يف مذكــرة وكيــل املدعيــة محــل‬\n                                                                                     ‫الــرد‬\n      ‫‪ -‬توضــح قائمــة حركــة االســتثمارات لــأخ (‪ ).....‬بأنــه مت إيــداع مبلــغ‬\n      ‫( ‪)21.186.148‬ريــا ًال يف صنــدوق (‪ )....‬العقــاري مبصــرف (‪ ).....‬الــذي‬\n      ‫يحقــق عائــد ًا ســنوي ًا بنســبة ‪ %9‬حســب تقريــر احملاســب القانونــي (‬\n      ‫مرفــق‪ )2‬وهــو املبلــغ الــذي يظــن وكيــل املدعيــة بأنــه مت ســحبه مــن‬\n                                ‫رصيــد األخ (‪ ،)......‬والبقيــة يف صناديــق أخــرى‪.‬‬\n      ‫‪-1‬أن األخ (‪ ).....‬وصــل ســن البلــوغ بتاريــخ ‪1433/5/16‬ه ـ ‪ ،‬وبتاريــخ‬\n      ‫‪1433/5/17‬ه ـ أصــدر بطاقــة أحوالــه ‪ ،‬ثــم قــام هــو بنفســه بالتصــرف‬\n\n\n‫‪301‬‬\n\f                   ‫يف حســابه يؤكــد ذلــك صــورة مــن احلســاب املرفــق (‪)3‬‬\n‫‪ -2‬ادعــاء وكيــل املدعيــة بــأن األخ (‪ ).....‬امتنــع عــن تســديد رســوم‬\n‫املــدارس إلخوانــه القصــر ‪ ،‬وهــذا محــض افتــراء ‪ ،‬فقــد بــادر مجلــس‬\n‫للقصــر ‪ ،‬يوضــح ذلــك‬ ‫ّ‬     ‫الواليــة علــى القصــر يف تســديد رســوم املــدارس‬\n                  ‫كشــف احلســاب وســند قبــض مبلــغ الرســوم ‪( .‬مرفــق‪)4‬‬\n‫‪-3‬ومــا عــدا ذلــك فــإن جميــع مــا ذكــره وكيــل املدعيــة يف مذكرتــه‬\n‫مــن ادعــاءات وتهمــة وجــود عــداوة بــن أعضــاء مجلــس الواليــة والقصــر‬\n‫ســبق وأن مت الترافــع فيهــا لــدى فضيلــة القاضــي بهــذه احملكمــة الشــيخ‬\n‫(‪ )......‬يف دعــوى الواليــة علــى الشــيخ (‪ )......‬والطعــن بأهليتــه عنــد‬\n‫كتابــة الوصيــة ‪ ،‬وقــد حكــم فضيلتــه بصــرف النظــر عنهــا ‪ ،‬وأثبــت‬\n‫أن جميــع تصرفــات الشــيخ (‪ ).....‬ووصيتــه صحيحــة نافــذة وصــدرت‬\n‫منــه وهــو يف حالــة معتبــرة شــرع ًا ‪ ،‬وعليــه صــدر صــك شــرعي برقــم‬\n‫‪ 3339658‬وتاريــخ ‪1433/01/22‬ه ـ بتعيــن مجلــس الواليــة علــى الشــيخ‬\n‫(‪ ).....‬مــن ضمنهــم أبنــاؤه (‪ )...‬و(‪ )...‬وعــدم النظــر يف الطعــون ضدهمــا‬\n‫بعــد أن ثبــت لفضيلتــه أهليتهمــا للواليــة و ُأ ّيــد احلكــم مــن محكمــة‬\n‫االســتئناف ‪4‬ـ يظهــر لفضيلتكــم مــن خــال ثنايــا مذكــرة وكيــل‬\n‫ـس باطلــة ‪ ،‬وطعـ ٍـن ألحــكام‬        ‫املدعيــة أنهــا كيديــة وقائم ـ ٌة علــى أسـ ٍ‬\n‫ـف ألحــكام أخــرى‬       ‫قضائيــة قطعيــة كمــا ورد يف املــادة الثانيــة‪ ،‬ووصـ ٍ‬\n‫بأنهــا أحــكام ظاملــة كمــا ورد يف الفقــرة الرابعــة مــن املــادة اخلامســة‬\n‫القصــر كيفمــا يشــاء وذلــك مبــا‬ ‫ّ‬      ‫ـام للمجلــس بالتصــرف بأمــوال‬ ‫‪ ،‬واتهـ ٌ‬\n‫قــام بــه فضيلــة القاضــي يف هــذه احملكمــة الشــيخ (‪ ).....‬مــن بيــع نصيــب‬\n‫القصــر مــن تركــة والدهــم علــى شــركة (‪ ،)......‬مــع أن هــذا البيــع لــم‬\n‫يتــم إال بعــد االســتئناس بأهــل اخلبــرة وتأكيدهــم بــأن هــذا البيــع يحقــق‬\n\n\n                                                                                        ‫‪302‬‬\n\f      ‫الغبطــة واملصلحــة للقصــر‪ ،‬خاصــة وأنــه ســبقهم مبثــل هــذا البيــع بنفــس‬\n                   ‫املبلــغ ثــاث وعشــرون مــن الورثــة ‪ ،‬فأيــن املخاطــرة املزعومــة ؟‬\n      ‫وهــذا يــدل علــى أن الهــدف مــن ذلــك كلــه تشــتيت القضيــة وإطالــة‬\n      ‫أمدهــا ‪ ،‬وإشــغال القضــاة‪ ،‬وتعطيــل تنفيــذ األحــكام القضائيــة وهــذا‬\n      ‫وبعــد‬    ‫ـلك خاطــئ ومنزلــق خطيــر يظهــر معــه حنكــة الشــيخ (‪ُ ).....‬‬     ‫مسـ ٌ‬\n      ‫القصــر‬\n            ‫ّ‬       ‫نظــره ‪-‬رحمــه اهلل ‪ -‬يف الوصيــة مــن إقامــة مجلــس الواليــة علــى‬\n      ‫مــن أبنائــه‪ .‬يتضــح ممــا ســبق ومــن خــال تقريــر احملاســب القانونــي أن‬\n      ‫القصــر‬ ‫ّ‬      ‫القصــر كان شــديد احلــرص علــى أمــوال‬ ‫ّ‬     ‫مجلــس الواليــة علــى‬\n      ‫وتنميتهــا ورعايتهــا واحملافظــة عليهــا واســتثمارها بالطــرق الشــرعية‬\n      ‫كمحفظــة (‪ )......‬لالســتثمار واملشــاركة لــه يف صنــدوق (‪ ).....‬العقــاري‬\n      ‫بعائــد ســنوي قــدره ‪ %9‬وغيرهــا مــن الصناديــق االســتثمارية إال أن األخ‬\n      ‫(‪ )....‬وحلداثــة سـ ّنه وقلــة خبرتــه لــم يكــن علــى علــم بطــرق التعامــل مــع‬\n      ‫البنــوك والصناديــق االســتثمارية وآليــة االســتفادة منهــا والتعــرف علــى‬\n      ‫معلوماتهــا ‪ ،‬حيــث أن مجلــس الواليــة ومبجــرد علمــه بإصــدار (‪).....‬‬\n      ‫لبطاقــة أحوالــه املدنيــة التــي تثبــت بلوغــه ســن اخلامســة عشــر عام ـ ًا‬\n      ‫وقيامــه مبراجعــة البنــوك لتولــي إدارة حســاباته قــام باالتصــال بــه وطلــب‬\n      ‫االجتمــاع معــه لتســليمه امليزانيــة اخلاصــة به إال أنه رفــض احلضور وطلب‬\n      ‫ـاء علــى طلبــه‬    ‫إرســالها عــن طريــق البريــد االلكترونــي وأرســلت لــه بنـ ً‬\n      ‫(مرفــق‪ )5‬وهــذا يدحــض ادعاءهــم أمــام فضيلتكــم بــأن مجلــس الواليــة‬\n      ‫اختلــس خمــس وعشــرين مليــون ريــال وهــو نتــاج قلــة خبرتهــم وعــدم‬\n      ‫معرفتهــم بتحليــل ودراســة التقاريــر املاليــة كل ذلــك يؤكــد أن الشــيخ‬\n      ‫القصــر ‪ -‬رحمــه اهلل ‪ -‬كان حريص ـ ًا علــى حفــظ أمــوال‬          ‫ّ‬      ‫(‪ )....‬والــد‬\n      ‫القصــر وحقوقهــم مــن خــال تعيــن املؤهلــن والقادريــن واألمنــاء علــى‬\n\n\n‫‪303‬‬\n\f‫أبنائــه القصــر كمــا أن تصــرف األخ (‪ ).....‬وعــدم معرفتــه بــإدارة أموالــه‬\n‫واتهــام أخيــه باختالســه مبلــغ خمــس وعشــرين مليــون ريــال مــن حســابه‬\n‫مــع حتقــق وجــوده لــدى مصــرف (‪ ).....‬ويف امليزانيــات والتقاريــر املســلمة‬\n‫مؤكـ ٌـد علــى حاجتــه بــأن يتولــى‬\n                                  ‫ّ‬      ‫القصــر‬\n                                             ‫ّ‬     ‫لــه مــن مجلــس الواليــة علــى‬\n‫مجلــس الواليــة علــى القصــر االســتمرار يف الواليــة عليــه حتــى يكتمــل‬\n‫ميكنــه مــن حمايــة حقوقــه وأموالــه وخشــية مــن أن يســتغل‬   ‫رشــده والــذي ّ‬\n‫ا بقولــه تعالــى ‪ « :‬وابتلــوا اليتامــى حتــى إذا‬\n                                                  ‫مــن ضعــاف النفــوس ‪ ،‬عمـ ً‬\n‫بلغــو النــكاح فــإن آنســتم منهــم رشــد ًا فادفعــوا إليهــم أموالهــم « ممــا‬\n‫ســبق يتضــح لفضيلتكــم أن هــدف املدعيــة مــن هــذه الدعــوى تعطيــل‬\n‫أعمــال مجلــس الواليــة علــى القصــر وهــذا بــا شــك يضــر بالقصــر مــن‬\n‫ناحيــة رعايــة مصاحلهــم وكذلــك مــن ناحيــة اســتثمار وتنميــة أموالهــم‬\n‫التــي تبلــغ مئــات املاليــن حيــث كان والدهــم رحمــه اهلل يعلــم حجــم‬\n‫ثروتهــم واحلاجــة خلبــراء وأمنــاء عليهــم كمــا حددهــم بوصيتــه‪ ،‬وهــذا‬\n‫يثبــت لفضيلتكــم أن دعــوى املدعــي بالوكالــة مخالــف ملــا هــو مقــرر‬\n‫عنــد فقــاء املذهــب ومــا هــو معمــول بــه يف احملاكــم مــن أن وصــي‬\n‫األب مقــدم علــى األم يف الواليــة‪ ،‬كمــا أن مضمــون هــذه الدعــوى مــن‬\n‫الطعــون بأعضــاء مجلــس الواليــة علــى القصــر ســبق وأن ُحكــم فيــه‬\n‫بأحــكام قضائيــة قطعيــة ســبق اإلشــارة إليهــا لــكل مــا تقــدم أطلــب‬\n‫مــن فضيلتكــم احلكــم بإمضــاء الصــك الواليــة الصــادر مــن مكتــب‬\n‫فضيلتكــم برقــم ‪ 33356475‬وتاريــخ ‪1433/7/26‬ه ـ ‪ ،‬واحلكــم بــرد‬\n‫الدعــوى واســتمرار املجلــس وصي ـ ًا علــى القاصــر (‪ )...‬هكــذا أجــاب‬\n‫وبطلــب إثبــات مــا ادعــاه املدعــى عليــه وكالــة مــن أن املبلــغ الــذي أودع‬\n‫يف حســاب ابــن املدعيــة (‪ )....‬قــد جــرى إيداعه لدى شــركة (‪ )....‬التابعة‬\n\n\n                                                                                      ‫‪304‬‬\n\f      ‫ملصــرف (‪ )...‬أبــرز ورقــه مــن أوراق ومطبوعــات (‪ )....‬املاليــة وموجه لـ(‪)...‬‬\n      ‫ومتضمنــه اإلفــادة بوجــود اســتثمار لــ(‪ )...‬مببلغ وقــدره ‪ 20898000‬ريال‬\n      ‫وعائــد ســنويا قــدره ‪ %6‬وبعــرض ذلــك علــى املدعي وكالة أجاب أطلب‬\n      ‫مهلــة للتأكــد مــن اخلطــاب الــذي أبــرزه املدعــى عليــه وكالــة هكــذا‬\n      ‫أجــاب ثــم يف يــوم األحــد املوافق‪1434/05/05‬ه ـ افتتحــت اجللســة‬\n      ‫الرابعــة الســاعة الواحــدة والربــع وفيهــا حضــر املدعــي وكالــة واملدعــى‬\n      ‫عليــه وكالــة وبســؤال املدعــي وكالــة عمــا اســتمهل مــن أجلــه أجــاب‬\n      ‫لقــد راجعــت مصــرف (‪ )....‬وطلبــت منــه بيــان باحلــواالت التــي متــت علــى‬\n      ‫حســاب (‪ )...‬فطلبــوا منــي وقــت كــون احلــواالت متــت علــى مبالــغ صغيــرة‬\n      ‫هكــذا أجــاب وجــرى ســؤال املدعــي وكالــة هلمــا ذكــره املدعــى عليــه‬\n      ‫وكالــة مــن وجــود اســتثمار لــ(‪ ).....‬يف شــركة (‪ ).....‬صحيــح أجــاب نعــم‬\n      ‫لــه مبلــغ مســتثمر يف شــركة (‪ )....‬بنفــس املبلــغ الــذي ذكــره املدعــى‬\n      ‫عليــه وكالــة لكــن ليــس مســحوب ًا مــن حســاب (‪ ).....‬هكــذا أجــاب‬\n      ‫وبعــرض ذلــك علــى املدعــى عليــه وكالــة أجــاب مــا ذكــره املدعــي‬\n      ‫وكالــة مــن اتهــام موكلــي عضــو مجلــس الوصايــة باالســتيالء علــى‬\n      ‫أمــوال (‪ )....‬فقــد ثبــت بجــواب وكيــل املدعيــة بأنــه موجــود يف حســاب‬\n      ‫االســتثمار اخلــاص بــ(‪ )....‬يف صنــدوق (‪ ).....‬العقــاري وهــذا يؤكــد أن‬\n      ‫موكلــي وأعضــاء مجلــس الوصايــة ومحافظــن علــى أمــوال القصــر‬\n      ‫ويســتثمرونها فيمــا يحقــق الصالــح لهــم حتقيــق الوصيــة والدهــم رحمــه‬\n      ‫اهلل كما يؤكد أن (‪ ).....‬ووالدته املدعية ليس لديهم اخلبرة الكافية‬\n      ‫لقــراءة التقاريــر املاليــة اخلاصة باالســتثمارات واحلســابات وإدارة األموال‬\n      ‫التــي ورثوهــا هكــذا أجــاب وأبــرز املدعــى عليــه وكالــة ورقــة أصــل‬\n      ‫صــادرة مــن (‪ )....‬املاليــة ومؤرخــة يف ‪2012/7/31‬م ومتضمنــه أن لــ(‪)...‬‬\n\n\n‫‪305‬‬\n\f‫اســتثمار لديهــا مبلــغ وقــدره ‪20898000‬ريــال وأنهــا حققــت عائــدا قــدره‬\n‫‪ %6.0‬للفتــرة مــن ‪2012/2/1‬م إلــى ‪2012/7/31‬م ومذيلــة بتوقيــع‬\n‫العضــو املنتــدب صنــدوق (‪ )....‬للدخــل العقــاري وعضــو مجلــس اإلدارة‬\n‫واخلتــم الرســمي وبعــرض ذلــك علــى املدعــي وكالــة أجــاب إن املبلــغ‬\n‫املــودع يف صنــدوق (‪ )....‬هــو ‪20898000‬ريــال واملبلــغ الــذي أخــذ مــن‬\n‫حســاب ابــن موكلتــي هــو قريــب خمســة وعشــرون مليــون ريــال وأوخــذ‬\n‫علــى دفعــات صغيــرة بينمــا مــا أودع البــن موكلتــي علــى دفعتــن كل‬\n‫دفعــة قرابــة عشــرة مليــون ريــال هكــذا أجــاب وعنــد وصــول الدعــوى‬\n‫عنــد هــذا احلــد رفعــت اجللســة الســاعة ‪ 01،45‬للتأمــل والنطــق باحلكــم‬\n‫ثــم يف يــوم الســبت ‪1434/05/25‬ه ـ افتتحــت اجللســة اخلامســة الســاعة‬\n‫‪ 01،40‬وفيهــا حضــر املدعــي (‪ )...‬ســعودي اجلنســية مبوجــب الهويــة‬\n‫الوطنيــة برقــم (‪ )...‬بصفتــه وكيــا عــن (‪ )...‬ســعودي اجلنســية مبوجــب‬\n‫الهويــة الوطنيــة رقــم (‪ )...‬الوكيــل عــن (‪ )...‬حســب الوكالــة الصــادرة‬\n‫مــن كتابــة العــدل الثانيــة شــمال محافظــة جــدة برقــم ‪ 60519‬وتاريــخ‬\n‫‪1430/6/22‬ه واملخــول لــه فيهــا حــق املطالبــة واملرافعــة واملدافعة وإقامة‬\n‫الدعــاوى وســماع الدعــاوى والــرد عليهــا وطلــب اليمــن واملدعــى عليــه‬\n‫وكالــة وقــد جــرى اطالعــي علــى احلكــم الصــادر مــن ســلفي فضيلــة‬\n‫الشــيخ (‪ )......‬رقــم ‪ 3339658‬وتاريــخ ‪1433/1/22‬ه بثبــوت وصيــة‬\n‫(‪ )...‬والــد املدعــن واملدعــى عليهــم وهــو يف حالــة معتبــرة شــرع ًا وقــد‬\n‫اكتســب احلكــم القطعيــة بتصديــق محكمــة االســتئناف مبوجــب‬\n‫قرارهــم ‪ 33332198‬وتاريــخ ‪1433/7/8‬ه ـ وحيــث أن مــن ضمــن‬\n‫الوصيــة إقامــة املدعــى عليهــم أوصيــاء علــى القصــر مــن أوالده كمــا هــو‬\n‫منصــوص يف وصيــة مــورث املدعــن واملدعــى عليهــم يف الصحيفــة رقــم‬\n\n\n                                                                                  ‫‪306‬‬\n\f      ‫‪ 6‬مــن صــك احلكــم وملــا أن وصــي األب مقــدم علــى غيــره كمــا نــص‬\n      ‫علــى ذلــك فقهــاء احلنابلــة (ينظــر كشــاف القنــاع للبهوتــي (‪)383/8‬‬\n      ‫والــكايف البــن قدامــه ( ‪ )251/3‬وملــا أن مــا قدمــه املدعــي وكالــة مــن‬\n      ‫قــدح يف مجلــس الوصايــة ال يرقــى إلــى عــزل أوصيــاء األب كمــا أن‬\n      ‫الصــك الصــادر مــن ســلفي قــد تطــرق فيــه املدعــون مبثــل هــذه األمــور‬\n      ‫ومت صــرف النظــر عنهــا وملــا أن مــورث القصــر مشــهور بالتجــارة وأن‬\n      ‫مــا ورثــه القصــر مــن أمــوال كثيــرة حتتــاج إلــى مجلــس وصايــة يقــوم‬\n      ‫بأعبائهــا ممــا قــد ال تســتطيع معــه املدعيــة القيــام بــه لــذا فقــد رددت‬\n      ‫دعــوى املدعــي بإلغــاء وصايــة املدعــى عليهــم علــى القصــر مــن أوالد (‪)...‬‬\n      ‫لتقــدمي وصــي األب علــى غيــره ولتحقــق املصلحــة يف إبقــاء أوصيــاء األب‬\n      ‫أوصيــاء علــى القصــر وبــه حكمــت وبعــرض احلكــم علــى املدعــي قــرر‬\n      ‫عــدم القناعــة وطلــب رفعــه حملكمــة االســتئناف فأفهمتــه باحلضــور غدا‬\n      ‫الســتالم نســخة احلكــم واالعتــراض عليهــا خــال مــدة أقصاهــا ثالثــون‬\n      ‫يومـ ًا مــن تاريخــه وإن لــم يعترضــوا فيســقط حقهــم يف االعتــراض وقــرر‬\n      ‫املدعــى عليــه وكالــة القناعــة واختتمــت اجللســة الســاعة ‪ 02،00‬وعليــه‬\n      ‫جــرى التوقيــع وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                            ‫وصحبــه وســلم حــرر يف ‪1434/5/25‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الثانيــة‬\n      ‫املختصــة بنظــر قضايــا األحــوال الشــخصية واإلنهــاءات مبحكمــة‬\n      ‫االســتئناف علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة العامــة‬\n      ‫برقــم (‪ ).........‬وتاريــخ ‪1434/7/16‬ه املرفــق بهــا الصــك الصــادر مــن‬\n      ‫فضيلــة القاضــي باحملكمــة الشــيخ‪ ).........( /‬املســجل برقــم (‪).........‬‬\n      ‫وتاريــخ ‪1434/5/27‬ه ـ اخلــاص بدعــوى (‪ ).........‬ضــد (‪ ).........‬بعــض‬\n\n\n‫‪307‬‬\n\f‫ورثــة (‪ ).........‬يف قضيــة إلغــاء واليــة علــى القصــر وقــد تضمــن الصــك‬\n‫حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه‪ .‬وبدراســة الصــك وصــورة‬\n‫ضبطــه والالئحــة االعتراضيــة وأوراق املعاملــة تقــرر الدائــرة املصادقــة‬\n‫علــى احلكــم ‪.‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد و علــى آلــه‬\n                                                            ‫وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                 ‫‪308‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"8772d0b1-3c0f-5928-9c22-98c49da1913e","source_page_start":285,"source_page_end":308,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"3ef4e3138015135a395198cff715eee03f11a8a680a22acbeb53e04b78cc5902","normalized_text_hash":"39d6e9641752ed0f89ed12e88a9d80fee6f4539d5e585c129fc14d3a03add5d7","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v4-p285-34223712"},{"id":"381596aa-51d1-5eb6-bbf3-eacccae14927","document_type":"judgment","category":"judicial","subcategory":"general","title":"والية -إلغاء والية اجلد ألب وجعلها للجدة ألم -إحالة الطرفن إلى قسم الصلح وردت بعدم اختصاصهم -البينة بشهادة الشهود العدول -كبر سن الولي وسوء حالته الصحية -احلكم بنقل صالحية الوالية للمدعية ورفعها عن اجلد وإقامتها وليه على","document_number":"34193719","case_number":"92430313","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بجدة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/28","year":"1434","subject":"والية -إلغاء والية اجلد ألب وجعلها للجدة ألم -إحالة الطرفن إلى قسم الصلح وردت بعدم اختصاصهم -البينة بشهادة الشهود العدول -كبر سن الولي وسوء حالته الصحية -احلكم بنقل صالحية الوالية للمدعية ورفعها عن اجلد وإقامتها وليه على","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/4/28 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪34193719 :‬‬\n                         ‫َر ْق ُم الدعوى‪92430313 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 34245184‬تاريخه‪1434/6/19:‬هـ‬\n\n\n      ‫واليــة ‪ -‬إلغــاء واليــة اجلــد ألب وجعلهــا للجــدة ألم ‪ -‬إحالــة الطرفــن‬\n      ‫إلــى قســم الصلــح وردت بعــدم اختصاصهــم ‪ -‬البينــة بشــهادة الشــهود‬\n      ‫العــدول ‪ -‬كبــر ســن الولــي وســوء حالتــه الصحيــة ‪ -‬احلكــم بنقــل‬\n      ‫صالحيــة الواليــة للمدعيــة ورفعهــا عــن اجلــد وإقامتهــا وليــه علــى‬\n                                                                        ‫القصــر‪.‬‬\n\n\n\n\n                 ‫‪ .1‬قول تعالى (وال تقربوا مال اليتيم إال بالتي هي أحسن)‪.‬‬\n      ‫‪ .2‬قــال يف كشــاف القنــاع ‪( 443/3‬وال يجــوز لوليهمــا أي الصغيــر‬\n           ‫واملجنــون أن يتصــرف يف مالهمــا إال علــى وجــه احلــظ لهمــا)‪.‬‬\n\n\n\n\n      ‫ادعــت جــدة الم دعــوى تطالــب بإلغــاء واليــة اجلــد ألب علــى القصــر مــن‬\n      ‫أوالد ابنتهــا وجعلهــا لهــا وذكــرت أن املدعــى عليــه كبيــر يف الســن‬\n      ‫وال يســتطيع القيــام بأعبــاء الواليــة وأنــه أصــدر وكالــة إلبنــه الــذي هــو‬\n      ‫عــم األوالد للقيــام بشــؤون القصــر وأن املدعــى عليــه ووكيلــه لــم يقومــا‬\n      ‫بــأي شــيء جتــاه القاصريــن ‪ -‬صــادق املدعــى عليــه علــى الواليــة وأنــه‬\n      ‫لــم يقــم بشــيء جتــاه القاصريــن وادعــى أن ذلــك كان بســبب املدعيــة‬\n      ‫ألنهــا منعتــه مــن مشــاهدة القصــر ملــدة ســنتني ورفــض نــزع الواليــة منــه‬\n\n‫‪309‬‬\n\f‫‪ -‬حاولــت احملكمــة اإلصــاح بــن الطرفــن فلــم يصطلحــا وقــررت‬\n‫احملكمــة إحالــة الطرفــن لقســم الصلــح يف هــذه احملكمــة بــا جــدوى‬\n‫ثــم حضــرت املدعيــة ووكيــل املدعــى عليــه وذكــر وكيــل املدعــى عليــه‬\n‫أنــه يرقــد باملستشــفى للعــاج وأحضــرت املدعيــة معهــا شــاهدين شــهد ًا‬\n‫بأنهــا ذات أمانــة وكفــاءة وديانــة واقتــدار وجرى تعديل الشــاهدين وبناء‬\n‫عليــه ونظــر ًا لكبــر ســن املدعــى عليــه وســوء حالتــه الصحيــة وإلقــراره‬\n‫بأنــه لــم يعمــل شــيء جتــاه القاصريــن وألن املدعيــة جــدة للقصــر مــن‬\n‫جهــة األم لــذا ثبــت لــدى احملكمــة صالحيــة املدعيــة ألن تكــون وليــة‬\n‫علــى القصــر وقــررت نقــل الواليــة لهــا وأمرتهــا بالقيــام بشــؤون القصــر‬\n‫يف كل مــا يخصهــم‪ ،‬قــرر املدعــى عليــه عــدم القناعــة‪ ،‬صــدق احلكــم‬\n                                                  ‫مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد فلــدي‬\n‫أنــا (‪ ).....‬القاضــي يف احملكمــة العامــة بجــدة وبنــاء علــى املعاملــة‬\n‫احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة بجــدة املســاعد وتاريــخ‬\n‫‪1432/04/08‬ه ـ املقيــدة باحملكمــة وتاريــخ ‪1432/04/08‬ه ـ حضرت‬\n‫(‪ ).....‬ســعودي اجلنســية ولــم يحضــر املدعــى عليــه وال مــن ينــوب عنــه وقــد‬\n‫تبلــغ باملوعــد فادعــت قائلــة يف دعواهــا لقــد أصــدر فضيلــة ســلفكم‬\n‫الشــيخ (‪ ).....‬الصــك يف ‪1431/01/04‬ه ـ املتضمــن إقامــة املدعــى عليــه‬\n‫ولي ـ ًا علــى أحفــادي أوالد مــن ابنتــي ومبــا أن املدعــى عليــه طاعــن يف‬\n‫الســن ويبلــغ مــن العمــر ثمانــن عام ـ ًا وهــو ضعيــف البصــر ممــا جعلــه‬\n‫غيــر قــادر علــى القيــام بأعبــاء الواليــة علــى القصــر كمــا أنــه قــد أصــدر‬\n\n                                                                                       ‫‪310‬‬\n\f      ‫صــك وكالــة لعــم القصــر وهــو ابــن املدعــى عليــه ولــم يقــم املدعــى عليــه‬\n      ‫وال وكيلــه بــأي شــيء جتــاه القاصريــن لــذا أطلــب نــزع الواليــة منــه‬\n      ‫واحلكــم بهــا لــي هــذه دعــواي ويف جلســة أخــرى حضــرت املدعيــة (‪).....‬‬\n      ‫حضــر حلضورهــا (‪ ).....‬ســعودي اجلنســية ثــم جــرى عــرض الدعــوى علــى‬\n      ‫املدعــى عليــه فقــال مــا ذكرتــه املدعيــة من صك الواليــة ورقمه وتاريخه‬\n      ‫ومصــدره ومــا تضمنــه فهــو صحيــح ومــا ذكرتــه مــن أننــي طاعــن يف‬\n      ‫الســن وأننــي أبلــغ مــن العمــر ثمانــن عام ـ ًا فهــو غيــر صحيــح فأنــا مــن‬\n      ‫مواليــد عام‪1359‬ه ـ حســب مــا يتضــح لفضيلتكــم مــن بطاقــة الهويــة‬\n      ‫الوطنيــة ومــا ذكرتــه مــن أننــي ضعيــف البصــر فهــو صحيــح ولكــن‬\n      ‫ذلــك ال يطعــن يف واليتــي عليهــم ومــا ذكرتــه مــن أننــي لــم أقــم بشــيء‬\n      ‫جتــاه القاصريــن فهــو صحيــح ولكــن ذلــك بســبب املدعيــة لكونهــا‬\n      ‫منعتنــي مــن مشــاهدة أحفــادي القصــر ملــدة ســنتني وال أوافــق علــى نــزع‬\n      ‫الواليــة منــي وجعلهــا للمدعيــة هكــذا أجــاب وبعــد ســماع الدعــوى‬\n      ‫واإلجابــة جــرى منــي محاولــة اإلصــاح بــن الطرفــن فلــم يصطلحــا ثــم‬\n      ‫أبــرزت املدعيــة الصــك يف ‪1431/07/14‬ه ـ الصــادر مــن هذه احملكمة‬\n      ‫املتضمــن احلكــم بحضانــة القصــر للمدعيــة ضــد املدعــى عليــه ونظــر ًا‬\n      ‫لوجــود القرابــة والرحــم بــن الطرفــن فقــد قــررت إحالــة الطرفــن إلــى‬\n      ‫قســم الصلــح يف هــذه احملكمــة حملاولــة اإلصــاح بــن الطرفــن ورفعــت‬\n      ‫اجللســة لذلــك ويف جلســة أخــرى حضــرت املدعيــة واملعــرف بهمــا مــن‬\n      ‫قبــل زوجهــا (‪ ).....‬ســعودي اجلنســية وحضــر حلضورهــا املدعــى عليــه وقــد‬\n      ‫كانــت جــرت الكتابــة لقســم االصــاح من أجل االصــاح بني الطرفني‬\n      ‫مبوجــب خطابنــا يف ‪1433/03/13‬ه ـ فعــادت إلينــا بشــرحهم املــؤرخ يف‬\n      ‫‪1433/04/20‬ه ـ املتضمــن عــدم مراجعــة الطرفــن أ‪ .‬ه ـ ‪ .‬وبعــرض ذلــك‬\n\n\n‫‪311‬‬\n\f‫علــى الطرفــن اســتعدا مبراجعــة قســم االصــاح ورفعــت اجللســة لذلــك‬\n‫ويف جلســة اخــرى حضــرت املدعيــة واملعــرف ولــم يحضــر املدعــى عليــه‬\n‫وال مــن ينــوب عنــه وقــد تبلــغ باملوعــد وقــد كانــت جــرت الكتابــة لقســم‬\n‫اإلصــاح مبوجــب خطابنــا يف ‪1433/08/11‬ه ـ فعــادت إلينــا بشــرحهم‬\n‫املــؤرخ يف ‪1433/12/21‬ه ـ املتضمــن عــدم اختصاصهم وســألت املدعية‬\n‫عــن البينــة التــي وعــدت بإحضارهــا فقالــت أطلــب إمهالــي إلحضارهــا‬\n‫ورفعــت اجللســة لذلــك ويف جلســة اخــرى حضــرت املدعيــة واملعــرف (‪).....‬‬\n‫واملدعــى عليــه وكالــة (‪ ).....‬ســعودي اجلنســية بالوكالــة عــن مبوجــب‬\n‫الوكالــة يف ‪1431/12/03‬ه ـ الصــادرة مــن كتابــة العــدل الثانيــة (‪).....‬‬\n‫وبســؤال املدعــى عليــه وكالــة عــن ســبب عــدم حضــور موكلــه اجللســة‬\n‫الســابقة قــال إن موكلــي ‪ -‬وهــو والــدي ‪ -‬يرقــد يف املستشــفى حاليــا‬\n‫للعــاج مــن الغرغرينــة هكــذا أجــاب وبســؤال املدعيــة عــن البينــة التــي‬\n‫وعــدت بإحضارهــا أحضــرت (‪ ).....‬ســعودي اجلنســية وبســؤاله عمــا لديه‬\n‫قــال أشــهد هلل تعالــى أن املدعيــة صاحلــة للواليــة علــى أحفادهــا القصــر‬\n‫أوالد وهــي ذات أمانــة وكفــاءة وديانــة واقتــدار هكــذا شــهد كمــا‬\n‫أحضــرت املدعيــة للشــهادة (‪ ).....‬ســعودي اجلنســية وبســؤاله عمــا لديــه‬\n‫قــال أشــهد هلل تعالــى أن املدعيــة صاحلــة للواليــة علــى أحفادهــا القصــر‬\n‫أوالد وهــي ذات أمانــة وكفــاءة وديانــة واقتــدار هكــذا شــهد وبعــرض‬\n‫الشــهود وشــهادتهم علــى املدعــى عليــه وكالــة قــال ال نعرفهــم وال نقــول‬\n‫فيهــم شــيئا غيــر أن موكلــي يرفــض نقــل الواليــة للمدعيــة هكــذا قــرر‬\n‫وبســؤال املدعيــة هــل لديهــا معدلــن لشــهودها قالــت نعــم وأحضــرت‬\n‫(‪ ).....‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم (‪ ).....‬وبســؤاله‬\n‫عمــا لديــه قــال أشــهد هلل تعالــى أن الشــاهدين أوالد (‪ ).....‬عــدالن‬\n\n\n                                                                                   ‫‪312‬‬\n\f      ‫ثقتــان هكــذا شــهد كمــا أحضــرت (‪ ).....‬ســعودي اجلنســية مبوجــب‬\n      ‫الســجل املدنــي رقــم (‪ ).....‬وبســؤاله عمــا لديــه قــال أشــهد هلل تعالــى‬\n      ‫أن الشــاهدين أوالد (‪ ).....‬عــدالن ثقتــان هكــذا شــهد فبنــاء علــى مــا‬\n      ‫تقــدم مــن الدعــوى واإلجابــة وشــهادة الشــاهدين املعدلــن شــرع ًا ونظــر ًا‬\n      ‫لكبــر ســن املدعــى عليــه أصالــة وســوء حالتــه الصحيــة وملــا انــه قــد تبني‬\n      ‫مــن حضــوره يف جلســة ســابقة أنــه رجــل مقعــد ونظــرا إلقــراره بأنــه لــم‬\n      ‫يقــم بشــيء جتــاه القاصريــن وألن مــا بــرر بــه مــن أن عــدم قيامــه بذلــك‬\n      ‫هــو بســبب منــع املدعيــة لــه مــن مشــاهدة أحفــاده القصــر ‪ -‬علــى فــرض‬\n      ‫صحتــه وثبوتــه ‪ -‬غيــر ســائغ إذ ال ذنــب للقصــر يف ذلــك وذلــك يلحــق‬\n      ‫الضــرر بهــم وكان الواجــب عليــه أن يقــوم مبــا فيــه األحــظ للقصــر قــال‬\n      ‫يف كشــاف القنــاع ‪ 447/3‬وال يجــوز لوليهمــا أي الصغيــر واملجنــون أن‬\n      ‫يتصــرف يف مالهمــا إال علــى وجــه احلــظ لهمــا لقولــه تعالــى (وال تقربــوا‬\n      ‫مــال اليتيــم إال بالتــي هــي احســن) وألن املدعيــة جــدة للقصــر مــن جهــة‬\n      ‫األم لــذا كلــه فقــد ثبتــت لــدي صالحيــة املدعيــة ألن تكــون وليــا علــى‬\n      ‫القصــر املذكوريــن وقــررت نقــل الواليــة مــن املدعــى عليــه أصالــة إلــى‬\n      ‫املدعيــة وأقمتهــا وليــا علــى القصــر أوالد ترعــى شــؤونهم وحتافــظ علــى‬\n      ‫مصاحلهــم وتخاصــم وتدافــع عــن حقوقهــم ولهــا احلــق يف البيــع والشــراء‬\n      ‫واإلفــراغ وقبولــه واســتالم الثمــن والتأجيــر واســتالم األجــرة وتوقيــع‬\n      ‫العقــود واســتالم جميــع مــا لهــم مــن حقــوق واملطالبــة بهــا واملداعــاه‬\n      ‫واملخاصمــة وســماع الدعــوى والــرد عليهــا وإقامــة البينــة والرفــع يف‬\n      ‫أي قضيــة تقــام منهــم أو ضدهــم أمــام أي محكمــة ويف أي جهــة ولهــا‬\n      ‫مراجعــة الدوائــر احلكوميــة واملؤسســات والشــركات واألفــراد وأي‬\n      ‫جهــة أخــرى يف جميــع املعامــات اخلاصــة بهــم وإنهــاء كافــة اإلجــراءات‬\n\n\n‫‪313‬‬\n\f‫الشــرعية واإلداريــة املتعلقــة بذلــك ولهــا حــق توكيــل الغيــر وأفهمتهــا‬\n‫بــأن عليهــا أن ال تتصــرف بشــيء مــن عقــارات القاصريــن ببيــع أو شــراء‬\n‫أو بــدل إال بــإذن مــن حاكــم شــرعي وان تقــدم بيان ـ ًا ســنوي ًا مبــا قامــت‬\n‫بــه جتــاه أمــوال وحقــوق القاصريــن املذكوريــن ومبــا تقــدم حكمــت‬\n‫وبعــرض احلكــم علــى املدعــى عليــه وكالــة قــرر عــدم القناعــة وطلــب‬\n‫التمييــز فأجيــب لطلبــه وجــرى إفهامــه بــأن عليــه املراجعــة يــوم االثنــن‬\n‫املوافــق ‪1434/4/22‬ه ـ الســتالم نســخة مــن صــك احلكــم لالعتــراض‬\n‫عليــه وأن عليــه تقــدمي اعتراضــه خــال ثالثــن يومــا تبــدأ مــن التاريــخ‬\n‫املذكــور فــإن تأخــر عــن ذلــك ســقط حقــه يف االعتــراض واكتســب‬\n‫احلكــم القطعيــة وختمــت اجللســة الســاعة ‪08 : 45‬وبــاهلل التوفيــق‬\n‫‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n                                                              ‫‪1434/04/20‬ه ـ‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ويف يــوم‬\n‫الثالثاء املوافق ‪1434/07/04‬هـ افتتحت اجللســة بعد أن عادت املعاملة‬\n‫مــن محكمــة االســتئناف وبرفقهــا القــرار يف ‪1434/06/19‬ه ـ ونــص‬\n‫احلاجــة منــه (وبدراســة الصــك وصــورة ضبطــه والئحتــه االعتراضيــة‬\n‫تقــرر باألكثريــة املوافقــة علــى احلكــم مــع مالحظــة التنبيــه) قاضــي‬\n‫اســتئناف (‪ ).....‬ختــم وتوقيــع قاضــي اســتئناف (‪ ).....‬ختــم وتوقيــع رئيــس‬\n‫الدائــرة ‪ -‬لــي وجهــة نظــر ‪ -‬ختــم وتوقيــع ‪ ،‬وحتــى ال يخفــى أمــرت‬\n‫بإثباتــه علــى ضبطــه وســجله ‪ ،‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n                 ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/7/4‬ه ـ‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد فقــد‬\n‫جــرى منــا نحــن قضــاة الدائــرة الثالثــة لألحــوال الشــخصية واألوقــاف‬\n\n\n                                                                                     ‫‪314‬‬\n\f      ‫والوصايــا والقصــار وبيــوت املــال مبحكمة االســتئناف يف منطقة مكة‬\n      ‫املكرمــة االطــاع علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة‬\n      ‫العامــة املســاعد وتاريــخ ‪1434/6/7‬ه املرفــق بهــا الصــك الصــادر مــن‬\n      ‫فضيلــة الشــيخ (‪ ).....‬القاضــي باحملكمــة العامة وتاريخ ‪1434/4/21‬هـ‬\n      ‫‪ ،‬املتضمــن طلــب املــرأة نــزع واليــة عــن أحفادهــا‪ ،‬وبدراســة الصــك‬\n      ‫وصــورة ضبطــه والئحتــه االعتراضيــة تقــرر باألكثريــة املوافقــة علــى‬\n      ‫احلكــم مــع مالحظــة التنبيــه املرفــق‪ ،‬واهلل املوفــق ‪ .‬وصلــى اهلل علــى‬\n                                       ‫نبينــا محمــد وعلــى الــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪315‬‬\n\f316\n\f317\n\f318\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"8772d0b1-3c0f-5928-9c22-98c49da1913e","source_page_start":309,"source_page_end":318,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"a976bac48e0a5b7d31e6c37d479532318406284d349db829ba94263fd633ae2c","normalized_text_hash":"f6acc1e734ce03c4e089d1a843fcafb8747b4b15406f6d1473d0b651b330d160","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v4-p309-34193719"},{"id":"23434c3a-12ef-5b08-bbff-b6f635102d5a","document_type":"judgment","category":"judicial","subcategory":"general","title":"حجر -حجر لسفه -ابن يطالب باحلجر على والده لسفه بتبديد املال وصرفه يف غير مصلحه ومنع مستحقه -إنكار املدعى عليه والدفع بأن املدعى ولد عاق وغير سوي -ثبوت سامة املدعي عليه من الناحية النفسية والعقلية -صرف النظر عن دعوى املدعى .","document_number":"34209994","case_number":"50077","judgment_number":null,"decision_number":null,"circular_number":null,"court":null,"circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/9/17","year":"1434","subject":"حجر -حجر لسفه -ابن يطالب باحلجر على والده لسفه بتبديد املال وصرفه يف غير مصلحه ومنع مستحقه -إنكار املدعى عليه والدفع بأن املدعى ولد عاق وغير سوي -ثبوت سامة املدعي عليه من الناحية النفسية والعقلية -صرف النظر عن دعوى املدعى .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/9/17:‬هـ‬\n                      ‫ُ‬                ‫َر ْق ُم َّ‬\n                         ‫الص ِّك‪34209994 :‬‬\n                           ‫َر ْق ُم الدعوى‪50077 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n               ‫‪ 34295203‬تاريخه‪1434/8/13 :‬هـ‬\n\n\n      ‫حجــر ‪ -‬حجــر لســفه ‪ -‬ابــن يطالــب باحلجــر علــى والــده لســفه بتبديــد‬\n      ‫املــال وصرفــه يف غيــر مصلحــه ومنــع مســتحقه ‪ -‬إنــكار املدعــى عليــه‬\n      ‫والدفــع بــأن املدعــى ولــد عــاق وغيــر ســوي ‪ -‬ثبــوت ســامة املدعــي عليــه‬\n         ‫مــن الناحيــة النفســية والعقليــة ‪ -‬صــرف النظــر عــن دعــوى املدعــى ‪.‬‬\n\n\n\n\n      ‫مــا أســتند إليــه القاضــي مــن القواعــد العامــة ومبــادئ العدالــة يف‬\n                                                             ‫تســبيب حكمــه‪.‬‬\n\n\n\n\n      ‫إقامــة ابــن دعــوى حجــر علــى والــده لســفهه ‪ ،‬ذكــر املدعــي أن املدعــى‬\n      ‫عليــه يقــوم بتبديــد األمــوال ورهــن املنــازل وحتمــل الديــون وتواجــده‬\n      ‫خــارج البــاد بشــكل دائــم وإهمالــه ألهــل بيتــه وعــدم اإلنفــاق عليهــم‬\n      ‫النفقــة الواجبــة وذكــر تصرفــات لوالــده اســتدل بهــا علــى ســفهه ‪ ،‬لــم‬\n      ‫تعتبــر احملكمــة هــذا التصرفــات موجبــه إلثبــات ســفه املدعــى عليــه ‪،‬‬\n      ‫انكــر املدعــى عليــه مــا جــاء يف دعــوى املدعــي وذكــر بــأن املدعــي عــاق‬\n      ‫ويتعاطــى املخــدرات وأن بينــه وبــن املدعــى عــدة دعــاوى ‪ ،‬طلــب املدعــي‬\n      ‫الكشــف علــى والــده لتحديــد ســامته مــن املــرض ‪ ،‬قــررت احملكمــة‬\n      ‫الكتابــة للمستشــفى املختــص ‪ ،‬فــورد تقريــر مــن اجلهــة املختصــة يثبــت‬\n\n‫‪319‬‬\n\f‫ســامة املدعــى عليــه مــن الناحيــة النفســية والعقليــة ‪ ،‬لــذا حكمــت‬\n‫احملكمــة بصــرف النظــر عــن دعــوى املدعــى ‪ ،‬اعتــرض املدعــي علــى‬\n                 ‫احلكــم ‪ ،‬صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ ).....‬القاضــي يف احملكمــة العامــة‬\n‫بالريــاض حضــر وحضــر حلضــوره وادعــى األول قائـاً‪ :‬إن دعــواي علــى‬\n‫والــدي علــى قيامــه بتبديــد أمــوال التركــه ورفــع دعــوى علــى والــده بعــد‬\n‫املمــات مبطالبــة ماليــة ومطالبــة الورثــة ببيــع الوقــف جلــدي ورهــن املنــازل‬\n‫التــي نعيــش بهــا وحتميلنــا ديــون ملصلحتــه وتواجــده خــارج الســعودية‬\n‫بشــكل دائــم وهــو مبتلــى بفتنــة النســاء وظلمــه لنــا ولوالدتنــا ونحــن‬\n‫جاهــزون لتحضيــر الشــهود أنــا وإخوتــي وأطلــب احلجــر علــى والــدي‬\n‫لعــدم أهليتــه يف صــرف األمــوال وحمايتــه مــن نفســه وحمايتنــا منــه ورد‬\n‫حقــوق النــاس هــذه دعــواي وبعــرض دعــوى املدعــي علــى املدعــى عليــه‬\n‫وكالــة أجــاب جوابـ ًا محــرر ًا هــذا نصــه ‪ :‬احلمــد هلل علــى مــا قــدر واحلمد‬\n‫هلل علــى مــا شــاء وكمــا قــال تعالــى وقولــه احلــق جــل يف عــاه يف كتابــه‬\n‫الكــرمي (إن مــن أزواجكــم وأوالدكــم عــدو لكــم) ســورة التغابــن‬\n‫اســمحوا لــي أن لوضــح لكــم الوقائــع الســابقة بينــي وبــن املدعــي (‬\n‫ابنــي العــاق ) وهــي مــا يلــي ‪ -1 :‬قــام ابنــي العــاق يف بيــع عــدد ‪ 52‬تأشــيرة‬\n‫واملســجلة باســم مؤسســة (‪ ).......‬للديكــورات لصاحبهــا (‪ ،).......‬قــام‬\n‫ابنــي العــاق ببيعهــا ملؤسســات وشــركات وبــدون علمــي وموافقتــي‬\n‫وجــراء بيعــه للتأشــيرات فقــد ضــر مبصاحلــي التجاريــة وبعــد مناقشــة‬\n‫ابنــي العــاق بشــان بيعــه للتأشــيرات قــام بتهديــدي بالقتــل والتلفــظ علــى‬\n\n                                                                                         ‫‪320‬‬\n\f      ‫باســوا األلفــاظ التــي ال تليــق بابــن عاقــل أن يتلفــظ بهــا علــى والــده ويف‬\n      ‫العشــر األواخــر مــن رمضــان مــن عــام ‪1431‬ه ـ قامــت الدوريــات األمنيــة‬\n      ‫بالقبــض عليــه للشــك يف تعاطيــه للمخــدرات ‪ ،‬وبعــد إجــراء الكشــف‬\n      ‫الطبــي عليــه ثبــت تعاطيــه للمخــدرات بنــاء علــى التقريــر الطبــي الصــادر‬\n      ‫مــن مستشــفى (‪ ).......‬والــذي ســبق وان زودناكــم بصــورة منــه ومرفــق‬\n      ‫صــورة منــه ‪-2 .‬تفاجئــت يف يــوم عيــد الفطــر لعــام ‪ 1431‬ه ـ بخــروج ابنــي‬\n      ‫العــاق مــن املستشــفى مــع املفتــرض أن يبقــي فتــرة طويلــة متتــد ألشــهر‬\n      ‫للعــاج فــا أعلــم كيــف خــرج مــن املستشــفى ‪ ،‬ولهــذا الســبب قــرر‬\n      ‫أن ينتقــم منــي برفعــه لهــذه الدعــوى املنظــورة لــدي فضيلتكــم فضيلــة‬\n      ‫الشــيخ أفيدكــم بأنــه بتاريــخ ‪1432/03/12‬ه ـ تقدمــت بخطــاب‬\n      ‫لصاحــب الســمو امللكــي األميــر (مرفــق صــورة مــن اخلطــاب) ومت إحالــة‬\n      ‫اخلطــاب مــن أمــارة الريــاض إلــي احملكمــة اجلزئيــة لنظــر موضوعــي‬\n      ‫شــرع ًا ضــد ابنــي العــاق وقامــت احملكمــة اجلزئيــة بإحالــة ملــف القضيــة‬\n      ‫إلــى فضيلــة الشــيخ الدكتــور (‪ ، ).......‬حيــث تتعلــق الدعــوى بعقــوق‬\n      ‫ابنــي ولكــن تخلــف ابنــي عــن حضــور اجللســات ومت طلبــه أكثــر مــن‬\n      ‫مــرة مــن فضيلــة القاضــي واتصــل بــه عــدة مــرات ولــم يحضــر ‪ ،‬وقــد‬\n      ‫أرســل فضيلــة القاضــي ملركــز شــرطة امللــز خطاب ـ ًا ذي الرقــم ‪5699‬‬\n      ‫وتاريــخ ‪1432/8/17‬ه ـ للقبــض عليــه بالقــوة وإحضــاره مخفــور ًا ومت‬\n      ‫التعميــم عليــه يف املباحــث إلحضــاره للقبــض عليــه بالقــوة اجلبرية ولكن‬\n      ‫لــم يتــم القبــض عليــه حتــى هــذا التاريــخ وال يــزال حــر ًا طليق ـ ًا وميــارس‬\n      ‫إدمانــه للمخــدرات ‪ ،‬واملباحــث يف أدارة مكافحــة املخــدرات تبحــث‬\n      ‫عنــه ألكثــر مــن أربعــة شــهور ولــم جتــده حتــى اآلن فضيلــة الشــيخ كمــا‬\n      ‫أوضحــت يف اجللســة الســابقة لفضيلتكــم بأننــي تأســفت بــان املدعــي‬\n\n\n‫‪321‬‬\n\f‫ابنــي الــذي قمــت طــوال هــذه الســنوات املنطويــة بتربيتــه وتعليمــه يف‬\n‫ارقــي اجلامعــات وتكلفــت بتكاليــف زواجــه كاملــة مــن مهــر ومعيشــة‬\n‫كرميــة وقدمــت لــه مــن التســهيالت املاليــة فــوق حاجتــه وســلمته اجلمــل‬\n‫ومــا حمــل وحــررت لــه وكاالت شــرعية ( مرفــق صــورة منهــا ) يحــق لــه‬\n‫البيــع والشــراء والقبــض وغيرهــا مــن الصالحيــات وقــد ضعفــت نفســه‬\n‫الدنيئــة للشــيطان واســتجاب لشــياطني اإلنــس واجلــن وأصبــح عــدوا لــي‬\n‫ويريــد احلجــر علــي وأن يســتحل مالــي بــدون مســوغ شــرعي أو نظامــي‪.‬‬\n‫احلمــد هلل وحــده وبعــد فلــدي (‪ ).......‬القاضــي يف احملكمــة العامــة‬\n‫بالريــاض ففــي يــوم الســبت املوافــق ‪1433/03/19‬ه ـ افتتحــت اجللســة‬\n‫الســاعة ‪10 : 30‬ص لســماع دعــوى ضــد وفيهــا حضــر املدعــى عليــه‬\n‫ولــم يحضــر املدعــي أو مــن ينــوب عنــه يف هــذه اجللســة وقــد قــدم املدعــي‬\n‫طلــب تأجيــل الدعــوى برقــم يف ‪1433/03/14‬ه ـ لكونــه غيــر متواجــد‬\n‫يف هــذا التاريــخ احملــدد لســماع الدعــوى وعليــه رفعــت اجللســة حلــن‬\n‫مراجعــة املدعــي وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n‫آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1433/03/19‬ه ـ الســاعة احلاديــة عشــرة‬\n                                                                         ‫صباحــا‪.‬‬\n‫احلمــد هلل وحــده وبعــد ففــي يــوم الثالثــاء املوافــق ‪1434/03/17‬ه ـ‬\n‫افتتحــت اجللســة الســاعة ‪09 : 00‬وفيهــا حضــر الطرفــان ولــم يحــرر‬\n‫املدعــي رده علــى مــا جــاء يف جــواب املدعــى عليــه يف اجللســة املاضيــة‬\n‫وجــرى إفهــام املدعــي بتحريــر دعــواه ورفعــت اجللســة وتأجلــت ليــوم‬\n‫األربعــاء ‪1434/5/1‬ه ـ الســاعة ‪ 11 : 30‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل‬\n‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/3/17‬ه ـ‬\n‫فضيلــة الشــيخ أن ابنــي العــاق أخــذ برفــع هــذه الدعــوى ليمــارس االنتقام‬\n\n\n                                                                                    ‫‪322‬‬\n\f      ‫والضغــط العصبــي ضــدي ويكســب مــن وراءهــا التســتر علــى أعمالــي‬\n      ‫واســتغالله للــوكاالت الشــرعية الصــادرة لــي واســتغل كبــر ســني يف‬\n      ‫عــدم متابعتــه للجلســات القضائيــة والرضــوخ لــي ولكــن فــات علــى ابني‬\n      ‫ا‬\n      ‫العــاق بانــه اســتمد قوتــه مــن اهلل ســبحانه وتعالــي والدعــاء عليــه لي ـ ً‬\n      ‫ونهــار ًا ويف الســر والعالنيــة فضيلــة الشــيخ اطلــب مــن فضيلتكم صرف‬\n      ‫النظــر عــن الدعــوى وعــدم التأخيــر يف البــت يف هــذه القضيــة مــع حفــظ‬\n      ‫كامــل حقوقــي الشــرعية والنظاميــة ضــد ابنــي العــاق ومــا ســببه لــي‬\n      ‫مــن أســى وتعــب جــراء تصرفاتــه بحقــي هكــذا أجــاب وبعــرض جــواب‬\n      ‫املدعــى عليــه علــى املدعــي قــال أطلــب مهلــة للجــواب جواب ـ ًا محــرر ًا يف‬\n      ‫اجللســة القادمــة ‪ .‬ويف جلســة أخــرى حضــر املدعــي وحضــر حلضــوره‬\n      ‫املدعــى عليــه يرافقــه بصفتــه وكيــا عنــه مبوجــب الوكالــة والصــادرة‬\n      ‫مــن كتابــة العــدل الثانيــة بالريــاض واملخــول لــه فيهــا باملطالبــة واملرافعة‬\n      ‫واإلقــرار والصلــح والتنــازل ‪ ...‬إلــخ وبســؤال املدعــي عمــا اســتمهل مــن‬\n      ‫ا أن مــا طرحــه خصمــي يف دعــواي مــن أننــي ابــن‬          ‫أجلــه أجــاب قائ ـ ً‬\n      ‫عــاق واســتخدم مخــدرات فاجلــواب أن فحــوى قضيتنــا هــذه أننــي أطلــب‬\n      ‫احلجــر علــى الوالــد لســفهه وعــدم حســن تصرفــه باملــال وأطلــب إصــدار‬\n      ‫صــك واليــة عليــه وردي علــي ادعائــه أننــي ابــن عــاق فهــذه قضيــة أخــري‬\n      ‫ومنظــورة لــدي فضيلــة القاضــي (‪ ).......‬باحملكمــة اجلزئيــة وقــد انتهــت‬\n      ‫بحفظهــا لــدي القاضــي بعــد حضــوري للجلســة وتقــدمي كفالــة حضوريــة‬\n      ‫حلضــوري يف أي وقــت يتــم اســتدعائي وأنــا مســتعد وجاهــز وبالنســبة‬\n      ‫الدعائــه أننــي اســتخدم مخــدرات وســارق فقــد صــدر تقريــر مــن إمــارة‬\n      ‫الريــاض ببطــان هــذا االدعــاء وجتــدون القــرار لديكــم يف األوراق‬\n      ‫ولــدي منــه صــورة أعــود إلــى صلــب املوضــوع فــإن والــدي قــد اســتلم‬\n\n\n‫‪323‬‬\n\f‫مبلــغ حوالــي ‪ 70‬مليــون ريــال ورثــه مــن والــده منــذ ثــاث ســنوات تقريبــا‬\n‫ولديكــم اإلثبــات ولــدي منهــا صــوره أيــن املــال اآلن ولدينــا بينــه اآلن‬\n‫أنــه يتســلف مبالــغ صغيــرة مــن العمــال وكذلــك يســكن شــقة إيجــار‬\n‫وكذلــك مت توقيفــه بشــرطه امللــز بقضيــه مبلــغ ‪170‬الــف ريــال إضافــة‬\n‫إلــى أن والــدي قــام ببيــع عمــارة بامللــز مببلــغ ثالثــة ماليــن وثالثمائة ألف‬\n‫ريــال يف ‪1432/9/2‬ه ـ وهــي مســيومة مببلــغ أربعــة ماليــن وســتمائة‬\n‫ألــف ريــال عــن طريــق مكتــب (‪ ).......‬العقــاري وخالــي كان وســيطا‬\n‫ثــم بعــد خمســة أشــهر مت توقيــف والــدي بشــرطة امللــز يف ‪1433/2/1‬ه ـ‬\n‫أطلــب ســؤاله أيــن ذهــب املــال الثالثــة ماليــن خــال اخلمســة أشــهر‬\n‫فأنــا ادعــي أن والــدي بــاع هــذه العمــارة ســفها حيــث باعهــا بأقــل مــن‬\n‫قيمتهــا مبليــون ريــال واعتقــد شــرع ًا أن هــذا مبــرر قــوي لرفــع واليتــه‬\n‫عــن البيــع والشــراء وبالنســبة إلضاعــة املــال خــال خمســة أشــهر ولدينــا‬\n‫الدليــل وهــذا يعتبــر تفريــط وهــذان املبــرران أعتقــد أنهمــا كافيــان‬\n‫لنــزع واليتــه علــى التصــرف باملــال كمــا أن والــدي بــاع فيــا بالربــوة‬\n‫قبــل أربعــن يومــا تقريبــا مببلــغ ثالثــة ماليــن ومائتــي ألــف ريــال فأطلــب‬\n‫ســؤاله أيــن ذهــب هــذا املــال وأطلــب مــن احملكمــة نــدب جلنــة لتقييــم‬\n‫العقــار ألننــي اعتقــد أنــه بــاع هــذا العقــار بالنقــص مــن قيمتــه بكثيــر‬\n‫وبالنســبة لألمــور الباقيــة لــدى والــدي والتــي معــي عليهــا دليــل وهــي‬\n‫التــي دفعتنــي لطلــب احلجــر عليــه هــي متلكــه لقصــر باملغــرب وللعلــم فــان‬\n‫والــدي قــد طلــب منــي أن أتنــازل عــن أرضــه بحائــل أو أنــه ســوف يتعامــل‬\n‫معــي بقســاوة ولــدي دليــل علــى مســاومته وعنــدي شــاهد ضابــط يعمــل‬\n‫بالشــرطة وأنــا مســتعد بإحضــاره وبالنســبة الدعائــه بتربيتنــا فلتعلــم‬\n‫احملكمــة أن أكثــر إقامتــه كانــت باملغــرب وتركنــي أنــا ووالدتــي‬\n\n\n                                                                                       ‫‪324‬‬\n\f      ‫بحائــل وبإمــكان احملكمــة طلــب تقريــر مــن جــوزات الريــاض عــن‬\n      ‫عــدد الســنوات التــي أقامهــا يف املغــرب وقبــل ذلــك كان يقيــم بالريــاض‬\n      ‫وأطلــب تقريــر حديــث مــن الصحــة النفســية لتحديــد ســامة والــدي‬\n      ‫مــن املــرض النفســي وقــد أحضــر للمحكمــة تقريــر حديــث يفيــد أنــه‬\n      ‫ســليم وأن ملفــه جديــد لــم يتعــد أشــهر وهــذا باطــل ولدينــا الدليــل أن‬\n      ‫ملفــه بالصحــة النفســية بالريــاض مفتــوح وقائــم منــذ خمســة عشــر ســنة‬\n      ‫ورقــم امللــف إضافــة إلــى أن علــى والــدي مطالبــة ماليــة قائمــة باحملكمــة‬\n      ‫مببلــغ أربعــة ماليــن ريــال ولــدي الدليــل فضيلــه القاضــي كيــف أن‬\n      ‫شــخص يســتلم حوالــي ســبعني مليــون ريــال منــذ ثالثــة ســنوات تقريبــا‬\n      ‫واآلن مفلــس مــع العلــم انــه لــم يدخــل ســوق األســهم إمنــا كانــت إقامتــه‬\n      ‫بــ(‪ ).....‬للنزهــة أليــس هــذا ســفها أطلــب مــن الشــرع حمايــة باقــي احلــال‬\n      ‫هكــذا أجــاب هــذا وبعرضــه علــى املدعــى عليــه أجــاب املدعــى عليــه‬\n      ‫وكالــة بــأن املدعــي قــد أقــام علــى والــده عشــرة قضايــا حقوقيــة حديثــة‬\n      ‫لــم يتســلم موكلــي تبليغــات احلضــور بهــا فكيــف يدعــي علــى والــده‬\n      ‫الســفه ويقيــم عليــه هــذه القضايــا هكــذا أجــاب وبعرضــه علــى املدعــي‬\n      ‫أجــاب بــأن مــا ذكــره املدعــى عليــه وكالــة غيــر دقيــق والصحيــح أننــي‬\n      ‫رفعــت علــى والــدي خمســة قضايــا حقوقيــة حديثــة وقضيــة سادســة‬\n      ‫جنائيــة تتضمــن طلــب كــف أذى وقــد رفضــت املدعــى عليــه وكالــة‬\n      ‫اســتالم التبليغــات وهــذا ال يتعــرض مــع دعــوى الســفهة هكــذا أجــاب‬\n      ‫هــذا وقــد جــرت الكتابــة منــي بتاريــخ ‪1433/6/7‬ه ـ ملجمــع (‪).......‬‬\n      ‫بالريــاض فوردتنــي اإلفــادة بخطــاب املديــر التنفيــذي ملجمــع (‪).......‬‬\n      ‫برقــم ‪ 44/22/5704/4441‬وتاريــخ ‪1433/7/5‬ه ـ واملتضمنــة عــرض‬\n      ‫املذكــور علــى اللجنــة الطبيــة يــوم األربعــاء ‪1433/6/25‬ه ـ وباالطــاع‬\n\n\n‫‪325‬‬\n\f‫علــى ملفــه لدينــا وأخــذ التاريــخ املرضــي مــن أحــد أقاربــه وإجــراء املقابلة‬\n‫النفســية وفحــص احلالــة العقليــة تبــن التالــي‪ :‬لــم يســبق لــه أنــه راجــع‬\n‫لدينــا مــن قبــل ال يوجــد تاريــخ ألي اضطرابــات نفســية ســابقة حســب‬\n‫ادعائــه ومبناظرتــه اليــوم وجــد أنــه هــاديء متعــاون مزاجــه معتــدل‬\n‫كالمــه مترابــط مــدرك للزمــان واملــكان واألشــخاص والوظائــف‬\n‫املعرفيــة ضمــن احلــدود الطبيعيــة حكمــه علــى األمــور جيــد ومســتبصر‬\n‫بحالتــه التوصيــات تــرى اللجنــة الطبيــة أن املذكــور ســليم مــن الناحيــة‬\n‫النفســية والعقليــة يف الوقــت الراهــن وعليــه فهــو ال يحتــاج إلــى ولــي‬\n‫يرعــى شــؤونه أخصائــي طــب نفســي د‪ .‬أ(‪ ).......‬ختــم وتوقيــع د‪).......( .‬‬\n‫أخصائــي طــب نفســي ختــم وتوقيــع رئيــس اللجنــة الطبيــة (‪ ).......‬توقيــع‬\n‫وبعــرض التقريــر علــى الطرفــن قــرر املدعــي عــدم القناعــة بــه وقــرر‬\n‫املدعــى عليــه القناعــة بــه فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة‬\n‫وبنــاء علــى التقريــر الطبــي املرصــود بعاليــه وفيــه أن املذكــور ســليم مــن‬\n‫الناحيــة النفســية والعقليــة يف الوقــت الراهــن وعليــه فهــو ال يحتــاج إلــى‬\n‫ولــي يرعــى شــؤونه لــذا فقــد أفهمــت املدعــي بعــدم اســتحقاقه ملــا يدعيــه‬\n‫وصرفــت النظــر عــن دعــواه وبإعــان احلكــم علــى الطرفــن فقــرر‬\n‫املدعــى عليــه القناعــة وقــرر املدعــي عــدم القناعــة فأفهمتــه باملراجعــة‬\n‫يف يــوم الســبت ‪1434/5/11‬ه ـ الســتالم نســخة احلكــم لتقــدمي الالئحــة‬\n‫االعتراضيــة خــال ثالثــن يومـ ًا مــن تاريخــه وإن لــم يتقــدم خــال املــدة‬\n‫املذكــورة فــإن حقــه يف االســتئناف يســقط ويكتســب احلكــم القطعية‬\n‫وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آله وصحبه وســلم‬\n                                                      ‫‪ .‬حــرر يف ‪1434/5/1‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ‪ ،‬فقــد اطلعنــا نحــن قضــاة الدائــرة السادســة‬\n\n\n                                                                                       ‫‪326‬‬\n\f      ‫لتمييــز القضايــا احلقوقيــة مبحكمــة االســتئناف بالريــاض علــى‬\n      ‫املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة العامــة بالريــاض برقــم‬\n      ‫وتاريــخ املرفــق بهــا الصــك الصــادر مــن فضيلــة القاضــي باحملكمــة‬\n      ‫الشــيخ (‪ ).......‬اخلــاص بدعــوى (‪ ).......‬ضــد (‪ ).......‬يف دعــوى احلجــز علــى‬\n      ‫األوليــاء واملفلســن علــى الصفــة املوضحــة بالصــك واملتضمــن حكــم‬\n      ‫فضيلتــه بــأن املدعــى عليــه ال يحتــاج إلــى ولــي يرعــى شــؤونه وعــدم‬\n      ‫اســتحقاق املدعــي ملــا يدعيــه وصــرف النظــر عــن دعــواه‪ ،‬وبدراســة‬\n      ‫الصــك وصــورة ضبطــه والالئحــة االعتراضيــة وأوراق املعاملــة قررنــا‬\n      ‫باألكثريــة املصادقــة علــى احلكــم‪ .‬والل ــه املوفــق وصلــى اهلل علــى نبينــا‬\n                                                       ‫محمـ ــد وآل ــه وصحب ــه وســلم ‪.‬‬\n\n\n\n\n‫‪327‬‬\n\f328\n\f329\n\f330\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"8772d0b1-3c0f-5928-9c22-98c49da1913e","source_page_start":319,"source_page_end":330,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"d7fe8c7df9566c9996923d7e87d4601544942415df98e6a47af80d06d0ce1efc","normalized_text_hash":"f69135793bc596ca7bad08f98d2fb3c4f6d7b9e6c0f513eda447042ffd5ada28","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v4-p319-34209994"},{"id":"b33c98aa-fb26-5736-adf9-f6376e4133d9","document_type":"judgment","category":"judicial","subcategory":"general","title":"عقد وكالة بعوض -اتفاق املدعي واملدعى عليه على شراء املدعى عليه سيارات مبواصفات معينة خال مدة محددة -دفع املدعي للمدعى عليه مبلغ مالي -عدم إيفاء املدعى عليه مبا مت االتفاق عليه -مصادقة املدعى عليه على الدعوى -حلف املدعي اليمن- إلزام املدعى عليه بدفع املبلغ املطالب به قول النبي صلى اهلل عليه وسلم ( :البينة على املدعي واليمن على من أنكر) أخرجه البيهقي .","document_number":"34221359","case_number":"3489887","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالطائف والقائم بعمل املكتب القضائي الثامن","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/5/25","year":"1434","subject":"عقد وكالة بعوض -اتفاق املدعي واملدعى عليه على شراء املدعى عليه سيارات مبواصفات معينة خال مدة محددة -دفع املدعي للمدعى عليه مبلغ مالي -عدم إيفاء املدعى عليه مبا مت االتفاق عليه -مصادقة املدعى عليه على الدعوى -حلف املدعي اليمن- إلزام املدعى عليه بدفع املبلغ املطالب به قول النبي صلى اهلل عليه وسلم ( :البينة على املدعي واليمن على من أنكر) أخرجه البيهقي .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/5/25 :‬هـ‬\n                       ‫ُ‬                 ‫َر ْق ُم َّ‬\n                           ‫الص ِّك‪34221359 :‬‬\n                           ‫َر ْق ُم الدعوى‪3489887 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                     ‫‪ 342919‬تاريخه‪1434/8/8:‬هـ‬\n\n\n      ‫عقــد وكالــة بعــوض‪ -‬اتفــاق املدعــي واملدعــى عليــه علــى شــراء املدعــى‬\n      ‫عليــه ســيارات مبواصفــات معينــة خــال مــدة محــددة‪ -‬دفــع املدعــي‬\n      ‫للمدعــى عليــه مبلــغ مالــي‪ -‬عــدم إيفــاء املدعــى عليــه مبــا مت االتفــاق‬\n      ‫عليــه‪ -‬مصادقــة املدعــى عليــه علــى الدعــوى‪ -‬حلــف املدعــي اليمــن‪-‬‬\n                                    ‫إلــزام املدعــى عليــه بدفــع املبلــغ املطالــب بــه‬\n\n\n\n\n      ‫قــول النبــي صلــى اهلل عليــه وســلم‪ ( :‬البينــة علــى املدعــي واليمــن علــى‬\n                                                     ‫مــن أنكــر) أخرجــه البيهقــي ‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي بأنــه اتفــق مــع املدعــى عليــه علــى أن يشــتري لــه ســيارة‬\n      ‫مبواصفــات مذكــورة يف دعــواه خــال مــدة محــددة وســلم لــه مبلغــا‬\n                                      ‫ماليــا مقابــل ذلــك إال أن املدعــى عليــه لــم يـ ِ‬\n      ‫ـف مبــا مت االتفــاق عليــه ولــم‬\n      ‫يقــم بشــراء الســيارة لــه‪ ،‬ولــذا طلــب إلزامــه بدفــع املبلــغ الــذي اســتلمه‬\n      ‫منــه حــاال‪ -‬أقــر املدعــى عليــه مبــا جــاء يف الدعــوى ودفــع بأنــه وســيط‬\n      ‫بــن املدعــي وبــن طــرف ثالــث إال أنــه عجــز عــن إثبــات ذلــك الدفــع‬\n      ‫وطلــب ميــن املدعــي علــى نفــي مــا دفــع بــه فأداهــا املدعــي طبــق مــا‬\n      ‫طلــب منــه‪ -‬املدعــى عليــه أقــر مبــا جــاء يف دعــوى املدعــي وعجــز عــن‬\n‫‪331‬‬\n\f‫إثبــات كونــه وســيط ًا واملدعــي حلــف اليمــن التــي طلبــت منــه‪ -‬قضــت‬\n‫احملكمــة بإلــزام املدعــى عليــه بــأن يســلم للمدعــي املبلــغ املدعــى بــه‬\n‫حــا ًال دون تأخيــر أو مماطلــة‪ -‬عــارض املدعــى عليــه علــى احلكــم‪-‬‬\n                     ‫قــررت محكمــة االســتئناف املوافقــة علــى احلكــم ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا القاضــي يف احملكمــة العامــة بالطائف‬\n‫والقائــم بعمــل املكتــب القضائــي الثامــن وبنــاء علــى املعاملــة احملالــة‬\n‫لنــا مــن فضيلــة رئيــس احملكمــة العامــة بالطائــف برقــم ‪3489887‬‬\n‫وتاريــخ ‪ 1434/02/24‬ه ـ املقيــدة باحملكمــة برقــم ‪ 34459611‬وتاريــخ‬\n‫‪ 1434/02/24‬ه ـ ففــي يــوم األحــد املوافــق‪ 1434/03/22‬ه ـ افتتحــت‬\n‫اجللســة الســاعة التاســعة صباحــا للنظــر يف الدعــوى املرفوعــة مــن ‪........‬‬\n‫ضد ‪ ........‬للمطالبة بتســليم مبيع وفيها حضر ســعودي اجلنســية مبوجب‬\n‫الســجل املدنــي رقــم ولــم يحضــر املدعــى عليــه وال مــن ميثلــه بوكالــة‬\n‫شــرعية ولــم يردنــا مــا يفيــد تبلغــه وبنــاء علــى املــادة الثالثــة واخلمســن‬\n‫مــن نظــام املرافعــات الشــرعية رفعــت اجللســة ثــم لــدي أنــا القاضــي يف‬\n‫احملكمــة العامــة بالطائــف ويف يــوم الســبت املوافــق‪ 1434/04/20‬ه ـ‬\n‫افتتحــت اجللســة الســاعة التاســعة صباحــا وفيهــا حضــر املدعــي ســعودي‬\n‫اجلنســية مبوجــب الســجل املدنــي رقــم وحضــر حلضــوره املدعــى عليــه‬\n‫ســعودي اجلنســية مبوجــب بطاقــة الهويــة الوطنيــة رقــم وأدعــى املدعــي‬\n‫قائــا يف حتريــر دعــواه أنــي دفعــت لهــذا احلاضــر معــي مبلــغ وقــدرة‬\n‫أربعــة وخمســون ألــف ريــال مقابــل أن يشــتري لــي ســيارة مــن نــوع ‪....‬‬\n‫موديــل ‪2010‬م بلــون ســمني والداخلــي بلــون هلــوز اســتعمال أمريكــي‬\n\n                                                                                       ‫‪332‬‬\n\f      ‫ـف مبا مت‬ ‫ببطاقــة جمركيــة خــال أربعــن يومــا إال أن املدعــى عليــه لــم يـ ِ‬\n      ‫االتفــاق عليــه ولــم يحضــر لــي شــيئ ًا حتــى تاريــخ أطلــب إلزامــه بدفــع هــذا‬\n      ‫املبلــغ لــي حــاال هــذه دعــواي وإنــي أســأله اجلــواب وبســؤال املدعــي عليــه‬\n      ‫عــن دعــوى املدعــي أجــاب قائــا ‪ :‬مــا ذكــره املدعــي مــن اســتالم املبلــغ‬\n      ‫وقــدرة أربعــة وخمســون ألــف فصحيــح وكنــت اتفقــت معــه علــى أن‬\n      ‫اســتلم منــه املبلــغ وأشــتري لــه ســيارة باملواصفــات املذكــورة يف دعــواه‬\n      ‫ويســتلم الســيارة مــن شــخص يدعــى هــذ إجابتــي ولضيــق وقــت اجللســة‬\n      ‫ودخــول وقــت اجللســة التــي تليهــا جــرى رفــع اجللســة ويف يــوم الســبت‬\n      ‫‪ 1434/05/25‬ه ـ افتتحــت اجللســة الســاعة التاســعة والنصــف صباحــا‬\n      ‫وفيهــا حضــر املدعــي ســعودي اجلنســية مبوجــب بطاقــة الهويــة الوطنيــة‬\n      ‫رقــم وحضــر حلضــوره املدعــى عليــه ‪ .....‬ســعودي اجلنســية مبوجــب بطاقــة‬\n      ‫الهويــة الوطنيــة رقــم ‪ .....‬وبســؤال املدعــى عليــه عــن االتفــاق الــذي بينــه‬\n      ‫وبــن املدعــي أجــاب قائ ـاً‪ :‬إمنــا أنــا مجــرد وكيــل للمدعــي يف إيصــال‬\n      ‫املبلــغ وتســليم املدعــي كمبيالــة باملبلــغ‪ ،‬هــذه إجابتــي ‪ ،‬وبســؤال‬\n      ‫املدعــى عليــه هــل لديــك بينــة؟ أجــاب قائ ـاً‪ :‬ليــس لــدي بينــة وأطلــب‬\n      ‫ميــن املدعــي هكــذا أجــاب ‪ ،‬وبعرضــه علــى املدعــي اســتعد باحللــف‬\n      ‫ا ‪ :‬واهلل الــذي ال إلــه إال هــو الــذي يعلــم الســر والعالنيــة‬  ‫وحلــف قائ ـ ً‬\n      ‫ويعلــم الغيــب والشــهادة إننــي اتفقــت مــع هــذا احلاضــر معــي علــى أن‬\n      ‫يحضــر لــي ســيارة مــن نــوع ‪ 2010 ....‬لونهــا ســمني وداخلهــا هلــوز خــال‬\n      ‫مــدة أربعــن وليــس وكيــا لــي يف إيصــال املبلــغ ولــم أتفــق معــه علــى أن‬\n      ‫يكــون االســتالم عنــد ‪ .......‬وال أعرفــه إال بعــد حصــول هــذه املشــكلة‬\n      ‫ولــم أســتلم منــه الســيارة ولــم أكشــف عليهــا واهلل واهلل واهلل هكــذا‬\n      ‫حلــف ‪ ،‬فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة املتضمنــة مصادقــة‬\n\n\n‫‪333‬‬\n\f‫املدعــى عليــه لدعــوى املدعــي وعجــزه عــن إثبــات كونــه وســيط ًا ومبا أن‬\n‫املدعــي حلــف اليمــن التــي طلبــت منــه ‪ ،‬وملــا جــاء عــن النبــي صلــى اهلل‬\n‫عليــه وســلم ‪ ( :‬البينــة علــى املدعــي واليمــن علــى مــن أنكــر) أخرجــه‬\n‫البيهقــي (‪ )252/10‬عــن ابــن عبــاس ‪-‬رضــي اهلل عنــه‪ -‬وحســنه احلافــظ‬\n‫يف الفتــح (‪ ،)283/5‬لذلــك كلــه فقــد ثبــت لــدي أن بذمــة املدعــى عليــه‬\n‫مبلــغ قــدره أربعــة وخمســون ألــف ريــال يدفعهــا للمدعــي ‪ ............‬حــا ًال‬\n‫دون تأخيــر أو مماطلــة هــذا مــا ظهــر لــي وبــه حكمــت وبعرضــه علــى‬\n‫املدعــى عليــه قــرر اعتراضــه علــى احلكــم وطلــب االســتئناف بالئحــة‬\n‫اعتراضيــة ويف نفــس اجللســة جــرى تســليم املدعــى عليــه نســخة احلكــم‬\n‫وأفهــم بــأن لــه مــدة ثالثــن يــوم لتقــدمي اعتراضــه علــى احلكــم تبــدأ مــن‬\n‫تاريــخ اليــوم وإذا لــم يقــدم اعتراضه خاللها فيســقط حقه يف االعتراض‬\n‫ويكتســب احلكــم القطعيــة ففهــم ذلــك ‪ ،‬وكان رفــع اجللســة الســاعة‬\n‫العاشــرة صباحــا وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد‬\n                       ‫وعلــى آلــه وصحبــه أجمعــن‪ ،‬حــرر يف ‪1434/5/25‬هــ‪.‬‬\n‫احلمــد هلل وحــده‪ ،‬والصــاة والســام علــى مــن ال نبــي بعــده‪ ،‬وبعــد ‪:‬‬\n‫ثــم عــادت املعاملــة مــن محكمــة االســتئناف مبكــة املكرمــة مصادقـ ًا‬\n‫عليهــا بالقــرار رقــم ‪ 34291917‬يف ‪1434/8/8‬ه ـ ونصــه احلمــد هلل‬\n‫والصــاة والســام علــى رســول اهلل وبعــد فقــد جــرى اطالعنــا نحــن‬\n‫رئيــس وعضــوي الدائــرة احلقوقيــة الرابعــة يف محكمــة االســتئناف‬\n‫مبنطقــة مكــة املكرمــة االطــاع علــى الصــك الصــادر مــن فضيلــة‬\n‫الشــيخ ‪ /‬القاضــي باحملكمــة العامــة بالطائف واملســجل بعــدد املتضمن‬\n‫دعــوى ضــد‪ /‬احملكــوم فيــه مبــا دون باطنــه ‪ ،‬وبدراســة الصــك وصــورة‬\n‫ضبطــه والئحتــه االعتراضيــة تقــررت املوافقــة علــي احلكــم وبــاهلل‬\n\n\n                                                                                      ‫‪334‬‬\n\f      ‫التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم قاضــي‬\n      ‫اســتئناف ختــم وتوقيــع‪ .‬قاضــي اســتئناف موقــع يف األصــل وموافــق علــى‬\n      ‫احلكــم ومنتــدب‪ .‬رئيــس الدائــرة ختــم وتوقيــع‪ .‬وصلــى اهلل وســلم علــى‬\n                                        ‫نبينــا محمــد ‪.‬حــرر يف ‪1434/8/25‬هــ‪.‬‬\n\n\n\n\n‫‪335‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"8772d0b1-3c0f-5928-9c22-98c49da1913e","source_page_start":331,"source_page_end":335,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"c13afab8d7f3b8cd84e20dbd6754fbf1dfb7cbf61ec2811d018d247639fff444","normalized_text_hash":"ffe8e147da425234329387791f2fb689a318fab0d5b31d3cf6efe996e12cc896","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v4-p331-34221359"},{"id":"bac9ee3f-c417-599e-bb80-d56f2a060a04","document_type":"judgment","category":"judicial","subcategory":"general","title":"عقد وكالة بعوض -اتفاق املدعي مع املدعى عليه على شراء املدعى عليه سيارات محددة الوصف خال مدة محددة -الرجوع وسداد الثمن حال عدم التسليم يف املوعد -عدم إيفاء املدعى عليه مبا مت االتفاق عليه -املطالبة باملبلغ املدفوع -تقدمي املدعي بينة- شهادة شاهد عدل -حلف اليمن -عدم حضور املدعى عليه دون عذر -إلزام املدعى عليه غيابي ا بدفع املبلغ املدعى به -املدعى عليه على حجته متى حضر .","document_number":"34227273","case_number":"3499675","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالطائف ف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/5/29","year":"1434","subject":"عقد وكالة بعوض -اتفاق املدعي مع املدعى عليه على شراء املدعى عليه سيارات محددة الوصف خال مدة محددة -الرجوع وسداد الثمن حال عدم التسليم يف املوعد -عدم إيفاء املدعى عليه مبا مت االتفاق عليه -املطالبة باملبلغ املدفوع -تقدمي املدعي بينة- شهادة شاهد عدل -حلف اليمن -عدم حضور املدعى عليه دون عذر -إلزام املدعى عليه غيابي ا بدفع املبلغ املدعى به -املدعى عليه على حجته متى حضر .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/5/29 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪34227273 :‬‬\n                    ‫َر ْق ُم الدعوى‪3499675 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34274574‬تاريخه‪1434/7/22:‬هـ‬\n\n\n‫عقــد وكالــة بعــوض‪ -‬اتفــاق املدعــي مــع املدعــى عليــه علــى شــراء‬\n‫املدعــى عليــه ســيارات محــددة الوصــف خــال مــدة محــددة‪ -‬الرجــوع‬\n‫وســداد الثمــن حــال عــدم التســليم يف املوعــد‪ -‬عــدم إيفــاء املدعــى عليــه‬\n‫مبــا مت االتفــاق عليــه‪ -‬املطالبــة باملبلــغ املدفــوع‪ -‬تقــدمي املدعــي بينــة‪-‬‬\n‫شــهادة شــاهد عــدل‪ -‬حلــف اليمــن‪ -‬عــدم حضــور املدعــى عليــه دون‬\n‫عــذر‪ -‬إلــزام املدعــى عليــه غيابيـ ًا بدفــع املبلــغ املدعــى بــه‪ -‬املدعــى عليــه‬\n                                                       ‫علــى حجتــه متــى حضــر ‪.‬‬\n\n\n\n\n‫‪ -1‬حديــث ابــن عبــاس رضــي اهلل عنهمــا‪( :‬أن النبــي صلــى اهلل عليــه‬\n                         ‫وســلم قضــى بشــاهد وميــن )‪ .‬أخرجــه مســلم‬\n‫‪ -2‬ذكــر ابــن قدامــة يف الــكايف (‪ )128/6‬مــا نصــه‪« :‬فــإن امتنــع اخلصــم‬\n                      ‫مــن احلضــور عنــد احلاكــم حكــم عليه‪..‬إلخ»‪.‬أ‪.‬هـ‪.‬‬\n‫‪ -3‬ذكــر أبــو إســحاق إبراهيــم بــن حســن يف معــن احلــكام مــا نصــه‪:‬‬\n‫«مســألة قــال املــاوردي يف تفســير قولــه تعالــى (وإذا دعــوا إلــى اهلل‬\n                            ‫ورســوله ليحكــم بينهــم‪ ..‬اآليــة) ‪..‬إلخ»‪.‬أ‪.‬ه ـ‬\n       ‫‪ -4‬املادة (‪ )55‬من نظام املرافعات الشرعية ولوائحها التنفيذية‪.‬‬\n\n\n\n\n                                                                                          ‫‪336‬‬\n\f      ‫ادعــى املدعــي بأنــه اتفــق مــع املدعــى عليــه علــى أن يشــتري لــه ســيارات‬\n      ‫مبواصفات مذكورة يف دعواه خالل مدة محددة وأنه إذا لم يحضرها‬\n      ‫خــال تلــك املــدة فيحــق للمدعــي الرجــوع واســتعادة الثمــن‪ ،‬وقــد ســلم‬\n      ‫ـف مبــا مت االتفــاق‬ ‫لــه مبلغــا ماليــا مقابــل ذلــك إال أن املدعــى عليــه لــم يـ ِ‬\n      ‫عليــه ولــم يقــم بشــراء الســيارات حتــى انقضــت املــدة املتفــق عليهــا‪ ،‬ولــذا‬\n      ‫طلــب إلزامــه بإعــادة املبلــغ الــذي اســتلمه منــه حــاال‪ -‬املدعــى عليــه لــم‬\n      ‫يحضــر مــع تبلغــه لغيــر شــخصه لــذا فقــد قــررت احملكمــة مواصلــة‬\n      ‫الســير يف الدعــوى غيابيــا وطلبــت مــن املدعــي البينــة علــى دعــواه‬\n      ‫فأبــرز كمبيالــة مــن املدعــى عليــه لصاحلــه تتضمــن التزامــه لــه باملبلــغ‬\n      ‫املدعــى بــه كمــا أحضــر شــاهدا واحــد ًا فشــهد بصحــة دعــوى املدعــي‬\n      ‫وجــرى تعديلــه شــرعاً‪ -‬قــررت احملكمــة توجيــه اليمــن إلــى املدعــى‬\n      ‫ا لبينتــه فأداهــا طبــق مــا طلــب‬    ‫عليــه اســتظهار ًا حلــال الغائــب وتكمي ـ ً‬\n      ‫منــه‪ -‬قضــت احملكمــة غيابيـ ًا بإلــزام املدعــى عليــه بــأن يســلم للمدعــي‬\n      ‫املبلــغ املدعــى بــه حــا ًال وهــو علــى حجتــه إذا حضــر‪ -‬تعــذر تبليــغ املدعــى‬\n      ‫عليــه باحلكــم فقــررت احملكمــة رفعــه حملكمــة االســتئناف لتدقيقــه‪-‬‬\n                              ‫قــررت محكمــة االســتئناف املوافقــة علــى احلكــم ‪.‬‬\n\n\n\n\n‫‪337‬‬\n\f‫احلمــد هلل وحــده‪ ،‬والصــاة والســام علــى مــن ال نبــي بعــده‪ ،‬وبعــد ‪:‬‬\n‫ـدي أنــا ‪ ..........‬القاضــي يف احملكمــة العامــة بالطائــف ففــي يــوم‬\n                                                                      ‫فلـ َّ‬\n‫األربعــاء ‪1434/4/25‬ه ـ افتتحــت اجللســة الســاعة التاســعة صباح ـ ًا‬\n‫لســماع دعــوى ضــد وفيهــا حضــر ‪ ....‬ســعودي اجلنســية بالســجل املدنــي‬\n‫الوكيــل الشــرعي عــن بالوكالة رقــم ‪ 33463624‬يف ‪1433/12/21‬هـ‬\n‫الصــادرة مــن كتابــة عــدل الطائــف الثانيــة والتــي تخولــه املطالبــة‬\n‫وإقامــة الدعــاوي واملرافعــة واملدافعــة وســماع الدعــاوي والــرد عليهــا‬\n‫واإلقــرار واإلنــكار والصلــح والتنــازل و إحضــار الشــهود والبينــات‬\n‫والطعــن فيهــا واإلجابــة واجلــرح والتعديــل والطعــن بالتزويــر ونفيهــا‬\n‫واالعتــراض علــى األحــكام وطلــب االســتئناف وإنهــاء مــا يلــزم حضــور‬\n‫اجللســات يف جميــع الدعــاوى لــدى جميــع احملاكــم واســتالم املبالــغ‬\n‫واســتالم صكــوك األحــكام و االســتالم والتســليم ومراجعــة جميــع‬\n‫اجلهــات ذات العالقــة وإنهــاء جميــع اإلجــراءات الالزمــة والتوقيــع فيمــا‬\n‫يتطلــب ذلــك‪ ،‬ولــم يحضــر املدعــى عليــه وال مــن ميثلــه بوكالــة شــرعية‬\n‫(( وقــد وردنــا مــن قســم شــرطة الســامة خطابهــم رقــم ‪/1308‬ع يف‬\n‫‪1434/3/15‬ه ـ املتضمــن مت البحــث عــن املذكــور باملنــزل ولــم يعثــر‬\n‫عليــه ومت تســليم الطلــب وموعــد اجللســة لذويــه باملنــزل وذلــك حســبما‬\n‫تضمــن طيــه مــن إقــرار منــدوب العمــدة )) واســتناد ًا للمــادة اخلامســة‬\n‫واخلمســن مــن نظــام املرافعــات الشــرعية رفعــت اجللســة ويف يــوم الســبت‬\n‫املوافــق ‪ 1434/04/20‬ه ـ افتتحــت اجللســة الســاعة وفيهــا حضــر‬\n‫املدعــي وكالــة ســعودي اجلنســية مبوجــب بطاقــة الهويــة الوطنيــة رقــم‬\n‫ولــم يحضــر املدعــى عليــه وال مــن ينــوب عنــه ولــم يردنــا مــا يفيــد تبلغــه‬\n                                                                                       ‫‪338‬‬\n\f      ‫باجللســة مــن عدمــه واســتنادا علــى املــادة اخلامســة واخلمســن مــن نظــام‬\n      ‫املرافعــات الشــرعية جــرى رفــع اجللســة ويف يــوم األربعــاء ‪1434/5/29‬هـ‬\n      ‫الســاعة التاســعة صباحـ ًا افتتحــت اجللســة وفيهــا حضــر املدعــي ســعودي‬\n      ‫اجلنســية مبوجــب بطاقــة الهويــة الوطنيــة رقــم ولــم يحضــر املدعــى عليــه‬\n      ‫رغــم تبلــغ ذويــه يف موعــد جلســة ســابقة حســب خطــاب مديــر مركــز‬\n      ‫شــرطة الســامة رقــم ‪/1308‬ع يف ‪1434/3/15‬ه ـ ورفــض شــقيقه‬\n      ‫اســتالم التبليــغ جللســة اليــوم حســب خطــاب مديــر مركــز شــرطة‬\n      ‫ا يف‬ ‫الســامة رقــم ‪/2159‬ع يف ‪1434/4/30‬ه ـ فادعــى املدعــي قائ ـ ً‬\n      ‫حتريــر دعــواه ‪ :‬إننــي ســلمت الغائــب املجلــس احلكــم الشــرعي‪ /‬مبلــغ‬\n      ‫وقــدره مائــة وواحــد وســبعون ألــف ريــال مقابــل أن يحضــر لــي ثــاث‬\n      ‫ســيارات مــن نــوع ‪ ....‬موديــل ‪2010‬م اســتعمال أمريكــي لونهــا ســمني‬\n      ‫يســلمني إياهــا بتاريــخ ‪1433/5/20‬ه ـ كمــا اتفقــت معــه علــى أنــه إذا‬\n      ‫لــم يحضرهــا باملوعــد احملــدد فيحــق لــي الرجــوع وإعــادة الثمــن لــي وقــد‬\n      ‫مضــت املــدة احملــدد ولــم يســلمني املدعــى عليــه أي شــيء لــذا أطلــب‬\n      ‫إلــزام املدعــى عليــه بإعــادة الثمــن لــي وقــدره مائــة وواحــد وســبعون ألــف‬\n      ‫ريــال لــي حــاالً‪ ،‬هــذه دعــواي هكــذا ادعــى املدعــي وبطلــب البينــة‬\n      ‫مــن املدعــي أبــرز لنــا كمبيالــة برقــم ‪ 41665‬بتاريــخ ‪1433/5/20‬ه ـ‬\n      ‫باســم املديــن مبلــغ الكمبيالــة مائــة وواحــد وســبعون ألــف ريــال ال غيــر‬\n      ‫كمــا أحضــر للشــهادة وأدائهــا ســعودي اجلنســية مبوجــب بطاقــة الهويــة‬\n      ‫الوطنيــة رقــم معلــم بــإدارة التربيــة والتعليــم مبحافظــة مهــد الذهــب ال‬\n      ‫ا ‪:‬أشــهد هلل تعالــى إنــه تقريبـ ًا يف‬\n                                             ‫تربطــه باملدعــي أي قرابــة وشــهد قائـ ً‬\n      ‫شــهر صفــر مــن عــام ‪1433‬ه حضــرت اجتمــاع بــن املدعــي مــع املدعــى‬\n      ‫عليــه ودفــع املدعــي للمدعــى عليــه مبلــغ قــدره مائــة وواحــد وســبعون‬\n\n\n‫‪339‬‬\n\f‫ألــف ريــال عوض ـ ًا عــن ثالثــة ســيارات فــورد ماركيــز م ‪ /2010‬بلــون‬\n‫ســمني واتفقــا علــى أن يحضــر املدعــى عليــه الســيارات للمدعي يف نهاية‬\n‫‪1433/5/20‬ه ـ وإذا لــم يحضرهــا فيحــق املطالبــة بثمــن الــذي دفعــه‬\n‫وحــرر كمبيالــة بهــذا املبلــغ وكتبهــا املدعــى عليــه بيــده هكــذا شــهد‬\n‫‪ ،‬ثــم طلبــت مــن املدعــي مزكــن لشــاهده فأحضــر للتزكيــة وأدائهــا‬\n‫ال مــن ســعودي اجلنســية بالهويــة الوطنيــة رقــم ســعودي اجلنســية‬           ‫ك ً‬\n‫مبوجــب الهويــة الوطنيــة رقــم وشــهد كل واحــد منهمــا بعدالــة الشــاهد‬\n‫وأنــه يقبــل شــهادته لــه وعليــه ثــم طلبــت مــن املدعــي اليمــن علــى صحــة‬\n‫ا ‪ /‬واهلل العظيــم الــذي ال إلــه إال هــو‬ ‫دعــواه فاســتعد بهــا وحلــف قائ ـ ً‬\n‫الــذي يعلــم اجلهــر ومــا يخفــى ويعلــم خائنــة األعــن ومــا تخفــي الصــدور‬\n‫إن املدعــى عليــه أخــذ منــي مبلــغ وقــدرة مائــة وواحــد وســبعون ألــف ريــال‬\n‫ثمنـ ًا لثــاث ســيارات مــن نــوع فــورد موديــل ‪2010‬م لــون ســمني اســتعمال‬\n‫أمريكــي يســلمها لــي يف موعــد أقصــاه ‪1433/5/20‬ه ـ واتفقــت معــه‬\n‫علــى أنــه يف حــال عــدم إحضارهــا يف املوعــد احملــدد فــإن لــي الرجــوع‬\n‫وإعــادة الثمــن لــي وقــد مضــت املــدة احملــددة ولــم يحضــر لــي الســيارات‬\n‫حتــى اآلن ولــم يعــد لــي املبلــغ ولــم أبرئــه منهــا أي شــيء واهلل واهلل واهلل‪.‬‬\n‫هكــذا حلــف فبنــاء علــى مــا تقــدم مــن الدعــوى والبينــة املعدلــة ومبــا‬\n‫أن املدعــي حلــف اليمــن التــي طلبــت منــه وملــا جــاء عــن ابــن عبــاس‬\n‫رضــي اهلل عنــه ‪( :‬أن النبــي صلــى اهلل عليــه وســلم قضــى بشــاهد وميــن‬\n‫) أخرجــه مســلم يف صحيحــه برقــم ‪ )1712( :‬ص‪ ،)711( :‬واســتنادا‬\n‫علــى املــادة اخلامســة واخلمســن مــن نظــام املرافعــات الشــرعية ولوائحهــا‬\n‫التنفيذيــة ومبــا أن املدعــى عليــه لــم يحضــر ولــم يقــدم عــذرا عــن ســبب‬\n‫عــدم احلضــور ولــم يقــدم دفاعــه علــى هــذه الدعــوى مــع أنــه تبلــغ لغيــر‬\n\n\n                                                                                        ‫‪340‬‬\n\f      ‫شــخصه يف جلســة ماضيــة ورفــض شــقيقه اســتالم التبليــغ جللســة هــذا‬\n      ‫اليــوم بهــا حســب التعليمــات ‪ ،‬وقــد ذكــر ابــن قدامــه رحمــه اهلل تعالــى‬\n      ‫يف كتابــه الــكايف ‪ 128/6‬مــا نصــه‪« :‬فــإن امتنــع اخلصــم مــن احلضــور‬\n      ‫عنــد احلاكــم حكــم عليــه ألنــه لولــم يحكــم عليــه جلعــل االمتنــاع‬\n      ‫واالســتتار طريقــا لتضييــع احلقوق»‪.‬أ‪.‬ه ـ وقــد ذكــر أبــو إســحاق إبراهيــم‬\n      ‫بــن حســن يف كتابــه معــن احلــكام علــى القضايــا واألحــكام مــا‬\n      ‫نصــه‪« :‬مســالة قــال املــاوردي يف تفســير قولــه تعالــى (وإذا دعــوا إلــى اهلل‬\n      ‫ورســوله ليحكــم بينهــم )اآليــة دليــل علــى أنــه مــن دعــي إلــى حاكــم مــن‬\n      ‫حــكام املســلمني فعليــه اإلجابــة ويحــرج إن تأخــر وقــد ورد عــن احلســن‬\n      ‫بــن علــي رضــي اهلل عنهمــا أن النبــي صلــى اهلل عليــه قــال (مــن دعــي‬\n      ‫إلــى حاكــم مــن حــكام املســلمني ولــم يجــب فهــو ظالــم ال حــق لــه «‪.‬أ‪.‬ه ـ‬\n      ‫لذلــك كلــه فقــد حكمــت بإلــزام املدعــى عليــه الغائــب عــن مجلــس‬\n      ‫احلكــم الشــرعي أن يدفــع للمدعــي مبلــغ مائــة وواحــد وســبعون ألــف‬\n      ‫ريــال حــاال هــذا مــا ظهــر لــي وبــه حكمــت ‪ ،‬واملدعــى عليــه علــى حجتــه‬\n      ‫متــى حضــر‪ ،‬وقــررت بعــث نســخة مــن صــك احلكــم للمدعــى عليــه‬\n      ‫ليقــدم اعتراضــه خــال ثالثــن يومــا مــن تاريــخ التبليــغ باحلكــم وإذا‬\n      ‫لــم يقــدم اعتراضــه خاللهــا فيســقط حقــه يف االعتــراض ويكتســب‬\n      ‫احلكــم القطعيــة‪ ،‬وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد‬\n                         ‫وعلــى آلــه وصحبــه أجمعــن‪ ،‬حــرر يف ‪1434/5/29‬هــ‪.‬‬\n      ‫ويف يــوم الســبت ‪ 1434/06/17‬ه ـ افتتحــت اجللســة الســاعة الثامنــة‬\n      ‫والنصــف صباحــا وفيهــا وردتنــا تبليــغ صــورة احلكــم مــن رئيــس قســم‬\n      ‫محضــري اخلصــوم باحملكمــة برقــم ‪ 341318618‬املتضمــن (حيــث‬\n      ‫أن املدعــى عليــه املذكــور مطلــوب يف عــدة قضايــا ومت الذهــاب إلــى‬\n\n\n‫‪341‬‬\n\f‫العنــوان املــدون أعــاه ولعــدة مــرات ولكنــه غيــر متواجــد حتــى عنــد‬\n‫تبليغــه باحلضــور للجلســات غيــر متواجــد ممــا تعــذر علينــا تســليمه اســم‬\n‫احملضــر توقيعــه) أ‪ .‬ه ـ لــذا قــررت رفعهــا حملكمــة االســتئناف لتدقيــق‬\n‫احلكــم وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                  ‫وصحبــه وســلم ‪ .‬حــرر يف ‪1434/6/17‬هــ‪.‬‬\n‫احلمــد هلل وحــده‪ ،‬والصــاة والســام علــى مــن ال نبــي بعــده‪ ،‬وبعــد ‪:‬‬\n‫ثــم عــادت املعاملــة مــن محكمــة االســتئناف مبكــة املكرمــة مصادقـ ًا‬\n‫عليهــا بالقــرار رقــم ‪ 34274574‬يف ‪1434/7/22‬ه ـ ونصــه احلمــد هلل‬\n‫والصــاة والســام علــى رســول اهلل وبعــد فقــد جــرى اطالعنــا نحــن‬\n‫رئيــس وعضــوي الدائــرة احلقوقيــة الرابعــة محكمــة االســتئناف‬\n‫مبنطقــة مكــة املكرمــة علــى الصــك الصــادر مــن فضيلــة الشــيخ ‪/‬‬\n‫القاضــي باحملكمــة العامــة بالطائــف واملســجل بعــدد ‪34227273‬‬\n‫وتاريــخ ‪1434/5/29‬ه ـ املتضمــن دعــوى ضــد‪ /‬واحملكــوم فيــه مبــا‬\n‫دون باطنــة وبدراســة الصــك وصــورة ضبطــه تقــررت املوافقــة علــي‬\n‫احلكــم وعلــى فضيلتــه مراعــاة التنبيــه املرفــق باملعاملــة وصلــى اهلل علــى‬\n‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم قاضــي اســتئناف ختــم وتوقيــع‪.‬‬\n‫قاضــي اســتئناف ختــم وتوقيــع‪ .‬رئيــس الدائــرة ختــم وتوقيــع‪ .‬وصلــى اهلل‬\n                       ‫وســلم علــى نبينــا محمــد ‪.‬حــرر يف ‪1434/8/6‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده‪ ،‬وبعــد لــدي أنــا القاضــي باحملكمــة العامــة بالطائــف‬\n‫والقائــم بعمــل املكتــب الثامــن ففــي يــوم اخلميــس ‪1435/1/11‬ه ـ‬\n‫افتتحت اجللســة الســاعة العاشــرة والنصف صباح ًا بناء على االســتدعاء‬\n‫املقــدم مــن املدعــو‪ ............ /‬واملقيــد باحملكمــة برقــم ‪342825300‬‬\n‫يف ‪1434/12/19‬ه ـ واملتضمــن رغبتــه يف التهميــش علــى الصــك رقــم‬\n\n\n                                                                                    ‫‪342‬‬\n\f      ‫ال‬\n      ‫‪ 34227273‬يف ‪1434/5/29‬هـ باســتالمه املبلغ املدون بالصك كام ً‬\n      ‫وحضــر فيهــا املدعــي وكالــة ســعودي اجلنســية مبوجــب بطاقــة الهويــة‬\n      ‫الوطنيــة رقــم بصفتــه وكيــل عــن املدعــي ســعودي مبوجــب ســجل مدنــي‬\n      ‫رقــم مبوجــب الوكالــة الصــادرة مــن كتابــة عــدل الطائــف الثانيــة برقــم‬\n      ‫‪ 33463624‬يف ‪1433/12/21‬ه ـ املتضمنــة املطالبــة وإقامــة الدعــاوي‬\n      ‫واملرافعــة واملدافعــة و اإلقــرار واالســتالم والتســليم ‪ ،‬وقــرر أنــه اســتلم‬\n      ‫كامــل املبلــغ احملكــوم بــه ضــد املدعــى عليــه بخصــوص هــذا الصــك‬\n      ‫‪ ،‬وأنــه بعــد اســتالم املبلــغ ال يطالــب املدعــى عليــه وال غيــره بشــيء‬\n      ‫بخصــوص هــذه الدعــوى‪ ،‬وبهــذا انتهــت هــذه الدعــوى‪ ،‬وبــاهلل التوفيق‪،‬‬\n                       ‫وصلــى اهلل علــى نبينــا محمــد‪ .‬حــرر يف ‪1435/1/11‬ه ـ ‪.‬‬\n\n\n\n\n‫‪343‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"8772d0b1-3c0f-5928-9c22-98c49da1913e","source_page_start":336,"source_page_end":343,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"15cd393efb027412e92b043e1b171f4287ee4d3eb9867bf6de07a60a6dbc0506","normalized_text_hash":"379c94fec16ec2d69a48ebe0d7e68119a95d779d3d567c2890d409f452994a6b","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v4-p336-34227273"},{"id":"575fa9a7-1faf-52d9-a8cc-d55de96ed2ca","document_type":"judgment","category":"judicial","subcategory":"general","title":"عقد وكالة بغير عوض -دفع املدعي للمدعى عليه مبلغ مالي مقابل استخراج تأشيرة سفر -التأشيرة مزورة -املطالبة باملبلغ- حلف املدعى عليه اليمن بتسليم مبلغ استخراج التأشيرة ملكتب خدمات عامة -ثبوت الغش والتزوير على مكتب اخلدمات -الوكيل يده يد أمانة وال ضمان عليه إال إذا تعدى أو فرط -رد الدعوى وإخاء سبيل املدعى عليه منها .","document_number":"34234533","case_number":"34183370","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة باملويه","circuit":"الدائرة احلقوقية الثالثة رقم 34278741","issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/6/7","year":"1434","subject":"عقد وكالة بغير عوض -دفع املدعي للمدعى عليه مبلغ مالي مقابل استخراج تأشيرة سفر -التأشيرة مزورة -املطالبة باملبلغ- حلف املدعى عليه اليمن بتسليم مبلغ استخراج التأشيرة ملكتب خدمات عامة -ثبوت الغش والتزوير على مكتب اخلدمات -الوكيل يده يد أمانة وال ضمان عليه إال إذا تعدى أو فرط -رد الدعوى وإخاء سبيل املدعى عليه منها .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫تاريخه‪1434/6/7 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪34234533 :‬‬\n                   ‫َر ْق ُم الدعوى‪34183370 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n            ‫‪ 34311444‬تاريخه‪1434/9/2:‬هـ‬\n\n\n‫عقــد وكالــة بغيــر عــوض‪ -‬دفــع املدعــي للمدعــى عليــه مبلــغ مالــي‬\n‫مقابــل اســتخراج تأشــيرة ســفر‪ -‬التأشــيرة مــزورة‪ -‬املطالبــة باملبلــغ‪-‬‬\n‫حلــف املدعــى عليــه اليمــن بتســليم مبلــغ اســتخراج التأشــيرة ملكتــب‬\n‫خدمــات عامــة‪ -‬ثبــوت الغــش والتزويــر على مكتب اخلدمــات‪ -‬الوكيل‬\n‫يــده يــد أمانــة وال ضمــان عليــه إال إذا تعــدى أو فــرط‪ -‬رد الدعــوى‬\n                                       ‫وإخــاء ســبيل املدعــى عليــه منهــا ‪.‬‬\n\n\n\n\n‫‪ -1‬الوكيــل يــده يــد أمانــة باتفــاق الفقهــاء وال ضمــان عليــه إال إذا‬\n‫تعــدى أو فــرط ويــد األمانــة يترتــب عليهــا أن يكــون القــول قــول األمــن‬\n‫مــع ميينــه يف دفــع الضمــان عــن نفســه‪ .‬انظــر املوســوعة الفقهيــة‬\n                                                         ‫الكويتيــة (‪.)86/45‬‬\n‫‪ -2‬املــواد (‪ )176‬و(‪ )178‬مــن نظــام املرافعــات الشــرعية ولوائحــه‬\n                                                                 ‫ا لتنفيذ يــة ‪.‬‬\n\n\n\n\n‫ادعــى املدعــي بأنــه ســلم املدعــى عليــه مبلغــا مالي ـ ًا وطلــب منــه أن‬\n‫يســتخرج تأشــيرة لزوجــة أخيــه بعــد أن علــم بأنــه ســيذهب الســتخراج‬\n‫تأشــيرة لزوجتــه عــن طريــق أحــد مكاتــب اخلدمــات العامــة ثــم بعــد أن‬\n\n                                                                                   ‫‪344‬‬\n\f      ‫مت اســتخراج التأشــيرة تبــن أنهــا مــزورة‪ ،‬ولــذا فقــد طلــب إلــزام املدعــى‬\n      ‫عليــه بإعــادة ذلــك املبلــغ الــذي ســلمه لــه‪ -‬أقــر املدعــي باســتالم املبلــغ‬\n      ‫املذكــور ودفــع بأنــه ســلمه إلــى مكتــب اخلدمــات املذكــور كمــا طلب‬\n      ‫منــه املدعــي إال أن املكتــب قــام بخداعهمــا وأصــدر لهمــا تأشــيرات‬\n      ‫مــزورة وقــد قــدم ضــده شــكوى لــدى اجلهــات املختصــة ولذلــك فهــو غيــر‬\n      ‫مســتعد بإعــادة املبلــغ‪ -‬قــررت احملكمــة توجيــه اليمــن إلــى املدعــى‬\n      ‫عليــه علــى صحــة مــا دفــع بــه فأداهــا طبــق مــا طلــب منــه‪ -‬الوكيــل يــده‬\n      ‫يــد أمانــة وال ضمــان عليــه إال إذا تعــدى أو فــرط فيقبــل قولــه مــع ميينــه يف‬\n      ‫دفــع الضمــان عــن نفســه‪ -‬قضــت احملكمــة بــرد دعــوى املدعــي وأخلــت‬\n      ‫ســبيل املدعــى عليــه منهــا‪ -‬قنــع املدعــى عليــه باحلكــم وعــارض عليــه‬\n                 ‫املدعــي‪ -‬قــررت محكمــة االســتئناف املوافقــة علــى احلكــم ‪.‬‬\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ........‬رئيــس احملكمــة العامــة باملويــه‬\n      ‫وبنــاء علــى املعاملــة الــواردة لنــا مــن قســم اإلحــاالت برقــم ‪34183370‬‬\n      ‫وتاريــخ ‪ 1434/04/21‬ه ـ املقيــدة باحملكمــة برقــم ‪ 34978975‬وتاريــخ‬\n      ‫‪ 1434/04/21‬ه ـ ففــي يــوم األحــد املوافــق ‪1434/05/26‬ه ـ افتتحــت‬\n      ‫اجللســة الســاعة ‪ 08 : 30‬وفيها حضر ‪ .......‬باكســتاني اجلنســية مبوجب‬\n      ‫اإلقامــة رقــم واملدعــى عليه ‪ .......‬باكســتاني اجلنســية حامل االقامة رقم‬\n      ‫والــذي يجيــد اللغــة العربيــة واملترجــم باكســتاني اجلنســية مســلم الديانة‬\n      ‫اقامــة رقــم وادعــى املدعــي عــن طريــق املترجــم قائــا يف دعــواه انــه يف‬\n      ‫تاريــخ ‪1434/2/3‬ه ـ اتفقــت مــع املدعــى عليــه علــى أن يســتخرج تأشــيرة‬\n      ‫لزوجــة أخــي لكونــي علمــت أنــه ســوف يذهــب إلــى الريــاض الســتخراج‬\n\n‫‪345‬‬\n\f‫تأشــيرة لزوجتــه وأخبرنــي بذلــك مــن يعمــل بجــوار محــل املدعــى عليــه‬\n‫وهــو مهنــدس األجهــزة الكهربائيــة واســمه وجنســيته باكســتاني وبعــد‬\n‫أســبوع ســلمت املدعــى عليــه مبلــغ وقــدره اثنــا عشــر ريــال‪ 12000‬وبعــد‬\n‫يومــن اتصــل بــي ليــا وأخبرنــي بأنــه مت اســتخراج التأشــيرة وأنــه ســلم‬\n‫املبلــغ للمكتــب وأرســل لــي رقــم التأشــيرة وقــال ســوف أحضــر غــدا‬\n‫وأســلمك ورقــة التأشــيرة ويف الصبــاح قمــت بتســليم الرقــم لصديــق لــي‬\n‫يدعــى ‪ ......‬يعمــل يف كهربــاء املويــه وقــام بإدخــال الرقــم علــى شــبكة‬\n‫اإلنترنــت ولــم يخــرج أي نتيجــة فأخبــرت املدعــى عليــه بذلــك فقــال‬\n‫بــل التأشــيرة صحيحــة وأرســلها لباكســتان كمــا قــام املدعــى عليــه‬\n‫بتســليمي الورقــة الصفــراء اخلاصــة بالتأشــيرة وســلمتها ألخــي ‪......‬‬\n‫مبكــة فأرســلها بالفاكــس لباكســتان فقــام أخــي الثالــث ويدعــى‬\n‫‪ ......‬فذهــب لســفارة الســعودية بباكســتان فقالــوا لــه إن التأشــيرة‬\n‫مــزورة وأنــا اآلن اطلــب املدعــى عليــه تســليمي املبلــغ الــذي دفعتــه لــه‬\n‫وقــدره اثنــا عشــر ألــف ‪ 12000‬لكــون التأشــيرة مــزورة‪ ،‬وبعــرض‬\n‫الدعــوى علــى املدعــى عليــه قــال مــا ذكــره املدعــي صحيــح كلــه جملــة‬\n‫وتفصيــا ماعــدا قولــه انــه اتصــل بــي صباحــا واخبرنــي أن الرقــم غيــر‬\n‫صحيــح بــل إن ‪ ......‬أخبرنــي بأنــه ال يعــرف الدخــول ملوقــع وزارة اخلارجيــة‬\n‫الســعودية كمــا أخبرنــي املدعــي بــأن أخــاه ‪ ......‬تأكــد مــن التأشــيرة‬\n‫يف مكــة فوجدهــا صحيحــة وأنــا لســت مســتعدا بإرجــاع هــذا املبلــغ ألن‬\n‫املكتــب الــذي تعاملــت معــه غشــني وغــش املدعــى عليــه وقــد شــكيته‬\n‫لــدى شــرطة املربــع بالريــاض ورقــم املعاملــة ‪ ........‬يف ‪1434/2/24‬ه ـ‬\n‫واســم صاحــب املكتــب ‪ .....‬واســم املكتــب ‪ .....‬للخدمــات العامــة وقــد‬\n‫وكلــت شــخص ًا علــى شــكايته ومكتبــه مغلــق وبالفعــل ابــرز صــورة‬\n\n\n                                                                                    ‫‪346‬‬\n\f      ‫وكالــة صــادرة مــن هــذه احملكمــة برقــم ‪ 34413900‬يف ‪1434/4/6‬هـ‬\n      ‫املتضمنــة ( وقــد مت اإلقــرار بتوكيــل ســعودي اجلنســية ســجل مدنــي رقــم‬\n      ‫فيمــا يخــص اجلهــات احلكوميــة وذلــك يف مراكــز الشــرطة ملراجعــة‬\n      ‫احلقــوق يف شــرطة املربــع بالريــاض الســتالم جميــع مســتحقاتي املاليــة‬\n      ‫‪-‬االســتالم والتســليم‪ -‬ومراجعــة جميــع اجلهــات ذات العالقــة وإنهــاء‬\n      ‫جميــع اإلجــراءات الالزمــة والتوقيــع فيمــا يتطلــب ذلــك ) انتهــى كمــا‬\n      ‫ابــرز صــورة ورقــة باســم تذكــرة مراجعــة تأشــيرات لإلقامــة اســتقدام‬\n      ‫الريــاض وعليهــا شــعار وزارة الداخليــة اإلدارة العامــة لشــؤون الوافديــن‬\n      ‫إدارة شــؤون االســتقدام رقــم الصــادر يف ‪1434/2/16‬ه ـ املتضمنــة‬\n      ‫(حيــث تقــرر املوافقــة علــى طلــب رقــم صاحــب العمــل) انتهــى وبســؤال‬\n      ‫املدعــي عــن التأشــيرة ورقمهــا ابــرز صــورة ورقــة باســم تذكــرة مراجعــة‬\n      ‫تأشــيرات لإلقامــة اســتقدام الريــاض وعليهــا شــعار وزارة الداخليــة‬\n      ‫اإلدارة العامــة لشــؤون الوافديــن إدارة شــؤون االســتقدام رقــم الصــادر‬\n      ‫يف ‪1434/2/16‬ه ـ املتضمنــة (حيــث تقــرر املوافقــة علــى طلــب رقــم‬\n      ‫صاحــب العمــل) انتهــى وبعــرض صــورة التأشــيرة علــى املدعــى عليــه‬\n      ‫قــال نعــم هــذه صورتهــا ويف جلســة أخــرى حضــر املتداعيــان وحضــر‬\n      ‫حلضورهمــا املترجــم باكســتاني اجلنســية مبوجــب اإلقامــة رقــم ثــم‬\n      ‫جــرى ســؤالي للمدعــي عــن طريــق املترجــم هــل اتفقــت مــع املدعــى‬\n      ‫عليــه علــى مبلــغ مالــي مقابــل إصــدار التأشــيرة املذكــورة بالدعــوى‬\n      ‫فأجــاب عــن طريــق املترجــم بـ ــا ثــم ســألته هــل تريــد ميينــه علــى انــه‬\n      ‫ســلم املبلــغ للمكتــب الــذي قــام باســتخراج التأشــيرة ولــم يســتخدمه‬\n      ‫يف شــيء غيــره وانــه لــم يســتلم املبلــغ بعــد ذلــك وال شــيء منــه فقــال‬\n      ‫ال فطلبــت أنــا مــن املدعــى عليــه احللــف علــى ذلــك بعــد حتذيــري لــه‬\n\n\n‫‪347‬‬\n\f‫بخطــر اليمــن ان كانــت كاذبــة فأصــر فأذنــت لــه فحلــف قائــا واهلل‬\n‫العظيــم أننــي ســلمت املبلــغ الــذي ســلمنيه املدعــي وقــدره اثنــا عشــر‬\n‫ألــف ريــال‪ 12000‬الســتخراج تأشــيرة لزوجــة أخيــه إلــى موظــف ســعودي‬\n‫مبكتــب للخدمــات العامــة ولــم اســتخدمه يف شــيء غيــره وال اســتلم‬\n‫املبلــغ بعــد ذلــك وال شــيء منــه واهلل العظيــم فبنــاء علــى مــا ســبق مــن‬\n‫الدعــوى واإلجابــة وملصادقــة املدعــى عليــه علــى دعــوى املدعــي ولكــون‬\n‫املدعــي يدعــي بــان املدعــى عليــه اصــدر لــه تأشــيرة مــزورة ولكــون‬\n‫املدعــى عليــه يف املعاملــة احلاصلــة بينهمــا عبــارة عــن وكيــل ولكــون‬\n‫املدعــى عليــه دفــع بــأن تأشــيرته اخلاصــة بــه والصــادرة لزوجتــه مــزورة‬\n‫أيضــا بســبب غــش مكتــب اخلدمــات العامــة لــه ولكونــه قــام مبــا طلــب‬\n‫منــه املدعــي ولكــون الغــش مــن عدمــه ليــس مــن شــأن املدعــى عليــه وال‬\n‫بســببه بــل بســبب صاحــب املكتــب وهــذا ليــس تعديــا وال تفريطــا منــه‬\n‫ولكــون الوكيــل يــده يــد أمانــة باتفــاق الفقهــاء وأنــه ال ضمــان عليــه إال‬\n‫إذا تعــدى أو فــرط وملــا قــرره الفقهــاء مــن أن يــد األمانــة يترتــب عليهــا أن‬\n‫يكــون القــول قــول األمــن مــع ميينــه يف دفــع الضمــان عــن نفســه انظــر‬\n‫ذلــك كلــه يف املوســوعة الفقهيــة الكويتيــة (‪ )86/45‬وحللــف املدعــى‬\n‫عليــه اليمــن املطلوبــة بطلبــي وبعــد اذنــي وحتذيــري لــه مــن خطرهــا ان‬\n‫كانــت كاذبــة بعــد ان قــرر املدعــي رفضهــا لذلــك كلــه فقــد رددت‬\n‫دعــوى املدعــي وأخليــت ســبيل املدعــى عليــه منهــا هــذا مــا ظهــر لــي وبــه‬\n‫حكمــت وبعرضــه علــى الطرفــن قــرر املدعــي عــدم القناعــة ورغــب‬\n‫بتقــدمي الئحــة اعتراضيــه وبعرضــه علــى املدعــى عليــه قــرر قناعتــه‬\n‫باحلكــم وقــررت تنظيــم صــك هــذا اليــوم وجــرى تســليم املعتــرض نســخة‬\n‫منــه هــذا اليــوم وأفهمتــه بــأن لــه مهلــة ثالثــون يومـ ًا لتقــدمي مــا لديــه مــن‬\n\n\n                                                                                             ‫‪348‬‬\n\f      ‫اعتــراض علــى احلكــم واذا انتهــت هــذه املهلــة ولــم يتقــدم بشــي فيســقط‬\n      ‫ـاء علــى املادتــن‬\n                        ‫حقــه يف طلــب التمييــز ويكتســب احلكــم القطعيــة بنـ ً‬\n      ‫السادســة والســبعني بعــد املائــة والثامنــة والســبعني بعــد املائــة مــن نظــام‬\n      ‫املرافعــات الشــرعية ولوائحــه التنفيذيــة وقــد كانــت جميــع أســئلتي‬\n      ‫للمدعــي وأجوبتــه واإلفهــام عــن طريــق املترجــم وأغلقــت اجللســة الســاعة‬\n      ‫الثامنــة والنصــف‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                      ‫وســلم ‪ .‬حــرر يف ‪1434/6/7‬هــ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ففــي يــوم األحــد ‪ 1434/08/21‬ه ـ افتتحــت‬\n      ‫اجللســة الســاعة الثامنــة وقــد عــادت املعاملــة مــن فضيلــة رئيــس محكمة‬\n      ‫االســتئناف مبنطقــة مكــة املكرمــة املكلــف رقــم ‪341667730‬‬\n      ‫بتاريــخ ‪1434/7 /30‬ه ـ وبرفقهــا قــرار أصحــاب الفضيلــة قضــاة‬\n      ‫الدائــرة احلقوقيــة الثالثــة رقــم ‪ 34278741‬بتاريــخ ‪1434/7/25‬ه ـ‬\n      ‫وفيــه (وبدراســة احلكــم وصــورة ضبطــه والئحتــه االعتراضيــة تقــرر‬\n      ‫باألكثريــة إعادتهــا لفضيلتــه إلدخــال املكتــب طــرف ثالــث حســب‬\n      ‫النظــام وفــق اهلل اجلميــع للصــواب ) انتهــى وعليــه أجيــب صاحبــي‬\n      ‫الفضيلــة وفقنــي اهلل وإياهــم لــكل خيــر أوال بــأن طلــب اإلدخــال الــوارد‬\n      ‫يف النظــام طلــب جــوازي وثانيــا أن املكتــب غيــر معــروف لدينــا املعرفــة‬\n      ‫التــي متكــن احملكمــة نظامــا مــن تبليغــه والداللــة عليــه وكل مــا لــدى‬\n      ‫املدعــى عليــه ورقــة عاديــة مصــورة حتمــل اســم املكتــب ولــم يتبــن فيهــا‬\n      ‫ال رقــم ترخيصــه وال غيــره ويف هــذا تطويــل للدعــوى ومضــارة للقاضــي‬\n      ‫يف اســتقصاء ذلــك كلــه وقــررت رفــع املعاملــة إلــى محكمة االســتئناف‬\n      ‫وعليــه أغلقــت اجللســة الســاعة الثامنــة والنصــف وصلــى اهلل علــى نبينــا‬\n                    ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/8/21‬ه ـ‬\n\n\n‫‪349‬‬\n\f‫احلمــد هلل وحــده وبعــد ففــي يــوم الثالثــاء ‪ 1434/10/6‬ه ـ افتتحــت‬\n‫اجللســة الســاعة التاســعة والنصــف وقــد عــادت املعاملــة مــن فضيلــة‬\n‫رئيــس محكمــة االســتئناف مبنطقــة مكــة املكرمــة املكلــف برقــم‬\n‫‪ 341021262‬بتاريــخ ‪1434/9/13‬ه ـ وبرفقهــا قــرار أصحــاب الفضيلــة‬\n‫قضــاة الدائــرة احلقوقيــة الثالثــة رقــم ‪ 34311444‬بتاريــخ ‪1434/9/2‬ه ـ‬\n‫ونــص احلاجــة منــه ( بدراســة احلكــم وصــورة ضبطــه والئحتــه‬\n‫االعتراضيــة تقــررت املوافقــة علــى احلكــم بعــد اإلجــراء األخيــر ) انتهــى‬\n‫وعليــه أغلقــت اجللســة الســاعة العاشــرة وصلــى اهلل علــى نبينــا محمــد‬\n                         ‫وعلــى الــه وصحبــه وســلم حــرر ‪1434/10/6‬ه ـ ‪.‬‬\n\n\n\n\n                                                                                   ‫‪350‬‬\n\f                     ‫كشاف املوضوعات‬\n\n‫الصفحة‬                     ‫املوضوع‬                      ‫التصنيف‬   ‫م‬\n\n\n          ‫مطالبة املدعي للمدعى عليه بسداد القرض‬\n  ‫‪5‬‬                                                      ‫قرض‬      ‫‪1‬‬\n                    ‫الذي أقرضه إياه‬\n\n\n           ‫مطالبة املدعي للمدعى عليها بسداد باقي‬\n  ‫‪23‬‬                                                     ‫قرض‬      ‫‪2‬‬\n           ‫القرض الذي أقرضه إياها مورث املدعي‬\n\n\n          ‫مطالبة املدعية للمدعى عليه بسداد القرض‬\n  ‫‪28‬‬      ‫الذي أقرضته إياه مستندة على إقرار خطي‬          ‫قرض‬      ‫‪3‬‬\n                   ‫منسوب للمدعى عليه‬\n\n\n          ‫مطالبة املدعي للمدعى عليه بسداد القرض‬\n  ‫‪33‬‬      ‫الذي أقرضه إياه واتفقا على تسديده بثالث‬        ‫قرض‬      ‫‪4‬‬\n                  ‫دفعات ولم يسدد أي ًا منها‬\n\n\n           ‫مطالبة املدعي للمدعى عليه بسداد القرض‬\n  ‫‪40‬‬     ‫الذي أقرضه إياه بينما اعترض املدعى عليه بأن‬     ‫قرض‬      ‫‪5‬‬\n                ‫املبلغ كان للمتاجرة وليس قرضاً‪.‬‬\n\n\n          ‫مطالبة املدعي للمدعى عليه بسداد القرض‬\n  ‫‪45‬‬       ‫الذي أقرضه إياه ولتخلف املدعى عليه عن‬         ‫قرض‬      ‫‪6‬‬\n          ‫احلكم مت التنويه بأنه على حجته متى حضر‬\n\n\n           ‫مطالبة املدعي للمدعى عليه بسداد القرض‬\n         ‫الذي أقرضه إياه بينما اعترض املدعى عليه بأن‬\n  ‫‪50‬‬     ‫املبلغ ليس قرض ًا بل كان مقابل تنازله للمدعي‬    ‫قرض‬      ‫‪7‬‬\n          ‫عن قطعة أرض وإشرافه على عمارته القائمة‬\n                        ‫على تلك األرض‬\n\f‫الصفحة‬                      ‫املوضوع‬                       ‫التصنيف‬   ‫م‬\n\n\n          ‫مطالبة املدعي للمدعى عليه بسداد القرض‬\n         ‫الذي أقرضه لطرف ثالث وضمنه املدعى عليه‬\n  ‫‪57‬‬                                                       ‫قرض‬      ‫‪8‬‬\n         ‫فيما بقي من املبلغ حيث اختفى الطرف الثالث‬\n                      ‫وال يعرف له مكان‬\n\n\n          ‫مطالبة املدعي للمدعى عليه بسداد القرض‬\n  ‫‪63‬‬                                                       ‫قرض‬      ‫‪9‬‬\n          ‫الذي أقرضه إياه بشيك قام بصرفه من البنك‬\n\n\n         ‫مطالبة املدعي للمدعى عليه بسداد املبلغ املالي‬\n          ‫الذي أعطاه إياه للمضاربة به مع األرباح بينما‬\n  ‫‪68‬‬                                                       ‫قرض‬      ‫‪10‬‬\n           ‫اعترض املدعى عليه بأن املبلغ كان مقابل‬\n         ‫قرض حسن سبق أن أعطاه املدعى عليه للمدعي‬\n\n\n         ‫مطالبة املدعي للمدعى عليه بسداد املبلغ املالي‬\n  ‫‪72‬‬      ‫الذي قام املدعى املدعي بسداده عنه لطرف‬           ‫قرض‬      ‫‪11‬‬\n                 ‫ثالث لكونه ضامنا له ولم يسدد‬\n\n\n         ‫مطالبة املدعية للمدعى عليه بسداد املبلغ املالي‬\n         ‫الذي قام باقتراضه من مورثها وسدد جزء منه‬\n  ‫‪79‬‬                                                       ‫قرض‬      ‫‪12‬‬\n          ‫حال حياته وقام بأداء اليمني على ذلك لرفض‬\n                          ‫املدعية أداء اليمني‬\n\n\n           ‫مطالبة املدعي للمدعى عليه بسداد القرض‬\n  ‫‪89‬‬     ‫الذي أقرضه إياه بينما اعترض املدعى عليه بأن‬       ‫قرض‬      ‫‪13‬‬\n                   ‫مهلة السداد لم تنتهي بعد‬\n\n\n           ‫مطالبة املدعي للمدعى عليه بسداد القرض‬\n  ‫‪93‬‬                                                       ‫قرض‬      ‫‪14‬‬\n           ‫الذي أقرضه إياه وأنكر املدعى عليه ذل‬\n\f‫الصفحة‬                     ‫املوضوع‬                     ‫التصنيف‬   ‫م‬\n\n\n          ‫مطالبة املدعي للمدعى عليه بسداد القرض‬\n         ‫الذي أقرضه إياه وكتب له سند ًا بناء على ذلك‬\n ‫‪100‬‬                                                    ‫قرض‬      ‫‪15‬‬\n         ‫حيث سبق أن صدر به قرار من مكتب الفصل‬\n                         ‫باألوراق التجارية‬\n\n\n           ‫مطالبة املدعي للمدعى عليه بسداد القرض‬\n ‫‪113‬‬       ‫الذي أقرضه إياه وقدم بينة على ذلك شاهد‬       ‫قرض‬      ‫‪16‬‬\n                           ‫وميينه‬\n\n\n           ‫مطالبة املدعي للمدعى عليه بسداد القرض‬\n            ‫الذي أقرضه إياه واعترض املدعي أن املبلغ‬\n ‫‪117‬‬                                                    ‫قرض‬      ‫‪17‬‬\n         ‫املذكور لم يكن وإمنا كان مقابل عدة مشاريع‬\n                         ‫يف مجال اإلنشاء‬\n\n\n           ‫مطالبة املدعية للمدعى عليه بسداد القرض‬\n ‫‪128‬‬        ‫الذي أقرضته إياه عندما قامت ببيع صوري‬       ‫قرض‬      ‫‪18‬‬\n         ‫للذهب اخلاص بها لسداد بعض الديون التي عليه‬\n\n\n           ‫مطالبة املدعي بإثبات إعساره مع أن الديون‬\n ‫‪139‬‬     ‫اخلاصة به مترتبة على أفعال مجرمة ‪،‬وهي مما‬      ‫إعسار‬    ‫‪19‬‬\n                  ‫ال ينظر فيها دعوى اإلعسار‬\n\n\n           ‫مطالبة املدعي بإثبات إعساره وثبوت ذلك‬\n ‫‪145‬‬      ‫لكون الدين لزمه بغير اختياره وأدى اليمني‬      ‫إعسار‬    ‫‪20‬‬\n                           ‫على ذلك‬\n\n\n          ‫مطالبة املدعي بإثبات إعساره وثبوت ذلك بناء‬\n ‫‪154‬‬                                                    ‫إعسار‬    ‫‪21‬‬\n                      ‫على شهادة الشهود‬\n\f‫الصفحة‬                     ‫املوضوع‬                     ‫التصنيف‬   ‫م‬\n\n\n          ‫مطالبة املدعي بإثبات إعساره وثبوت ذلك بناء‬\n ‫‪163‬‬                                                    ‫إعسار‬    ‫‪22‬‬\n                ‫على شهادة الشهود وميينه على ذلك‬\n\n\n         ‫مطالبة املدعي بإثبات إعساره وعدم إثبات ذلك‬\n ‫‪173‬‬     ‫لكون الدين املستحق عليه ناجت عن عملية نصب‬      ‫إعسار‬    ‫‪23‬‬\n            ‫واحتيال أدين بها بحكم شرعي سابق‬\n\n\n          ‫مطالبة املدعي بإثبات إعساره وثبوت ذلك بناء‬\n ‫‪177‬‬                                                    ‫إعسار‬    ‫‪24‬‬\n                      ‫على شهادة الشهود‬\n\n\n          ‫مطالبة املدعي بإثبات إعساره بناء على دين‬\n ‫‪184‬‬     ‫مستحق يف ذمته صادر به حكم شرعي وثبوت‬           ‫إعسار‬    ‫‪25‬‬\n                ‫ذلك بناء على شهادة الشهود‬\n\n\n          ‫مطالبة املدعي بإثبات إعساره بناء على حداث‬\n ‫‪189‬‬     ‫مروري نتج عنه وفاة مورث املدعى عليهما وثبوت‬    ‫إعسار‬    ‫‪26‬‬\n                  ‫ذلك بناء على شهادة الشهود‬\n\n\n         ‫مطالبة املدعي بإثبات إعساره باإلضافة لوجود‬\n ‫‪195‬‬     ‫غرماء كثر غير املدعى عليهم وثبوت ذلك بناء‬      ‫إعسار‬    ‫‪27‬‬\n                      ‫على شهادة الشهود‬\n\n\n          ‫مطالبة املدعي بإثبات إعساره وإنكار املدعى‬\n ‫‪205‬‬      ‫عليه لذلك وإقراره بأنه مليء دون إحضار بينة‬    ‫إعسار‬    ‫‪28‬‬\n         ‫على ذلك وثبوت إعساره بناء على شهادة الشهود‬\n\n\n          ‫مطالبة املدعي بإثبات إعساره وثبوت ذلك بناء‬\n ‫‪210‬‬                                                    ‫إعسار‬    ‫‪29‬‬\n                      ‫على شهادة الشهود‬\n\f‫الصفحة‬                       ‫املوضوع‬                       ‫التصنيف‬     ‫م‬\n\n\n            ‫مطالبة املدعي بإثبات إعساره مع عدم علم‬\n ‫‪216‬‬      ‫املدعى عليه بذلك وثبوت ذلك بناء على شهادة‬         ‫إعسار‬      ‫‪30‬‬\n                           ‫الشهود‬\n\n\n          ‫مطالبة املدعي بإثبات إعساره وثبوت ذلك بناء‬\n ‫‪223‬‬                                                        ‫إعسار‬      ‫‪31‬‬\n                      ‫على شهادة الشهود‬\n\n\n          ‫مطالبة املدعي بإثبات إعساره ورد ذلك لكون‬\n ‫‪229‬‬                                                        ‫إعسار‬      ‫‪32‬‬\n            ‫الديون ناجتة عن سرقات قام بها املدعي‬\n\n\n          ‫مطالبة املدعي بإثبات إعساره ورد ذلك لثبوت‬\n ‫‪235‬‬                                                        ‫إعسار‬      ‫‪33‬‬\n                           ‫احتياله‬\n\n\n            ‫مطالبة املدعي بإثبات إعساره وثبوت ذلك‬\n ‫‪244‬‬                                                        ‫إعسار‬      ‫‪34‬‬\n                        ‫بشهادة الشهود‬\n\n\n          ‫مطالبة املدعي بإثبات إعساره لتقاعده وعدم‬\n ‫‪249‬‬                                                        ‫إعسار‬      ‫‪35‬‬\n            ‫قدرته على النفقة املتقررة عليه لوالده‬\n\n\n          ‫مطالبة املدعي بإثبات إعساره وعاقلته وثبوت‬\n ‫‪254‬‬                                                        ‫إعسار‬      ‫‪35‬‬\n                     ‫ذلك بشهادة الشهود‬\n\n\n             ‫مطالبة املدعي ببراءة ذمته من املديونية ألحد‬\n ‫‪263‬‬                                                       ‫براءة ذمة‬   ‫‪36‬‬\n          ‫مقدمي اخلدمة على العقار الذي اشتراه مؤخر ًا‬\n\n\n         ‫مطالبة أم ابن زوجها بفسخ واليته عن أخيه الذي‬\n ‫‪273‬‬       ‫هو ابن املدعية وجعلها للمدعية ألنها األحق‬         ‫والية‬     ‫‪37‬‬\n                            ‫بالوالية‬\n\f‫الصفحة‬                      ‫املوضوع‬                       ‫التصنيف‬         ‫م‬\n\n\n            ‫مطالبة املدعية أبيها الغائب بإسقاط والية‬\n ‫‪280‬‬                                                         ‫والية‬        ‫‪38‬‬\n                 ‫التزويج عنه لغيبته وجعلها ألخيها‬\n\n\n         ‫مطالبة أم بفسخ والية األوصياء املعينني من والد‬\n ‫‪285‬‬                                                         ‫والية‬        ‫‪39‬‬\n                    ‫القصر وجعلها للمدعية‬\n\n\n             ‫مطالبة اجلدة الم بإلغاء والية اجلد ألب على‬\n           ‫القصر من أوالد ابنتها وجعلها لها ألن املدعى‬\n                       ‫عليه كبير يف السن‬\n            ‫وال يستطيع القيام بأعباء الوالية وأنه أصدر‬\n ‫‪309‬‬                                                         ‫والية‬        ‫‪40‬‬\n                      ‫وكالة البنه الذي هو‬\n         ‫عم األوالد للقيام بشؤون القصر وأن املدعى عليه‬\n                        ‫ووكيله لم يقوما‬\n                    ‫بأي شيء جتاه القاصرين‬\n\n\n ‫‪319‬‬          ‫مطالبة االبن باحلجر على والده لسفهه‬         ‫حجر ل َِس َفه‬   ‫‪41‬‬\n\n\n          ‫مطالبة املدعي للمدعى عليه بإعادة املبلغ الذي‬\n ‫‪331‬‬                                                        ‫وكالة‬         ‫‪42‬‬\n                     ‫سلمه له ليشتري له سيارة‬\n\n\n          ‫مطالبة املدعي للمدعى عليه بإعادة املبلغ الذي‬\n ‫‪336‬‬      ‫سلمه له ليشتري له سيارات خالل مدة معينة‬           ‫وكالة‬         ‫‪43‬‬\n                        ‫لكونه لم يقم بذلك‬\n\n\n         ‫مطالبة املدعي للمدعى عليه بإعادة املبلغ الذي‬\n ‫‪344‬‬     ‫سلمه له ليستخرج له تأشيرة سفر لزوجته حيث‬           ‫وكالة‬         ‫‪44‬‬\n              ‫تبني أن التأشيرة املستخرجة مزورة‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"8772d0b1-3c0f-5928-9c22-98c49da1913e","source_page_start":344,"source_page_end":356,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"bf1a6e3a5458bccb49a1f16c584db8c31f3306cf2549118f8de645c8c503984b","normalized_text_hash":"6fb9677b07aad5a92710d8c82966a0c98eb3f6f2ac17f1bde5cd95bc3be572b1","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v4-p344-34234533"}]$archive_payload$::jsonb) AS x LIMIT 25
